INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市 quán shì：整个城市，指城里的全体人或整体。"}, {"text": "拳师", "is_correct": false, "explanation": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。"}, {"text": "全诗", "is_correct": false, "explanation": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。"}, {"text": "全史", "is_correct": false, "explanation": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}], "explanations": {"全市": "全市 quán shì：整个城市，指城里的全体人或整体。", "拳师": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。", "全诗": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。", "全史": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}, "sentence_index": null, "correct_answer": "全市"}, "level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指城里的全体人，符合“都在看比赛”的语境。"}, {"text": "全身", "is_correct": false, "explanation": "语义：“全身”指人或动物的整个身体，不指城里的人群。"}, {"text": "全书", "is_correct": false, "explanation": "语义：“全书”指一本书，不能指看比赛的人。"}, {"text": "全天", "is_correct": false, "explanation": "搭配：“全天”说的是时长，不能用来修饰表示人群的名词。"}], "explanations": {"全市": "全市指城里的全体人，符合“都在看比赛”的语境。", "全身": "语义：“全身”指人或动物的整个身体，不指城里的人群。", "全书": "语义：“全书”指一本书，不能指看比赛的人。", "全天": "搭配：“全天”说的是时长，不能用来修饰表示人群的名词。"}, "sentence_index": 0, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我全市都在发抖。", "explanation": "这里应该用〈全身〉。〈全市〉指整座城市，不能用来指一个人的身体。"}, {"text": "这本书全市共有十章。", "explanation": "这里应该用〈全书〉。〈全市〉指城市，不能用来指一本书的范围。"}, {"text": "我全市都在复习。", "explanation": "这里应该用〈全天〉。〈全市〉指城市的范围，不能用来表示一整天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指整座城市，消息可以传遍全市，符合句子的语境。"}, {"text": "全年", "is_correct": false, "explanation": "语义：“全年”指一整年，消息不会“传遍”一整年。"}, {"text": "全页", "is_correct": false, "explanation": "语义：“全页”指一张纸的整页，消息不能传遍一页纸。"}, {"text": "全程", "is_correct": false, "explanation": "搭配：“全程”说的是行程的整段，不能用来指消息传播的范围。"}], "explanations": {"全市": "全市指整座城市，消息可以传遍全市，符合句子的语境。", "全年": "语义：“全年”指一整年，消息不会“传遍”一整年。", "全页": "语义：“全页”指一张纸的整页，消息不能传遍一页纸。", "全程": "搭配：“全程”说的是行程的整段，不能用来指消息传播的范围。"}, "sentence_index": 6, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的全市作业都做完了。", "explanation": "〈全市〉指整座城市的全体，不能表示“全部”，应说“全部作业”。"}, {"text": "我一个人把这盘菜全市都吃光了。", "explanation": "这里应该用〈全部〉。〈全市〉指整个城市或城里的全体人，「我一个人」的动作不能用「全市」来表示。"}, {"text": "他的全市钱都花光了。", "explanation": "〈全市〉指整座城市，不能表示“全部”，应说“全部的钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息让全市地人民都很激动。", "corrected_sentence": "这个消息让全市的人民都很激动。", "error_description": "错误：修饰名词「人民」的「全市」要用「的」，不能用「地」；应说「全市的人民」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大火的消息让一个全市都紧张起来了。", "corrected_sentence": "那场大火的消息让全市都紧张起来了。", "error_description": "错误：「全市」指整个城市，是整体而非可数的个体，不能用数量词「一个」修饰。应去掉「一个」，说「让全市都紧张起来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
