INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92303, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "死线是最晚要交东西的那一天。", "primary_collocate": null, "pronunciation": "sǐ xiàn", "ipa": "sɿ˨˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "今天是交作业的死线。", "target_word": "死线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大家在死线以前交作业。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "死线是星期五，别忘了。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了死线，老师就不收作业了。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不知道死线是哪一天。", "target_word": "死线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "报名的死线是这个月三十号。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把死线写在日历上了。", "target_word": "死线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说死线不能改。", "target_word": "死线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我记得死线是明天下午三点。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离死线只有两天了，你写完了吗？", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个死线", "label": "量词"}], "register": "口语", "sense_fingerprint": "最晚交作业或材料的那一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丝线", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是丝线。"}, {"text": "米线", "is_correct": false, "explanation": "mǐ 与 sǐ 声母不同（m 与 s），意思是米粉做的面条。"}, {"text": "四线", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，如“四线城市”，意思是第四等级。"}, {"text": "死线", "is_correct": true, "explanation": "sǐ xiàn，指最晚交作业或材料的那一天，正确答案。"}], "explanations": {"丝线": "sī（第一声）与 sǐ（第三声）声调不同，意思是丝线。", "米线": "mǐ 与 sǐ 声母不同（m 与 s），意思是米粉做的面条。", "四线": "sì（第四声）与 sǐ（第三声）声调不同，如“四线城市”，意思是第四等级。", "死线": "sǐ xiàn，指最晚交作业或材料的那一天，正确答案。"}, "sentence_index": null, "correct_answer": "死线"}, "level_3": {"options": [{"text": "死线", "is_correct": true, "explanation": "死线指交作业的最后期限，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是作业，不能作为交的对象。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“交”一般搭配作业、报告等可提交的东西，不说“交镜子”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是房屋的构件，句子不通。"}], "explanations": {"死线": "死线指交作业的最后期限，符合句意。", "黑板": "语义：黑板不是作业，不能作为交的对象。", "镜子": "搭配：“交”一般搭配作业、报告等可提交的东西，不说“交镜子”。", "窗户": "语义：窗户是房屋的构件，句子不通。"}, "sentence_index": 0, "correct_answer": "死线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的死线是一周。", "explanation": "这里应该用〈期限〉。死线指截止的时间点，一周的时长要用〈期限〉。"}, {"text": "这次面试的死线是十分钟。", "explanation": "这里应该用〈时限〉。死线只指截止的时刻，十分钟的时长要用〈时限〉。"}, {"text": "会议死线请关机。", "explanation": "这里应该用〈期间〉。死线是时间点，不能指会议的整个过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死线", "is_correct": true, "explanation": "死线可以写在日历上，指截止的日期，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能被写在日历上，句意不通。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是食物，不能写在日历上。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“写”的对象应是文字或符号，不能用于“椅子”。"}], "explanations": {"死线": "死线可以写在日历上，指截止的日期，符合句意。", "冰箱": "语义：冰箱不能被写在日历上，句意不通。", "大米": "语义：大米是食物，不能写在日历上。", "椅子": "搭配：“写”的对象应是文字或符号，不能用于“椅子”。"}, "sentence_index": 6, "correct_answer": "死线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那条死线装进了箱子里。", "explanation": "这里把〈死线〉当成可以装进箱子的实物。死线是抽象的截止期限，不是东西，不能装进箱子。"}, {"text": "他站在一座死线的旁边。", "explanation": "这里量词用错。死线应该用〈个〉，〈座〉用于大型建筑或山。"}, {"text": "操场上有一片死线。", "explanation": "这里量词用错。〈片〉用于面积较大的平面，死线应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天只有一把死线，别忘了。", "corrected_sentence": "今天只有一个死线，别忘了。", "error_description": "量词用错：“死线”应用量词“个”；“把”用于有柄的器具，不能用于死线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在死线只有三天了，我们还没开始。", "corrected_sentence": "离死线只有三天了，我们还没开始。", "error_description": "介词用错：表示距离截止还有多久要用“离”，不能用“在”，应说“离死线只有三天了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
