INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92304, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "截止期限，到时必须完成的最后时间。", "primary_collocate": null, "pronunciation": "sǐ xiàn", "ipa": "sɿ˨˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "明天就是交报告的死线。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们必须在死线前完成工作。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他又错过了死线。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "死线快到了，大家都很忙。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把作业的死线改到了周五。", "target_word": "死线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次到了死线，他才开始写。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个项目的死线是下个月十号。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了赶死线，她昨晚没有睡觉。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给了我们一个很短的死线。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了死线，我们就不能再交了。", "target_word": "死线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个死线", "label": "量词"}], "register": "口语", "sense_fingerprint": "工作或任务必须完成的截止期限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丝线", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是丝线。"}, {"text": "米线", "is_correct": false, "explanation": "mǐ 与 sǐ 声母不同（m 与 s），意思是米粉做的面条。"}, {"text": "四线", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，如“四线城市”，意思是第四等级。"}, {"text": "死线", "is_correct": true, "explanation": "sǐ xiàn，指截止期限，正确答案。"}], "explanations": {"丝线": "sī（第一声）与 sǐ（第三声）声调不同，意思是丝线。", "米线": "mǐ 与 sǐ 声母不同（m 与 s），意思是米粉做的面条。", "四线": "sì（第四声）与 sǐ（第三声）声调不同，如“四线城市”，意思是第四等级。", "死线": "sǐ xiàn，指截止期限，正确答案。"}, "sentence_index": null, "correct_answer": "死线"}, "level_3": {"options": [{"text": "死线", "is_correct": true, "explanation": "死线指截止期限，与“交报告”搭配，符合句意。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是用来导电的线，不是可以交的东西。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“交”不能与“生日”搭配，句子不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是挂在窗户上的布，不是需要提交的东西。"}], "explanations": {"死线": "死线指截止期限，与“交报告”搭配，符合句意。", "电线": "语义：电线是用来导电的线，不是可以交的东西。", "生日": "搭配：“交”不能与“生日”搭配，句子不通。", "窗帘": "语义：窗帘是挂在窗户上的布，不是需要提交的东西。"}, "sentence_index": 0, "correct_answer": "死线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的死线是三年。", "explanation": "这里应该用〈期限〉。死线指一个截止的时间点，不能用来表示持续三年。"}, {"text": "这场考试的死线是两小时。", "explanation": "这里应该用〈时限〉。死线只指截止的那一刻，考试两小时的时长要用〈时限〉。"}, {"text": "比赛死线不能使用手机。", "explanation": "这里应该用〈期间〉。死线只指截止的时间点，不能指比赛持续的整段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死线", "is_correct": true, "explanation": "死线指截止日期，此处指项目的截止时间，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是日期，不能说“颜色是下个月十号”。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址指地点，不能表示某个日期。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“身材”多用于人的体形，不用于项目。"}], "explanations": {"死线": "死线指截止日期，此处指项目的截止时间，符合句意。", "颜色": "语义：颜色不是日期，不能说“颜色是下个月十号”。", "地址": "语义：地址指地点，不能表示某个日期。", "身材": "搭配：“身材”多用于人的体形，不用于项目。"}, "sentence_index": 6, "correct_answer": "死线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一把抓住那条死线，用力往上爬。", "explanation": "这里把〈死线〉当成可以抓握的绳索。死线只指截止的期限，是抽象的时间，不是实物，不能抓住往上爬。"}, {"text": "我们面前有一座死线。", "explanation": "这里量词用错。死线应该用〈个〉，〈座〉用于山、楼等大型建筑，不能用于死线。"}, {"text": "我们面前有一片死线。", "explanation": "这里量词用错。〈片〉用于面积较大的平面，死线应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们只有一只死线。", "corrected_sentence": "这个月我们只有一个死线。", "error_description": "量词用错：“死线”应用量词“个”；“只”用于动物，不能用于死线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一定要在死线之上交完作业。", "corrected_sentence": "我们一定要在死线之前交完作业。", "error_description": "方位词用错：时间上的截止要说“死线之前”，“之上”表示空间位置，不能用于死线。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "保守与“冒险”意思相反，指不敢冒险、只做稳妥的事。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明指智力高、反应快，与“冒险”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指场面喧闹、人多，与“冒险”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}], "correct_answer": "保守", "explanations": {"保守": "保守与“冒险”意思相反，指不敢冒险、只做稳妥的事。", "聪明": "聪明指智力高、反应快，与“冒险”没有反义关系。", "热闹": "热闹指场面喧闹、人多，与“冒险”没有反义关系。", "勤奋": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谨慎", "is_correct": true, "explanation": "谨慎与“冒险”意思相反，指做事小心，不去做有危险的事。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌或事物好看，与“冒险”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“冒险”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情指态度亲切主动，与“冒险”没有反义关系。"}], "correct_answer": "谨慎", "explanations": {"谨慎": "谨慎与“冒险”意思相反，指做事小心，不去做有危险的事。", "漂亮": "漂亮指外貌或事物好看，与“冒险”没有反义关系。", "清楚": "清楚指明白、不模糊，与“冒险”没有反义关系。", "热情": "热情指态度亲切主动，与“冒险”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冒险是去做有危险的事。", "primary_collocate": null, "pronunciation": "mào xiǎn", "ipa": "maʊ˥˩ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他喜欢去山里冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想去森林里冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们计划去非洲丛林冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不应该在河边冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不让我一个人冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个喜欢冒险的人。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们决定去海上冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人常想出去冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上冒险，结果迷路了。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒险家", "label": "派生词"}, {"form": "冒险精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "去做有危险的事，探险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：与“喜欢去山里”搭配，表示去做有危险的事，句意通顺。"}, {"text": "恐高", "is_correct": false, "explanation": "语义：「恐高」指害怕高处，与「去山里」的爱好意思矛盾，句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是不愿发生的状态，与“喜欢”的意思冲突，句意不合常理。"}, {"text": "思念", "is_correct": false, "explanation": "配价：“思念”是及物动词，必须带宾语，不能在这里单独作谓语。"}], "explanations": {"冒险": "冒险：与“喜欢去山里”搭配，表示去做有危险的事，句意通顺。", "恐高": "语义：「恐高」指害怕高处，与「去山里」的爱好意思矛盾，句意不通。", "生病": "语义：“生病”是不愿发生的状态，与“喜欢”的意思冲突，句意不合常理。", "思念": "配价：“思念”是及物动词，必须带宾语，不能在这里单独作谓语。"}, "sentence_index": 0, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份作业很简单，我想冒险做一下。", "explanation": "这里应该用〈尝试〉。作业简单、没有危险，“冒险”表示有危险地去做事，尝试普通的事不能说冒险。"}, {"text": "他冒险生病了。", "explanation": "这里应该用〈不慎〉。冒险指自己有意去做有危险的事，生病是无意中遭遇的结果，不能说“冒险”。"}, {"text": "周末他在家里冒险，看书喝茶。", "explanation": "这里应该用〈休息〉。冒险是去做有危险的事；在家看书喝茶没有任何危险，不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作“喜欢”的对象，表示喜欢去做有危险的事，句意通顺。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：「失眠」指长期睡不着，是不舒服的状态，与「喜欢」的意思冲突，句意不合常理。"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿”是不愿遭受的状态，与“喜欢”的意思冲突，句意不合常理。"}, {"text": "晕车", "is_correct": false, "explanation": "语义：「晕车」指乘车时身体不适，是不愿遇到的状态，与「喜欢」的意思冲突，句意不合常理。"}], "explanations": {"冒险": "冒险：作“喜欢”的对象，表示喜欢去做有危险的事，句意通顺。", "失眠": "语义：「失眠」指长期睡不着，是不舒服的状态，与「喜欢」的意思冲突，句意不合常理。", "挨饿": "语义：“挨饿”是不愿遭受的状态，与“喜欢”的意思冲突，句意不合常理。", "晕车": "语义：「晕车」指乘车时身体不适，是不愿遇到的状态，与「喜欢」的意思冲突，句意不合常理。"}, "sentence_index": 6, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在博物馆里冒险参观了一下午。", "explanation": "这里应该用〈游览〉。冒险指有危险地去做事；在博物馆里安全地参观、游览不含危险，不能说冒险。"}, {"text": "他在路上冒险打了个喷嚏。", "explanation": "这里应该用〈不小心〉。冒险指有意去做有危险的事；打喷嚏是无意中发生的动作，不能说冒险。"}, {"text": "他在家里冒险睡了一个安稳的午觉。", "explanation": "这里应该用〈安心〉。冒险指有危险地去做事；在家安稳睡午觉没有危险，表示放心时不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年冒险了过一次。", "corrected_sentence": "他去年冒险过一次。", "error_description": "错误形式：「他去年冒险了过一次」；正确形式：「他去年冒险过一次」。表示经历的「过」已经表达完成，与「了」不能同时用在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冒险着一次，结果受伤了。", "corrected_sentence": "他冒险了一次，结果受伤了。", "error_description": "错误形式：「他冒险着一次，结果受伤了」；正确形式：「他冒险了一次，结果受伤了」。「着」表示动作的持续状态，「冒险一次」是一次性完成的动作，应用表示完成的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谨慎", "is_correct": true, "explanation": "谨慎与“不顾危险去做某事”意思相反，指做事小心、避开危险。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“冒险”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌或事物好看，与“冒险”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}], "correct_answer": "谨慎", "explanations": {"谨慎": "谨慎与“不顾危险去做某事”意思相反，指做事小心、避开危险。", "清楚": "清楚指明白、不模糊，与“冒险”没有反义关系。", "漂亮": "漂亮指外貌或事物好看，与“冒险”没有反义关系。", "勤奋": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
