INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不顾危险去做某事。", "primary_collocate": null, "pronunciation": "mào xiǎn", "ipa": "maʊ˥˩ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他冒险跳进了河里。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒险给病人做了手术。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她冒险走过了那座旧桥。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冒险冲进了火里。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们冒险在雨中开车回家。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冒险把孩子送到了医院。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士冒险过河，给大家送信。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了救人，他冒险爬上了高楼。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机冒险停下车，帮了老人。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者冒险进入了大雨中的山区。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒险家", "label": "派生词"}, {"form": "冒险精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不顾危险，后接动作去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作状语修饰“跳进”，表示不顾危险地跳进河里，句意通顺。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与后面已经发生的“跳进了”意思矛盾，句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“跳进了河里”的动作相矛盾，放弃了又跳进去，句意不通。"}, {"text": "遇到", "is_correct": false, "explanation": "配价：“遇到”后接名词性宾语，不能接“跳进了河里”这样的动词短语。"}], "explanations": {"冒险": "冒险：作状语修饰“跳进”，表示不顾危险地跳进河里，句意通顺。", "拒绝": "语义：“拒绝”与后面已经发生的“跳进了”意思矛盾，句意不通。", "放弃": "语义：“放弃”与“跳进了河里”的动作相矛盾，放弃了又跳进去，句意不通。", "遇到": "配价：“遇到”后接名词性宾语，不能接“跳进了河里”这样的动词短语。"}, "sentence_index": 0, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我在家里冒险看了一场电影。", "explanation": "这里应该用〈消遣〉。冒险指不顾危险去做某事；在家看电影只是消遣，没有危险，不能说冒险。"}, {"text": "他冒险长高了三厘米。", "explanation": "这里应该用〈不知不觉〉。冒险指不顾危险主动去做某事；长高是自然发生的变化，不能说冒险。"}, {"text": "他冒险给花浇了水。", "explanation": "这里应该用〈照例〉。冒险指不顾危险去做某事；给花浇水没有危险，不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作状语修饰“过河”，表示不顾危险地过河送信，句意通顺。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避过河”与“给大家送信”的目的相矛盾，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与过河、送信毫无关联，句意荒谬。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”是及物动词，必须带宾语，不能直接接“过河”。"}], "explanations": {"冒险": "冒险：作状语修饰“过河”，表示不顾危险地过河送信，句意通顺。", "逃避": "语义：“逃避过河”与“给大家送信”的目的相矛盾，句意不通。", "结婚": "语义：“结婚”与过河、送信毫无关联，句意荒谬。", "拥有": "配价：“拥有”是及物动词，必须带宾语，不能直接接“过河”。"}, "sentence_index": 6, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天在办公室冒险打扫房间。", "explanation": "这里应该用〈认真〉。冒险指不顾危险去做某事；在办公室打扫房间没有危险，不能说冒险。"}, {"text": "记者冒险感冒了。", "explanation": "这里应该用〈着凉〉。冒险指有意去做有危险的事；感冒是无意中得的病，不能说冒险。"}, {"text": "这条平坦的高速公路上，记者冒险开车。", "explanation": "这里应该用〈照常〉。冒险指不顾危险去做某事；在平坦畅通的路上照常开车没有危险，不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她冒险的穿过了火场。", "corrected_sentence": "她冒险地穿过了火场。", "error_description": "错误形式：「她冒险的穿过了火场」；正确形式：「她冒险地穿过了火场」。修饰动词的状语要用「地」，「的」只用于名词性修饰语，不能用于这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冒险得爬上了山顶。", "corrected_sentence": "他冒险地爬上了山顶。", "error_description": "错误形式：「他冒险得爬上了山顶」；正确形式：「他冒险地爬上了山顶」。修饰动词的状语要用“地”，“得”用于补语，这里误用了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
