INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "求助是请别人来帮忙。", "primary_collocate": null, "pronunciation": "qiú zhù", "ipa": "tɕʰioʊ˧˥ tʂu˥˩", "syllable_count": 2, "sentences": [{"text": "我的电脑坏了，只好向朋友求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，不要怕向别人求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迷路了，就向警察求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给老师发了信息求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会做这道题，想向同学求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明向邻居求助过一次。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，他向路人求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大声喊着向周围的人求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子有问题时，会向妈妈求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有困难的话，可以随时向我求助。", "target_word": "求助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "求助了", "label": "体标"}, {"form": "求助过", "label": "体标"}, {"form": "求助信", "label": "复合"}, {"form": "求助电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "请别人来帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维修", "is_correct": false, "explanation": "搭配：“维修”针对机器设备，不能说“向朋友维修”。"}, {"text": "求助", "is_correct": true, "explanation": "求助：请朋友帮忙，与“只好向朋友”和电脑坏了的语境相符。"}, {"text": "发送", "is_correct": false, "explanation": "配价：“发送”后面要带发送的内容或对象，“向朋友发送”缺少宾语，句子不完整。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把内容印在纸上，与电脑坏了后找人帮忙无关。"}], "explanations": {"维修": "搭配：“维修”针对机器设备，不能说“向朋友维修”。", "求助": "求助：请朋友帮忙，与“只好向朋友”和电脑坏了的语境相符。", "发送": "配价：“发送”后面要带发送的内容或对象，“向朋友发送”缺少宾语，句子不完整。", "打印": "语义：“打印”指把内容印在纸上，与电脑坏了后找人帮忙无关。"}, "sentence_index": 0, "correct_answer": "求助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向公司求助加薪。", "explanation": "这里应该用〈请求〉。求助是遇到困难请人帮忙，请公司批准加薪应说“请求”。"}, {"text": "消防员向被困的孩子求助。", "explanation": "这里应该用〈救助〉。求助是有困难的一方请别人帮自己，施救的消防员不能向被困的孩子求助。"}, {"text": "科学家正在求助治疗的方法。", "explanation": "这里应该用〈寻求〉。求助的内容是请人帮忙，寻找方法、途径要用“寻求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充值", "is_correct": false, "explanation": "语义：“充值”是往账户里存钱，与“他向路人”求助的意思不合。"}, {"text": "求助", "is_correct": true, "explanation": "求助：向路人请求帮忙，与手机没电、需要帮助的语境相符。"}, {"text": "上网", "is_correct": false, "explanation": "语义：“向路人上网”不成立，“上网”不需要向别人请求。"}, {"text": "更换", "is_correct": false, "explanation": "配价：“更换”需要带宾语（换什么），“向路人更换”后面缺少宾语。"}], "explanations": {"充值": "语义：“充值”是往账户里存钱，与“他向路人”求助的意思不合。", "求助": "求助：向路人请求帮忙，与手机没电、需要帮助的语境相符。", "上网": "语义：“向路人上网”不成立，“上网”不需要向别人请求。", "更换": "配价：“更换”需要带宾语（换什么），“向路人更换”后面缺少宾语。"}, "sentence_index": 6, "correct_answer": "求助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "红十字会正在向灾区求助。", "explanation": "这里应该用〈援助〉。求助是有困难的一方请人帮忙，提供帮助的红十字会应说“援助”，不能说它向灾区求助。"}, {"text": "他跪在地上求助原谅。", "explanation": "这里应该用〈乞求〉。求助是请人帮忙，不能接“原谅”这种请人宽恕的内容。"}, {"text": "学校求助了他的申请。", "explanation": "这里应该用〈接受〉。求助是请人帮忙，不能用来说对申请作出回应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子在半路抛锚了，我只好向修车师傅了求助。", "corrected_sentence": "车子在半路抛锚了，我只好向修车师傅求助。", "error_description": "错误在“了”的位置。“了”不能放在“向修车师傅”和“求助”之间；这里应去掉“了”，改为“我只好向修车师傅求助。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考试前我有很多题不会，就把老师求助。", "corrected_sentence": "考试前我有很多题不会，就向老师求助。", "error_description": "错误在介词。“求助”的对象要用“向”引出，不能用“把”；应说“向老师求助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
