INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "反正是说不管怎么样，结果都一样。", "primary_collocate": null, "pronunciation": "fǎn zhèng", "ipa": "fan˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你去不去，反正结果都一样。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别等了，他来不来，反正我们都要走。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贵也好，便宜也好，反正我都不买。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说什么，反正他都不会听。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐车还是走路，反正都要一个小时。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管你怎么解释，反正他不会相信。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早去晚去，反正都得排队，不用着急。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试了很多次，反正结果还是一样的。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨也好，不下雨也好，反正我都会去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哭也好笑也好，反正这件事不会改变。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不管怎么样，结果都一样，常与“不管”“都”“也好”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示不管怎样结果都一样，与“你去不去”的选择相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“去不去”的选择和“结果都一样”的判断都无关。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”后面通常接值得庆幸的结果，这里“结果都一样”不构成庆幸的理由。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，这句里没有先前的预料，用它不通。"}], "explanations": {"反正": "正确：“反正”表示不管怎样结果都一样，与“你去不去”的选择相合。", "忽然": "语义：“忽然”表示突然发生，与“去不去”的选择和“结果都一样”的判断都无关。", "幸好": "搭配：“幸好”后面通常接值得庆幸的结果，这里“结果都一样”不构成庆幸的理由。", "果然": "语义：“果然”表示与预料相符，这句里没有先前的预料，用它不通。"}, "sentence_index": 0, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果明天下雨，反正我们就不去了。", "explanation": "这里应该用〈那〉。“如果……那就……”表示由条件推出结果，“反正”表示不管条件如何结果都一样，不能引出由条件决定的结论。"}, {"text": "我猜他会迟到，反正他真的迟到了。", "explanation": "这里应该用〈果然〉。“果然”表示事情与预料相符，“反正”只强调结果不受条件影响，不表示印证。"}, {"text": "听到这个消息，他反正哭了起来。", "explanation": "这里应该用〈突然〉。“突然”表示事情发生得很快、出乎意料，“反正”没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示不论早去还是晚去，都得排队，结论不变，与“不用着急”相合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或与期望相反，这句只是说明情况，没有这层意思。"}, {"text": "刚好", "is_correct": false, "explanation": "搭配：“刚好”表示恰巧合适，与“都得排队”所说的必然性不协调。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙，与后句“不用着急”直接矛盾。"}], "explanations": {"反正": "正确：“反正”表示不论早去还是晚去，都得排队，结论不变，与“不用着急”相合。", "偏偏": "语义：“偏偏”表示故意或与期望相反，这句只是说明情况，没有这层意思。", "刚好": "搭配：“刚好”表示恰巧合适，与“都得排队”所说的必然性不协调。", "赶紧": "语义：“赶紧”表示急忙，与后句“不用着急”直接矛盾。"}, "sentence_index": 6, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过三次努力，他反正考上了大学。", "explanation": "这里应该用〈终于〉。“终于”表示经过努力后才实现，“反正”表示结果与条件无关，不强调经过。"}, {"text": "他一进门就反正坐下了。", "explanation": "这里应该用〈马上〉。“马上”表示动作紧接着发生，“反正”表示不管怎样结果都一样，不表示时间快。"}, {"text": "反正你努力，你就会成功。", "explanation": "这里应该用〈只要〉。“只要……就……”表示条件与结果有关，“反正”表示不管条件如何结果都一样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别管他，反正的我都不信。", "corrected_sentence": "别管他，反正我都不信。", "error_description": "“反正”是副词，不能加“的”修饰名词或代词；应去掉“的”，为“反正我都不信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坐飞机也好，坐火车也好，反正很都要花不少钱。", "corrected_sentence": "坐飞机也好，坐火车也好，反正都要花不少钱。", "error_description": "“反正”是表示结论不变的副词，不能受程度副词“很”修饰；应去掉“很”，为“反正都要花不少钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示情况虽然不同，但结果或结论不变。", "primary_collocate": null, "pronunciation": "fǎn zhèng", "ipa": "fan˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你走这条路，我走那条路，反正都能到学校。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得对不对，反正我已经决定了。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红的蓝的都行，反正我只要一件。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去或者明天去，反正你都得去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好不好，反正明天我们都要出发。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用笔写，他用电脑写，反正都要交作业。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买大的还是小的，反正价钱差不多。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师同意不同意，反正我明天都要去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的办法不同，反正最后的结果是一样的。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说中文，他说英文，反正我们都听得懂。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "几种情况各不相同，但结论不变，前面常列出两种或多种选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示两条路各不相同，但结论都是能到学校，与句意相合。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预料相反，句中没有转折的意思，只是并列说明两条路。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：“白白”多接“浪费”“等待”等表示徒劳的行为，不接“都能到学校”这种有好结果的说法。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上行动，与“你走这条路，我走那条路”的并列选择不相合。"}], "explanations": {"反正": "正确：“反正”表示两条路各不相同，但结论都是能到学校，与句意相合。", "反而": "语义：“反而”表示与预料相反，句中没有转折的意思，只是并列说明两条路。", "白白": "搭配：“白白”多接“浪费”“等待”等表示徒劳的行为，不接“都能到学校”这种有好结果的说法。", "立刻": "语义：“立刻”表示马上行动，与“你走这条路，我走那条路”的并列选择不相合。"}, "sentence_index": 0, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他练了很久，反正拿到了驾照。", "explanation": "这里应该用〈总算〉。“总算”表示经过努力后终于达到，“反正”不表达这种感慨。"}, {"text": "我以为他不来，反正他早就到了。", "explanation": "这里应该用〈原来〉。“原来”表示发现了真相，“反正”不表示意外的发现。"}, {"text": "这件衣服是他反正做的。", "explanation": "这里应该用〈亲手〉。“亲手”强调自己动手，“反正”没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示两种情况价钱不同，但结论不变，与“价钱差不多”相合。"}, {"text": "难道", "is_correct": false, "explanation": "语义：“难道”表示反问，这句是陈述语气，用它不通。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或与期望相反，这句只是比较两种选择。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”后接不得不做的动作，不能用来说明“价钱差不多”这种状态。"}], "explanations": {"反正": "正确：“反正”表示两种情况价钱不同，但结论不变，与“价钱差不多”相合。", "难道": "语义：“难道”表示反问，这句是陈述语气，用它不通。", "偏偏": "语义：“偏偏”表示故意或与期望相反，这句只是比较两种选择。", "只好": "搭配：“只好”后接不得不做的动作，不能用来说明“价钱差不多”这种状态。"}, "sentence_index": 6, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反正把门关上，不让我们进去。", "explanation": "这里应该用〈故意〉。“故意”表示有意识地这样做，“反正”不表示动机。"}, {"text": "大家都以为他很笨，反正他很聪明。", "explanation": "这里应该用〈其实〉。“其实”说出与表面看法相反的真实情况，“反正”不表示揭示真相。"}, {"text": "反正天气好，我们就去爬山。", "explanation": "这里应该用〈只要〉。“只要……就……”表示结果依赖条件，“反正”表示条件不影响结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我坐地铁，你骑车，反正的都能准时到公司。", "corrected_sentence": "我坐地铁，你骑车，反正都能准时到公司。", "error_description": "“反正”是副词，不能加“的”修饰后面的成分；应去掉“的”，为“反正都能准时到公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在家做饭，我在外面买菜，反正很晚饭都能吃上。", "corrected_sentence": "你在家做饭，我在外面买菜，反正晚饭都能吃上。", "error_description": "“反正”不能受程度副词“很”修饰；应去掉“很”，为“反正晚饭都能吃上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
