INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "江湖是到处走的人生活的社会。", "primary_collocate": null, "pronunciation": "jiāng hú", "ipa": "tɕjɑŋ˥ xu˧˥", "syllable_count": 2, "sentences": [{"text": "他从小就在江湖里长大。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江湖里的人到处走，没有家。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时走过江湖，卖过药。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想离开江湖，找一个固定的家。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江湖上的人常常换地方住。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个卖艺的人在江湖上生活了很多年。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说江湖很大，人和人常常只见一面。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在江湖上，大家互相帮忙。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，不想再走江湖了。", "target_word": "江湖", "complexity_tier": "T3", "furigana": "jiāng hú", "sentence_source": "generated"}, {"text": "江湖上的朋友一年也见不到几次。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "到处走的人生活的社会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：“银行”是存钱的机构，不是可以长大的生活环境，与句意不符。"}, {"text": "江湖", "is_correct": true, "explanation": "江湖：到处走的人生活的社会，与“从小就在……里长大”相合，说明生活在漂泊的环境中。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的用具，不能作为人长大的地方。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“在……里长大”要求人生活的地方，词典不是人生活的场所，不能这样搭配。"}], "explanations": {"银行": "语义：“银行”是存钱的机构，不是可以长大的生活环境，与句意不符。", "江湖": "江湖：到处走的人生活的社会，与“从小就在……里长大”相合，说明生活在漂泊的环境中。", "雨伞": "语义：“雨伞”是遮雨的用具，不能作为人长大的地方。", "词典": "搭配：“在……里长大”要求人生活的地方，词典不是人生活的场所，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "江湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐地铁去江湖上班。", "explanation": "这里应该用〈公司〉。江湖指到处走的人生活的社会，不是工作的地方，上班要去公司。"}, {"text": "他一直住在一个温暖的江湖里，从未搬过家。", "explanation": "这里应该用〈家〉。江湖指到处走的人生活的社会，不是可以安家住下的地方。"}, {"text": "周末我们一家人在江湖里吃晚饭。", "explanation": "这里应该用〈餐厅〉。江湖指到处走的人生活的社会，不是吃饭的地方，在外面吃饭要去餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能说“很大”，与句中“很大”不搭配。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：“胃口”指食欲，不指空间的大小，与“只见一面”无关。"}, {"text": "江湖", "is_correct": true, "explanation": "江湖：到处走的人生活的社会，与“很大”“人和人常常只见一面”相合。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”是装东西的小物件，不能说“人和人只见一面”的范围。"}], "explanations": {"心情": "搭配：“心情”不能说“很大”，与句中“很大”不搭配。", "胃口": "语义：“胃口”指食欲，不指空间的大小，与“只见一面”无关。", "江湖": "江湖：到处走的人生活的社会，与“很大”“人和人常常只见一面”相合。", "口袋": "语义：“口袋”是装东西的小物件，不能说“人和人只见一面”的范围。"}, "sentence_index": 6, "correct_answer": "江湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的江湖每天都和我见面，关系很好。", "explanation": "这里应该用〈同事〉。江湖指到处走的人生活的社会，不指朝夕相处的同事。"}, {"text": "他会弹江湖，弹得很好。", "explanation": "这里应该用〈古琴〉。江湖指到处走的人生活的社会，不是乐器，弹奏要用古琴这类乐器。"}, {"text": "他把江湖种在院子里，每天浇水。", "explanation": "这里应该用〈花草〉。江湖指到处走的人生活的社会，是抽象的概念，不能种在院子里浇水，种植浇水的是花草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直江湖里漂泊，没有固定的家。", "corrected_sentence": "他一直在江湖里漂泊，没有固定的家。", "error_description": "介词遗漏：表示在某处做事，要说“在江湖里漂泊”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他闯过一条江湖，后来就定居了。", "corrected_sentence": "他闯过江湖，后来就定居了。", "error_description": "量词错误：“江湖”是抽象的社会，不能用量词“条”来数，应说“闯过江湖”，不能加“一条”。“条”多用于河流、道路等细长的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
