INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧指四处漂泊谋生的人所处的社会；泛指社会上。", "primary_collocate": null, "pronunciation": "jiāng hú", "ipa": "tɕjɑŋ˥ xu˧˥", "syllable_count": 2, "sentences": [{"text": "他年轻时闯荡江湖，什么苦都吃过。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人在江湖上很有名。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就退出江湖，过着安静的生活。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江湖上的人讲究义气。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人走江湖，靠卖艺生活。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江湖险恶，你要小心。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在江湖上混了二十年，认识不少人。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是在江湖上认识的老朋友。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门在外，江湖上的规矩要懂。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老师傅走遍江湖，见多识广。", "target_word": "江湖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "漂泊谋生者所处的社会；泛指社会上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，与“闯荡”“吃过苦”不符。"}, {"text": "江湖", "is_correct": true, "explanation": "江湖：旧指漂泊谋生的人所处的社会，与“闯荡”“吃过苦”相合。"}, {"text": "课堂", "is_correct": false, "explanation": "搭配：“闯荡”指到外面的世界奔波，不能用于“课堂”。"}, {"text": "家乡", "is_correct": false, "explanation": "语义：“家乡”是出生生长的地方，与“闯荡”外出漂泊的意思相反。"}], "explanations": {"厨房": "语义：“厨房”是做饭的地方，与“闯荡”“吃过苦”不符。", "江湖": "江湖：旧指漂泊谋生的人所处的社会，与“闯荡”“吃过苦”相合。", "课堂": "搭配：“闯荡”指到外面的世界奔波，不能用于“课堂”。", "家乡": "语义：“家乡”是出生生长的地方，与“闯荡”外出漂泊的意思相反。"}, "sentence_index": 0, "correct_answer": "江湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都去江湖喝茶，下午再回公司。", "explanation": "这里应该用〈茶馆〉。江湖指四处漂泊谋生的人所处的社会，不是喝茶的场所，喝茶要去茶馆。"}, {"text": "他终于有了一个固定的江湖，不再四处奔波。", "explanation": "这里应该用〈家〉。江湖指四处漂泊谋生的社会，与“固定”“不再奔波”相矛盾，安定的住所要用家。"}, {"text": "我每天在江湖里学习，周末才回家。", "explanation": "这里应该用〈学校〉。江湖指漂泊谋生的社会，不是学习的场所，学习要去学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "搭配：“在……上混”指在某个社会圈子里谋生，不能用于“教室”。"}, {"text": "江湖", "is_correct": true, "explanation": "江湖：旧指漂泊谋生的人所处的社会，“混”在其中谋生，与“认识不少人”相合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是人活动谋生的场所，与“混”不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，不能作为人“混”的场所。"}], "explanations": {"教室": "搭配：“在……上混”指在某个社会圈子里谋生，不能用于“教室”。", "江湖": "江湖：旧指漂泊谋生的人所处的社会，“混”在其中谋生，与“认识不少人”相合。", "天空": "语义：“天空”不是人活动谋生的场所，与“混”不符。", "冰箱": "语义：“冰箱”是电器，不能作为人“混”的场所。"}, "sentence_index": 6, "correct_answer": "江湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个老师傅在江湖里教了三十年书，每天准时打卡上班。", "explanation": "这里应该用〈学校〉。江湖指四处漂泊谋生的社会，不是固定上班的地方，教书要在学校。"}, {"text": "那个老师傅在江湖里种了一辈子地，从没出过村子。", "explanation": "这里应该用〈农田〉。江湖指四处漂泊谋生的社会，种地要在农田里，不能说在江湖里种地。"}, {"text": "那个老师傅一辈子待在江湖里做饭，很少出门。", "explanation": "这里应该用〈厨房〉。江湖指四处漂泊谋生的社会，不是做饭的地方，做饭要在厨房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时走过一条江湖，吃过很多苦。", "corrected_sentence": "他年轻时走过江湖，吃过很多苦。", "error_description": "量词错误：“江湖”是抽象的社会，不能用量词“条”来数，应说“走过江湖”，不能加“一条”。“条”多用于河流、道路等细长的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时江湖闯荡，尝过很多苦。", "corrected_sentence": "他年轻时在江湖闯荡，尝过很多苦。", "error_description": "介词遗漏：表示在某个社会里做事，要说“在江湖闯荡”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92313, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "承认", "is_correct": true, "explanation": "正确：“承认”与“否认”互为反义，表示认可某事是自己做的。"}, {"text": "解释", "is_correct": false, "explanation": "与“否认”不构成反义关系：“解释”指说明道理或原因。"}, {"text": "参观", "is_correct": false, "explanation": "与“否认”不构成反义关系：“参观”指到某地实地看。"}, {"text": "收拾", "is_correct": false, "explanation": "与“否认”不构成反义关系：“收拾”指整理物品。"}], "correct_answer": "承认", "explanations": {"承认": "正确：“承认”与“否认”互为反义，表示认可某事是自己做的。", "解释": "与“否认”不构成反义关系：“解释”指说明道理或原因。", "参观": "与“否认”不构成反义关系：“参观”指到某地实地看。", "收拾": "与“否认”不构成反义关系：“收拾”指整理物品。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
