INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92313, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "否认是别人问你，你说不是你做的。", "primary_collocate": null, "pronunciation": "fǒu rèn", "ipa": "foʊ˨˩˦ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他否认是自己打破了杯子。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明否认拿了同学的笔。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问他，他马上否认了。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直否认昨天去过那里。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟否认吃了我的蛋糕。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他否认自己说过这句话。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别否认，我都看见了。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他红着脸否认了这件事。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机否认喝过酒。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她否认是自己把门关上的。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否认了", "label": "体标"}, {"form": "否认过", "label": "体标"}], "register": "中性", "sense_fingerprint": "否认：被问到时说事情不是自己做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否认", "is_correct": true, "explanation": "正确：“否认”表示说事情不是自己做的，与“他否认是自己打破了杯子”的句意一致。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”用于喜事，不能用于打破杯子这类坏事。"}, {"text": "夸奖", "is_correct": false, "explanation": "配价：“夸奖”要求带受夸的人或事物作宾语，不能接“是自己打破了杯子”这样的事件句。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”接活动、会议等，不能接“是自己打破了杯子”这样的事件句。"}], "explanations": {"否认": "正确：“否认”表示说事情不是自己做的，与“他否认是自己打破了杯子”的句意一致。", "庆祝": "语义：“庆祝”用于喜事，不能用于打破杯子这类坏事。", "夸奖": "配价：“夸奖”要求带受夸的人或事物作宾语，不能接“是自己打破了杯子”这样的事件句。", "参加": "搭配：“参加”接活动、会议等，不能接“是自己打破了杯子”这样的事件句。"}, "sentence_index": 0, "correct_answer": "否认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他否认了我的邀请。", "explanation": "这里应该用〈拒绝〉。“否认”只用于不承认说法或事实，不能用于邀请；“拒绝”可以接邀请。"}, {"text": "专家否认了我的方案。", "explanation": "这里应该用〈否定〉。“否认”针对说法或事实，否定方案要用“否定”。"}, {"text": "他否认了我的提醒。", "explanation": "这里应该用〈忽略〉。“否认”不能用于提醒，对别人的提醒不理会应说“忽略”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否认", "is_correct": true, "explanation": "正确：“否认”与“你别……，我都看见了”的语境相合，表示不承认。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赞赏，与“我都看见了”所指的事实无关，句子不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”接人或活动，不能用于对说法的回应。"}, {"text": "赢", "is_correct": false, "explanation": "语义：“赢”指胜过对手，与“别……，我都看见了”的语境不合。"}], "explanations": {"否认": "正确：“否认”与“你别……，我都看见了”的语境相合，表示不承认。", "欣赏": "语义：“欣赏”表示赞赏，与“我都看见了”所指的事实无关，句子不通。", "欢迎": "搭配：“欢迎”接人或活动，不能用于对说法的回应。", "赢": "语义：“赢”指胜过对手，与“别……，我都看见了”的语境不合。"}, "sentence_index": 6, "correct_answer": "否认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他否认了我的道歉。", "explanation": "这里应该用〈接受〉。“否认”针对说法或事实，不能用于道歉；接受道歉应说“接受”。"}, {"text": "我否认你的建议。", "explanation": "这里应该用〈同意〉。“否认”是不承认某事，不能用于建议；对建议表示认可应说“同意”。"}, {"text": "他否认了我的帮助。", "explanation": "这里应该用〈感谢〉。“否认”不能用于帮助，对别人的帮助表示感谢应说“感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她否认地是自己把花瓶打碎的。", "corrected_sentence": "她否认是自己把花瓶打碎的。", "error_description": "“地”误加在动词后：“否认”是动词，后面直接接内容，不能加“地”，应说“她否认是自己把花瓶打碎的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
