INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不承认；对某事实表示不认可。", "primary_collocate": null, "pronunciation": "fǒu rèn", "ipa": "foʊ˨˩˦ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "没有人能否认他的努力。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司否认了这个消息。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能否认这个事实。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家否认了这种说法。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他否认两个人是朋友关系。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生否认这种药有问题。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人否认过他的成绩。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府否认了涨价的传言。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不否认自己有错。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校否认这次考试作弊的说法。", "target_word": "否认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否认了", "label": "体标"}, {"form": "否认过", "label": "体标"}], "register": "中性", "sense_fingerprint": "否认：不承认某个事实、说法或消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否认", "is_correct": true, "explanation": "正确：“否认”表示不承认，与“没有人能……他的努力”的语境相合。"}, {"text": "认领", "is_correct": false, "explanation": "语义：“认领”指认领失物或子女，不能用于努力。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指搬动实体物品，努力不能被搬运。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”接建筑、设施等，不能接“努力”。"}], "explanations": {"否认": "正确：“否认”表示不承认，与“没有人能……他的努力”的语境相合。", "认领": "语义：“认领”指认领失物或子女，不能用于努力。", "搬运": "语义：“搬运”指搬动实体物品，努力不能被搬运。", "拆除": "搭配：“拆除”接建筑、设施等，不能接“努力”。"}, "sentence_index": 0, "correct_answer": "否认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他否认了我的访问。", "explanation": "这里应该用〈欢迎〉。“否认”只用于说法或事实，不能用于访问；对访问表示欢迎应说“欢迎”。"}, {"text": "我否认了他的礼物。", "explanation": "这里应该用〈接受〉。“否认”不能用于礼物，收下礼物应说“接受”。"}, {"text": "领导否认了这项申请。", "explanation": "这里应该用〈批准〉。“否认”针对说法或事实，申请要说“批准”或“拒绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否认", "is_correct": true, "explanation": "正确：“否认”表示不承认，与“没人……过他的成绩”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“成绩”搭配，句子不通。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”指占有，“没人拥有过他的成绩”意思不通，句子要表达的是不承认他的成绩。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”接责任、困难等，不能接“成绩”。"}], "explanations": {"否认": "正确：“否认”表示不承认，与“没人……过他的成绩”的语境相合。", "吃": "语义：“吃”不能与“成绩”搭配，句子不通。", "拥有": "语义：“拥有”指占有，“没人拥有过他的成绩”意思不通，句子要表达的是不承认他的成绩。", "逃避": "搭配：“逃避”接责任、困难等，不能接“成绩”。"}, "sentence_index": 6, "correct_answer": "否认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师否认了我的作业。", "explanation": "这里应该用〈批改〉。“否认”不能用于作业，老师评阅作业应说“批改”。"}, {"text": "大家否认了这个计划。", "explanation": "这里应该用〈同意〉。“否认”表示不承认事实或说法，对计划表示认可应说“同意”。"}, {"text": "我否认你的陪伴。", "explanation": "这里应该用〈感谢〉。“否认”不能用于陪伴，对别人的陪伴表示感谢应说“感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他否认好这个传言。", "corrected_sentence": "他否认了这个传言。", "error_description": "补语误用：「否认」后不接结果补语「好」，表示完成应使用动态助词「了」，应说「他否认了这个传言」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他否认了过这个消息。", "corrected_sentence": "他否认过这个消息。", "error_description": "体标错误：“了”与“过”不能同时用于同一动词，应说“否认过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很会读书写字、很有本事的女孩或女人。", "primary_collocate": null, "pronunciation": "cái nǚ", "ipa": "tsʰai˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "她从小爱读书，长大后成了有名的才女。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位才女考试总是第一名。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才女写的字又好看又有力。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是个才女，读书写字样样都行。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是班里的才女，作文常常被老师夸。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个才女不但会读书，做事也很有本事。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的才女考上了最好的大学。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位才女一个人把公司办得很好。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她是才女，什么书都读得懂。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才女的书房里摆满了书。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位才女", "label": "量词"}, {"form": "一个才女", "label": "量词"}], "register": "通用", "sense_fingerprint": "指学习、写作好，做事很有能力的女孩或女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指很会读书的女子，与前句「从小爱读书」一致。"}, {"text": "才子", "is_correct": false, "explanation": "语义：「才子」指男子，与「她」不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是地点，不能指「她」。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}], "explanations": {"才女": "正确：「才女」指很会读书的女子，与前句「从小爱读书」一致。", "才子": "语义：「才子」指男子，与「她」不符。", "图书馆": "语义：「图书馆」是地点，不能指「她」。", "水平": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}, "sentence_index": 0, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥是个才女，读书写字样样都行。", "explanation": "这里应该用〈才子〉。才女专指女子，形容男子要用才子。"}, {"text": "我姐姐是个才女，可是连一个字都不会写。", "explanation": "这里把「才女」用成了〈不识字的人〉的意思。才女指很会读书写字的女子，句子说她连字都不会写，与本义相反。"}, {"text": "我姐姐长得很美，大家都叫她才女。", "explanation": "这里把「才女」用来夸容貌。才女指很会读书写字、很有本事的女子，不指容貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指人，能考上最好的大学，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：「汽车」不能考上大学，与句意不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：「花园」不能考上大学，与句意不符。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：「作品」不能「考上」大学，这里的主语必须是人。"}], "explanations": {"才女": "正确：「才女」指人，能考上最好的大学，与句意相符。", "汽车": "语义：「汽车」不能考上大学，与句意不符。", "花园": "语义：「花园」不能考上大学，与句意不符。", "作品": "搭配：「作品」不能「考上」大学，这里的主语必须是人。"}, "sentence_index": 6, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个同学学习很差，作文也写不好，所以大家都叫她才女。", "explanation": "这里把「才女」用成了〈学习差的人〉的意思。才女指很会读书写字、很有本事的女子，学习差、写不好作文的人不能叫才女。"}, {"text": "我家的鹦鹉是才女，会背很多诗。", "explanation": "这里把「才女」用成了〈会背诗的鸟〉的意思。才女只指很会读书写字的女子或女人，不能用来指鸟。"}, {"text": "她不认识几个字，所以大家都叫她才女。", "explanation": "这里把「才女」用成了〈不识字的人〉的意思。才女指很会读书写字的女子，不识字的人不能叫才女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是班里的一颗才女，读书写字样样都行。", "corrected_sentence": "她是班里的一位才女，读书写字样样都行。", "error_description": "量词「颗」用于小而圆的东西，不能用来指人；应改为「位」，说「一位才女」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那三位才女们都很有学问。", "corrected_sentence": "那三位才女都很有学问。", "error_description": "「三位」已经表示人数，名词后不能再加「们」，应说「那三位才女都很有学问」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
