INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有才华的女子。", "primary_collocate": null, "pronunciation": "cái nǚ", "ipa": "tsʰai˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是我们学校有名的才女。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有很多才女，李清照就是一位。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位才女写的诗很有名。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她既会画画又会弹琴，大家都叫她才女。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位才女年轻时就出版了自己的诗集。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国古代的才女，常常在家里读书写诗。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小丽是公司里出名的才女，歌也唱得好。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个才女又会跳舞又会写文章。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了一位才女的故事。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸她是个才女，她却说自己还要学习。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位才女", "label": "量词"}, {"form": "一个才女", "label": "量词"}], "register": "通用", "sense_fingerprint": "指在诗文、书画、音乐等方面才华出众的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指有才华的女子，与「她」相符。"}, {"text": "才子", "is_correct": false, "explanation": "语义：「才子」指有才华的男子，与「她」不符。"}, {"text": "校车", "is_correct": false, "explanation": "语义：「校车」是物，不能指「她」这个人。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}], "explanations": {"才女": "正确：「才女」指有才华的女子，与「她」相符。", "才子": "语义：「才子」指有才华的男子，与「她」不符。", "校车": "语义：「校车」是物，不能指「她」这个人。", "水平": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}, "sentence_index": 0, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个才女，诗写得特别好。", "explanation": "这里应该用〈才子〉。才女专指有才华的女子，形容男子要用才子。"}, {"text": "她是个才女，连一句诗都背不出来。", "explanation": "这里把「才女」用成了〈不爱读书的人〉的意思。才女指有才华的女子，句子说她背不出一句诗，与才华相反。"}, {"text": "这块石头是个才女，摆在桌上很好看。", "explanation": "这里把「才女」用来指物。才女只指有才华的女子，不能用来指石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指有才华的女子，「歌也唱得好」说明她有才华。"}, {"text": "打印机", "is_correct": false, "explanation": "语义：「打印机」是物，不能指「小丽」这个人。"}, {"text": "会议室", "is_correct": false, "explanation": "语义：「会议室」是地点，不能指人。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：「出名的成绩」搭配不当，「成绩」不能指人。"}], "explanations": {"才女": "正确：「才女」指有才华的女子，「歌也唱得好」说明她有才华。", "打印机": "语义：「打印机」是物，不能指「小丽」这个人。", "会议室": "语义：「会议室」是地点，不能指人。", "成绩": "搭配：「出名的成绩」搭配不当，「成绩」不能指人。"}, "sentence_index": 6, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她不会写诗，也不会画画、唱歌，什么都不会，大家都叫她才女。", "explanation": "这里把「才女」用成了〈没有才能的人〉的意思。才女指在诗文、书画、音乐等方面有才华的女子，句子说她什么都不会，与本义相反。"}, {"text": "我家的小狗是个才女，会自己开门。", "explanation": "这里把「才女」用成了〈聪明的宠物〉的意思。才女只指有才华的女子，不能用来指小狗。"}, {"text": "她是个才女，却连自己的名字都写不出来。", "explanation": "这里把「才女」用成了〈不识字的人〉的意思。才女指有才华的女子，句子说她连名字都写不出，与才华相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是班里一只很有名的才女。", "corrected_sentence": "她是班里一位很有名的才女。", "error_description": "量词「只」不能用来指人的「才女」，应改为「位」，说「一位很有名的才女」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位才女们都很努力。", "corrected_sentence": "这两位才女都很努力。", "error_description": "「两位」已经表示人数，名词后不能再加「们」，应说「这两位才女都很努力」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
