INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河道是河水流的那条路。", "primary_collocate": null, "pronunciation": "hé dào", "ipa": "xɤ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这条河道很宽。", "target_word": "河道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天河水多，河道里都是水。", "target_word": "河道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在清理河道里的垃圾。", "target_word": "河道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河道两边种着很多树。", "target_word": "河道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河道又长又直。", "target_word": "河道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，河道里的水涨高了。", "target_word": "河道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河道里有很多小鱼。", "target_word": "河道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河道上有一座老桥。", "target_word": "河道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天河道干了，没有水。", "target_word": "河道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的河道需要每年清理。", "target_word": "河道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条河道", "label": "量词"}], "register": "中性", "sense_fingerprint": "河水流动的那条路，侧重河床和水路本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "搭配：量词“条”不能修饰房间，应说“这个房间”，“这条房间”不成立。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“很宽”描述空间的宽窄，声音不能用“很宽”来形容。"}, {"text": "河道", "is_correct": true, "explanation": "正确：河道是河水流经的路，“这条”与之搭配，“很宽”描述河道的宽窄。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子的量词是“张”，不能说“这条桌子”。"}], "explanations": {"房间": "搭配：量词“条”不能修饰房间，应说“这个房间”，“这条房间”不成立。", "声音": "语义：“很宽”描述空间的宽窄，声音不能用“很宽”来形容。", "河道": "正确：河道是河水流经的路，“这条”与之搭配，“很宽”描述河道的宽窄。", "桌子": "搭配：桌子的量词是“张”，不能说“这条桌子”。"}, "sentence_index": 0, "correct_answer": "河道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝一口河道。", "explanation": "这里应该用〈河水〉。河道是河床和水路，不能喝，喝的是河水。"}, {"text": "那座河道很长。", "explanation": "量词用错。河道应该用〈条〉，〈座〉用于山、桥、楼等大型建筑或山体。"}, {"text": "那只河道很长。", "explanation": "量词用错。河道应该用〈条〉，〈只〉用于动物或成对的器官，不能修饰河道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是水体，“里有很多小鱼”说的是水中的鱼。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“小鱼”只与水域搭配，沙发里不会有很多小鱼。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以装小鱼的地方，“里有很多小鱼”不成立。"}, {"text": "河道", "is_correct": true, "explanation": "正确：河道是水流的通道，里面可以有很多小鱼。"}], "explanations": {"天空": "语义：天空不是水体，“里有很多小鱼”说的是水中的鱼。", "沙发": "搭配：“小鱼”只与水域搭配，沙发里不会有很多小鱼。", "时间": "语义：时间不是可以装小鱼的地方，“里有很多小鱼”不成立。", "河道": "正确：河道是水流的通道，里面可以有很多小鱼。"}, "sentence_index": 6, "correct_answer": "河道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块河道很长。", "explanation": "量词用错。河道应该用〈条〉，〈块〉用于片状的东西。"}, {"text": "我们通过河道申请了证件。", "explanation": "这里应该用〈渠道〉。渠道可以指办事的途径，河道只指水流的通道，不能用来申请证件。"}, {"text": "那所河道很长。", "explanation": "量词用错。河道应该用〈条〉，〈所〉用于学校、医院等单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口有一个河道，水很清。", "corrected_sentence": "村口有一条河道，水很清。", "error_description": "量词错误。河道的量词应用“条”，“一个河道”应改为“一条河道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村子西边有一座河道，水很清。", "corrected_sentence": "村子西边有一条河道，水很清。", "error_description": "量词错误。河道的量词应用“条”，“一座河道”应改为“一条河道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
