INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外面是房子或盒子的外边。", "primary_collocate": null, "pronunciation": "wài miàn", "ipa": "wai˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "房子外面的草地上有一只狗。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子外面写着我的名字。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子外面停着一辆红色的车。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外面站着一个人。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把箱子放在门外面。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子外面有很多灰，里面很干净。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子外面是红色的，里面是白色的。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在教室外面等老师。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户外面有很多鸟。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包外面湿了，里面没湿。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "房子、盒子等物体的外边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外面", "is_correct": true, "explanation": "“外面”指房子的外边，与“草地上有一只狗”的位置一致。"}, {"text": "里面", "is_correct": false, "explanation": "语义：“里面”指房子内部，草地不会在房子里面，不符合本句。"}, {"text": "上面", "is_correct": false, "explanation": "搭配：“房子上面”指屋顶之上，草地不在屋顶上，不自然。"}, {"text": "地下", "is_correct": false, "explanation": "语义：“地下”指地面以下，不能表示房子外面的位置。"}], "explanations": {"外面": "“外面”指房子的外边，与“草地上有一只狗”的位置一致。", "里面": "语义：“里面”指房子内部，草地不会在房子里面，不符合本句。", "上面": "搭配：“房子上面”指屋顶之上，草地不在屋顶上，不自然。", "地下": "语义：“地下”指地面以下，不能表示房子外面的位置。"}, "sentence_index": 0, "correct_answer": "外面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饺子外面包着很多馅儿。", "explanation": "这里应该用〈里面〉。馅儿包在饺子的内部，“外面”指外侧，不能这样用。"}, {"text": "宝宝在妈妈的肚子外面慢慢长大。", "explanation": "这里应该用〈里面〉。宝宝在妈妈肚子的内部长大，“外面”指外侧，不能这样说。"}, {"text": "碗外面盛着热汤。", "explanation": "这里应该用〈里面〉。“盛”要求汤在碗的内部，“外面”指碗的外侧，不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外面", "is_correct": true, "explanation": "“外面”指杯子的外侧，与后半句“里面是白色的”形成对照。"}, {"text": "里面", "is_correct": false, "explanation": "语义：前半句说“杯子里面是红色的”，与后半句“里面是白色的”矛盾，句意不成立。"}, {"text": "旁边", "is_correct": false, "explanation": "搭配：“杯子旁边是红色的”说的是杯子之外的东西，不能描述杯子本身的颜色。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”是时间，不能表示杯子的位置。"}], "explanations": {"外面": "“外面”指杯子的外侧，与后半句“里面是白色的”形成对照。", "里面": "语义：前半句说“杯子里面是红色的”，与后半句“里面是白色的”矛盾，句意不成立。", "旁边": "搭配：“杯子旁边是红色的”说的是杯子之外的东西，不能描述杯子本身的颜色。", "夜里": "语义：“夜里”是时间，不能表示杯子的位置。"}, "sentence_index": 6, "correct_answer": "外面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心外面有很多话想说。", "explanation": "这里应该用〈里面〉。“心里面”指内心，“外面”指外侧，不能说“心外面”。"}, {"text": "他把钥匙放进了盒子外面。", "explanation": "这里应该用〈里面〉。“放进”要到达内部，“外面”指外侧，不能搭配。"}, {"text": "这篇文章外面有很多错字，大家都没发现。", "explanation": "这里应该用〈里面〉。错字在文章的内部，“外面”指外侧，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫箱子外面睡觉。", "corrected_sentence": "小猫在箱子外面睡觉。", "error_description": "错误：表示位置的“外面”前缺少“在”。正确：说“在箱子外面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的车停房子外面。", "corrected_sentence": "他的车停在房子外面。", "error_description": "错误：“停”后面缺少“在”，不能直接说“停房子外面”。正确：说“停在房子外面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
