INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某个范围以外的地方。", "primary_collocate": null, "pronunciation": "wài miàn", "ipa": "wai˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他在外面工作了十年。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市外面都是农田。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去外面看看世界。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在外面买菜，还没回家。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一年有半年在外面出差。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷很少出去，不知道外面的事情。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圈子外面的人不知道这件事。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，应该去外面学点东西。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从外面回来，带了很多礼物。", "target_word": "外面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校外面有一条河。", "target_word": "外面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "某个范围（家、城市、圈子）以外的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外面", "is_correct": true, "explanation": "“外面”指某个范围以外的地方，与“在……工作”的用法一致。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是时间，不能表示工作的地点或范围。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间，不能表示工作的地点或范围。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”是时间，不能表示工作的地点或范围。"}], "explanations": {"外面": "“外面”指某个范围以外的地方，与“在……工作”的用法一致。", "明天": "语义：“明天”是时间，不能表示工作的地点或范围。", "昨天": "语义：“昨天”是时间，不能表示工作的地点或范围。", "刚才": "语义：“刚才”是时间，不能表示工作的地点或范围。"}, "sentence_index": 0, "correct_answer": "外面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这些礼物装进外面。", "explanation": "这里应该用〈里面〉。“装进”要到达内部，而“外面”指范围之外，不能搭配。"}, {"text": "他把桌子搬进了城市外面。", "explanation": "这里应该用〈里面〉。“搬进”要到达内部，“外面”指范围之外，不能搭配。"}, {"text": "孩子把玩具藏进了学校外面。", "explanation": "这里应该用〈里面〉。“藏进”要到达内部，“外面”指范围之外，不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外面", "is_correct": true, "explanation": "“外面”指某个范围以外的地方，与“圈子外面的人不知道”的意思一致。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”是时间，不能表示“圈子”的范围之外。"}, {"text": "对面", "is_correct": false, "explanation": "语义：“对面”指相对的一边，不表示圈子之外。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间，不能表示“圈子”的范围之外。"}], "explanations": {"外面": "“外面”指某个范围以外的地方，与“圈子外面的人不知道”的意思一致。", "夜里": "语义：“夜里”是时间，不能表示“圈子”的范围之外。", "对面": "语义：“对面”指相对的一边，不表示圈子之外。", "昨天": "语义：“昨天”是时间，不能表示“圈子”的范围之外。"}, "sentence_index": 6, "correct_answer": "外面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把钥匙插进了城市外面。", "explanation": "这里应该用〈里面〉。“插进”要到达内部，“外面”指范围之外，不能搭配。"}, {"text": "我把书包放进了学校外面。", "explanation": "这里应该用〈里面〉。“放进”要到达内部，“外面”指范围之外，不能搭配。"}, {"text": "她把衣服挂进了房子外面。", "explanation": "这里应该用〈里面〉。“挂进”要到达内部，“外面”指范围之外，不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直外面打工。", "corrected_sentence": "他一直在外面打工。", "error_description": "错误：表示动作地点的“外面”前缺少“在”。正确：说“在外面打工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市外面地人很友好。", "corrected_sentence": "城市外面的人很友好。", "error_description": "错误：“外面”修饰名词时用了“地”。正确：修饰名词要用“的”，说“城市外面的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
