INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "玩电子游戏。", "primary_collocate": null, "pronunciation": "dǎ yóu xì", "ipa": "ta˨˩˦ jou˧˥ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "周末我在家打游戏。", "target_word": "打游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上都打游戏。", "target_word": "打游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟作业没写完，就想打游戏。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，打游戏的时间不能太长。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢和朋友一起打游戏。", "target_word": "打游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打游戏打到半夜才睡觉。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天不能出去，我只好在屋里打游戏。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不去学习，一直打游戏？", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边吃饭，一边打游戏。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥打游戏很厉害，我常常输给他。", "target_word": "打游戏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了游戏", "label": "体标（了）"}, {"form": "打过游戏", "label": "体标（过）"}, {"form": "打游戏机", "label": "复合"}], "register": "口语", "sense_fingerprint": "玩电子游戏这种娱乐活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打游戏", "is_correct": true, "explanation": "正确：打游戏是玩电子游戏，可以在家进行。"}, {"text": "爬山", "is_correct": false, "explanation": "语义：爬山要到山上去，与“在家”矛盾。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：逛街要到街上去，与“在家”矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要泳池或水域，在家里不搭配。"}], "explanations": {"打游戏": "正确：打游戏是玩电子游戏，可以在家进行。", "爬山": "语义：爬山要到山上去，与“在家”矛盾。", "逛街": "语义：逛街要到街上去，与“在家”矛盾。", "游泳": "搭配：“游泳”需要泳池或水域，在家里不搭配。"}, "sentence_index": 0, "correct_answer": "打游戏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末下午，叔叔们在操场边打游戏，每人跑了三圈。", "explanation": "这里应该用〈跑步〉。“打游戏”指玩游戏，不指在操场上跑圈这类体育活动。"}, {"text": "爷爷在公园里打游戏，棋子摆得整整齐齐。", "explanation": "这里应该用〈下棋〉。象棋等棋类要说“下”，“打游戏”只指玩电子游戏，不能用来指下棋。"}, {"text": "他每天下午和同学打游戏，在球场上跑了两个小时。", "explanation": "这里应该用〈踢足球〉。“打游戏”只指玩电子游戏，不指在球场上跑动的体育运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打游戏", "is_correct": true, "explanation": "正确：下雨天不能出去，只能在屋里打游戏。"}, {"text": "放风筝", "is_correct": false, "explanation": "语义：放风筝要在户外有风的地方，与“在屋里”矛盾。"}, {"text": "赶集", "is_correct": false, "explanation": "语义：赶集要去集市，与“不能出去”和“在屋里”矛盾。"}, {"text": "跳伞", "is_correct": false, "explanation": "搭配：“跳伞”需要飞机和降落伞，在屋里不搭配。"}], "explanations": {"打游戏": "正确：下雨天不能出去，只能在屋里打游戏。", "放风筝": "语义：放风筝要在户外有风的地方，与“在屋里”矛盾。", "赶集": "语义：赶集要去集市，与“不能出去”和“在屋里”矛盾。", "跳伞": "搭配：“跳伞”需要飞机和降落伞，在屋里不搭配。"}, "sentence_index": 6, "correct_answer": "打游戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起手机打游戏，跟妈妈聊了半个小时。", "explanation": "这里应该用〈打电话〉。跟人聊天要说“打电话”，“打游戏”是玩电子游戏。"}, {"text": "妈妈在厨房里打游戏，准备做蛋糕用的鸡蛋。", "explanation": "这里应该用〈打鸡蛋〉。搅拌鸡蛋要说“打鸡蛋”，“打游戏”是玩电子游戏。"}, {"text": "爷爷每天早上在公园里打游戏，动作又慢又稳。", "explanation": "这里应该用〈打太极拳〉。在公园慢慢练的拳要说“打太极拳”，“打游戏”是玩电子游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天打游戏了一晚上。", "corrected_sentence": "他昨天打游戏打了一晚上。", "error_description": "错误在于离合词的重复：“打游戏”是动宾结构，“了”要接在中间的动词“打”后，应说“打游戏打了一晚上”，不能说“打游戏了一晚上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打游戏得很好。", "corrected_sentence": "他打游戏打得很好。", "error_description": "错误在于补语的引出：“打游戏”后要用“打得”引出补语，应说“打游戏打得很好”，不能省略重复的“打”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
