INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92323, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "治愈是把病治好了。", "primary_collocate": null, "pronunciation": "zhì yù", "ipa": "ʈʂɻ̩˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "医生治愈了很多病人。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生治愈了我的病。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药治愈不了他的病。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中医治愈过不少老病人。", "target_word": "治愈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用新药治愈了这个孩子。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病是医生用三个月治愈的。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人能治愈这种病。", "target_word": "治愈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家医院治愈了很多癌症病人。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她希望医生能治愈她的孩子。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了两年才把自己的病治愈。", "target_word": "治愈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "治愈了", "label": "体标"}, {"form": "治愈过", "label": "体标"}, {"form": "治愈不了", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "医生等把病治好（带宾语的及物用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92323, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：医生等把病治好，正确答案。"}, {"text": "知遇", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）前字声调不同，意思是受到赏识（知遇之恩）。"}, {"text": "止于", "is_correct": false, "explanation": "zhǐ yú 与 zhì yù 两字声调都不同，意思是停在某处。"}, {"text": "至于", "is_correct": false, "explanation": "zhì yú（第二声）与 zhì yù（第四声）后字声调不同，意思是至于。"}], "explanations": {"治愈": "治愈：医生等把病治好，正确答案。", "知遇": "zhī（第一声）与 zhì（第四声）前字声调不同，意思是受到赏识（知遇之恩）。", "止于": "zhǐ yú 与 zhì yù 两字声调都不同，意思是停在某处。", "至于": "zhì yú（第二声）与 zhì yù（第四声）后字声调不同，意思是至于。"}, "sentence_index": null, "correct_answer": "治愈"}, "level_3": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：医生把病治好，填入“医生___了很多病人”中意思正确。"}, {"text": "开除", "is_correct": false, "explanation": "搭配：“开除”用于员工或学生，不能用于病人。"}, {"text": "辞退", "is_correct": false, "explanation": "搭配：“辞退”针对员工，不说辞退病人。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”的对象是书籍，与“病人”不合。"}], "explanations": {"治愈": "治愈：医生把病治好，填入“医生___了很多病人”中意思正确。", "开除": "搭配：“开除”用于员工或学生，不能用于病人。", "辞退": "搭配：“辞退”针对员工，不说辞退病人。", "出版": "语义：“出版”的对象是书籍，与“病人”不合。"}, "sentence_index": 0, "correct_answer": "治愈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去医院治愈了生病的奶奶。", "explanation": "这里应该用〈探望〉。治愈指通过治疗使病好，去医院看望病人只能说探望。"}, {"text": "修车师傅治愈了那辆汽车。", "explanation": "这里应该用〈修好〉。治愈只用于人或动物的疾病，汽车坏了要说修好。"}, {"text": "工人治愈了那座老桥。", "explanation": "这里应该用〈修复〉。治愈的对象是病人或疾病，桥坏了要说修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：医生把病治好，填入“没有人能___这种病”中意思正确。"}, {"text": "解雇", "is_correct": false, "explanation": "搭配：“解雇”针对员工，不能用于疾病。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”的对象是文件，与“这种病”不合。"}, {"text": "创作", "is_correct": false, "explanation": "语义：“创作”的对象是作品，与“这种病”不合。"}], "explanations": {"治愈": "治愈：医生把病治好，填入“没有人能___这种病”中意思正确。", "解雇": "搭配：“解雇”针对员工，不能用于疾病。", "下载": "语义：“下载”的对象是文件，与“这种病”不合。", "创作": "语义：“创作”的对象是作品，与“这种病”不合。"}, "sentence_index": 6, "correct_answer": "治愈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他花了两年才把对手治愈。", "explanation": "这里应该用〈打败〉。治愈只用于疾病，对手不能治愈，应说打败。"}, {"text": "他花了两年才把这座房子治愈。", "explanation": "这里应该用〈修缮〉。治愈只用于人或动物的疾病，房子要说修缮。"}, {"text": "他花了两年才把这幅画治愈。", "explanation": "这里应该用〈完成〉。治愈不用于作品，画要说完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小男孩被医生把治愈了。", "corrected_sentence": "那个小男孩被医生治愈了。", "error_description": "“被”字句与“把”字句不能同时使用：“被”与“把”重复标记，去掉“把”即可，应说「那个小男孩被医生治愈了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老医生还没治愈了他的哮喘。", "corrected_sentence": "这位老医生还没治愈他的哮喘。", "error_description": "“没”表示尚未发生，与“了”不能同用。应去掉“了”，改为「这位老医生还没治愈他的哮喘」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
