INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "治疗后痊愈。", "primary_collocate": null, "pronunciation": "zhì yù", "ipa": "ʈʂɻ̩˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "他的病治愈了，现在可以回家了。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这种病很难治愈。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的癌症治愈后，又回去上班了。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子的病已经治愈了。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病早发现，就可以治愈。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他治愈后，医生让他多休息。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的病一直没有治愈，她很难过。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "治愈以后，他每年还要去医院检查。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病治愈的可能性不高。", "target_word": "治愈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说他的皮肤病终于治愈了，大家都为他高兴。", "target_word": "治愈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "治愈了", "label": "体标"}, {"form": "治愈过", "label": "体标"}], "register": "中性", "sense_fingerprint": "病经治疗后痊愈（病为主语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92324, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：病经治疗后痊愈，正确答案。"}, {"text": "知遇", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）前字声调不同，意思是受到赏识（知遇之恩）。"}, {"text": "秩序", "is_correct": false, "explanation": "zhì xù（第四声）与 zhì yù 只有后字声母不同（x 与 y），意思是秩序。"}, {"text": "至于", "is_correct": false, "explanation": "zhì yú（第二声）与 zhì yù（第四声）后字声调不同，意思是至于。"}], "explanations": {"治愈": "治愈：病经治疗后痊愈，正确答案。", "知遇": "zhī（第一声）与 zhì（第四声）前字声调不同，意思是受到赏识（知遇之恩）。", "秩序": "zhì xù（第四声）与 zhì yù 只有后字声母不同（x 与 y），意思是秩序。", "至于": "zhì yú（第二声）与 zhì yù（第四声）后字声调不同，意思是至于。"}, "sentence_index": null, "correct_answer": "治愈"}, "level_3": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：病经治疗后痊愈，填入“他的病___了”中意思正确。"}, {"text": "恶化", "is_correct": false, "explanation": "语义：“恶化”指病情变重，与后文“现在可以回家了”矛盾。"}, {"text": "复发", "is_correct": false, "explanation": "语义：“复发”指旧病再次出现，与“现在可以回家了”矛盾。"}, {"text": "感染", "is_correct": false, "explanation": "语义：“感染”指病菌侵入，与后文“现在可以回家了”矛盾。"}], "explanations": {"治愈": "治愈：病经治疗后痊愈，填入“他的病___了”中意思正确。", "恶化": "语义：“恶化”指病情变重，与后文“现在可以回家了”矛盾。", "复发": "语义：“复发”指旧病再次出现，与“现在可以回家了”矛盾。", "感染": "语义：“感染”指病菌侵入，与后文“现在可以回家了”矛盾。"}, "sentence_index": 0, "correct_answer": "治愈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天都给他治愈。", "explanation": "这里应该用〈治疗〉。治愈表示病已经好了，是结果，不能说每天都治愈；治疗是过程，可以每天进行。"}, {"text": "我的自行车昨天治愈了。", "explanation": "这里应该用〈修好〉。治愈只用于人或动物的疾病，自行车坏了要说修好。"}, {"text": "他的失业终于治愈了，现在找到了工作。", "explanation": "这里应该用〈结束〉。失业不是疾病，治愈只用于病，应说结束失业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治愈", "is_correct": true, "explanation": "治愈：病经治疗后痊愈，填入“奶奶的病一直没有___”中意思正确。"}, {"text": "扩散", "is_correct": false, "explanation": "语义：“扩散”指病情蔓延，没有扩散本是好消息，与“她很难过”不合。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”指病情变重，“没有加重”是好消息，与“她很难过”的逻辑不合。"}, {"text": "患", "is_correct": false, "explanation": "配价：“患”后须接病名（患病），“没有患”缺少宾语，不成立。"}], "explanations": {"治愈": "治愈：病经治疗后痊愈，填入“奶奶的病一直没有___”中意思正确。", "扩散": "语义：“扩散”指病情蔓延，没有扩散本是好消息，与“她很难过”不合。", "加重": "语义：“加重”指病情变重，“没有加重”是好消息，与“她很难过”的逻辑不合。", "患": "配价：“患”后须接病名（患病），“没有患”缺少宾语，不成立。"}, "sentence_index": 6, "correct_answer": "治愈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人终于治愈了那座桥。", "explanation": "这里应该用〈修复〉。治愈只用于人或动物的疾病，桥坏了要说修复。"}, {"text": "他这次考试的成绩终于治愈了。", "explanation": "这里应该用〈提高〉。治愈只用于疾病，成绩要说提高，不能说治愈。"}, {"text": "这块旧地毯终于治愈了。", "explanation": "这里应该用〈清洗〉。治愈只用于疾病，地毯脏了要说清洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的病终于把治愈了。", "corrected_sentence": "她的病终于治愈了。", "error_description": "“把”字句要求“把”后带受事宾语（如“医生把她的病治愈了”），此句“把”后缺宾语，应去掉“把”，改为「她的病终于治愈了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种皮肤病终于治愈好了。", "corrected_sentence": "这种皮肤病终于治愈了。", "error_description": "“治愈”本身已含“病好”之意，后面不能再加“好”作补语。应去掉“好”，改为「这种皮肤病终于治愈了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
