INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失踪是一个人不见了，不知道去了哪里。", "primary_collocate": null, "pronunciation": "shī zōng", "ipa": "ʂɨ˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "小李失踪了，大家都不知道他去了哪里。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友突然失踪，手机也打不通。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他年轻时有个同学失踪了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个游客在森林里失踪了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失踪的消息让大家很难过。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失踪的男孩今天回家了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她失踪那天，天气很冷。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐担心他会失踪。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的孩子失踪了两天。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说失踪的人在城里。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失踪了", "label": "体标"}, {"form": "失踪者", "label": "复合"}, {"form": "失蹤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "失踪:一个人不见了，去向不明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2be088-64c2-41e3-84d8-6c7e9081f3dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失踪", "is_correct": true, "explanation": "正确。“小李失踪了”说明他去向不明，与后句“大家不知道他去了哪里”一致。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指冰雪等物质变成液体，不能用来形容人。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：枯萎多用于草木，不能说“小李枯萎了”。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭指火、灯等停止发光，不能用来形容人。"}], "explanations": {"失踪": "正确。“小李失踪了”说明他去向不明，与后句“大家不知道他去了哪里”一致。", "融化": "语义：融化指冰雪等物质变成液体，不能用来形容人。", "枯萎": "搭配：枯萎多用于草木，不能说“小李枯萎了”。", "熄灭": "语义：熄灭指火、灯等停止发光，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "失踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块冰在太阳下很快就失踪了。", "explanation": "这里应该用〈消失〉。失踪专指人下落不明，主语须是人；冰块融化应说消失。"}, {"text": "我的书包在地铁上失踪了，找了半天。", "explanation": "这里应该用〈丢失〉。失踪指人不见了；书包丢了应说丢失。"}, {"text": "这门老手艺慢慢失踪了。", "explanation": "这里应该用〈消亡〉。失踪指人下落不明；手艺衰落或不再流传应说消亡或失传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失踪", "is_correct": true, "explanation": "正确。“她失踪那天”指她不见的那天，句意自然。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：倒塌多指建筑、墙体等倒下，不能用来形容人。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：沸腾多用于液体或人群情绪，不能说“她沸腾那天”。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：凝固指液体或物质变硬，不能用来形容人。"}], "explanations": {"失踪": "正确。“她失踪那天”指她不见的那天，句意自然。", "倒塌": "语义：倒塌多指建筑、墙体等倒下，不能用来形容人。", "沸腾": "搭配：沸腾多用于液体或人群情绪，不能说“她沸腾那天”。", "凝固": "语义：凝固指液体或物质变硬，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "失踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场足球比赛因为下雨，还没开始就失踪了。", "explanation": "这里应该用〈取消〉。失踪指人下落不明，主语须是人；比赛因故不举行应说取消。"}, {"text": "雪在春天的阳光下，两天就失踪了。", "explanation": "这里应该用〈融化〉。失踪指人下落不明，主语须是人；雪变成水应说融化。"}, {"text": "我们的计划在会上突然失踪了，没有人再提起。", "explanation": "这里应该用〈搁置〉。失踪指人下落不明，主语须是人；计划暂停不再推进应说搁置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很失踪了好几天。", "corrected_sentence": "他失踪了好几天。", "error_description": "错误在“失踪”前多加了“很”。“失踪”是动作性动词，不能被“很”修饰，应直接说“失踪了好几天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "失踪那位老人还没有消息。", "corrected_sentence": "失踪的那位老人还没有消息。", "error_description": "错误在“失踪”后漏了“的”。“失踪”作定语修饰名词时要加“的”，应说“失踪的那位老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
