INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人下落不明，找不到。", "primary_collocate": null, "pronunciation": "shī zōng", "ipa": "ʂɨ˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他失踪三天了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子昨天晚上失踪了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在找失踪的老人。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的哥哥去年在山里失踪了。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很担心失踪的女儿。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人失踪以后，家人一直在找他。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失踪的学生还没有找到。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么突然失踪？", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说他在海边失踪过。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失踪的那个人的家人在报警。", "target_word": "失踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失踪了", "label": "体标"}, {"form": "失踪者", "label": "复合"}, {"form": "失蹤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "失踪:人下落不明，找不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2be088-64c2-41e3-84d8-6c7e9081f3dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失踪", "is_correct": true, "explanation": "正确。失踪指人下落不明，与“三天了”搭配自然。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指冰雪等物质变成液体，不能用来形容人。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：枯萎多用于草木，不能说“他枯萎三天了”。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：沸腾多用于液体或气氛，不能用来形容一个人。"}], "explanations": {"失踪": "正确。失踪指人下落不明，与“三天了”搭配自然。", "融化": "语义：融化指冰雪等物质变成液体，不能用来形容人。", "枯萎": "搭配：枯萎多用于草木，不能说“他枯萎三天了”。", "沸腾": "搭配：沸腾多用于液体或气氛，不能用来形容一个人。"}, "sentence_index": 0, "correct_answer": "失踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块在太阳底下很快就失踪了。", "explanation": "这里应该用〈消失〉。失踪专指人下落不明，主语须是人；冰块融化应说消失。"}, {"text": "我的护照在火车上失踪了，只能先回家。", "explanation": "这里应该用〈丢失〉。失踪指人不见了；证件、物品丢了应说丢失。"}, {"text": "这门古老的手艺在二十年前就失踪了。", "explanation": "这里应该用〈消亡〉。失踪指人下落不明；手艺衰落或不再流传应说消亡或失传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失踪", "is_correct": true, "explanation": "正确。失踪的学生指下落不明的学生，句意自然。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭指火、灯等停止发光，不能用来形容学生。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：倒塌多指建筑、墙体等倒下，不能用于学生。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：凝固用于液体或物质变硬，不能说“凝固的学生”。"}], "explanations": {"失踪": "正确。失踪的学生指下落不明的学生，句意自然。", "熄灭": "语义：熄灭指火、灯等停止发光，不能用来形容学生。", "倒塌": "语义：倒塌多指建筑、墙体等倒下，不能用于学生。", "凝固": "搭配：凝固用于液体或物质变硬，不能说“凝固的学生”。"}, "sentence_index": 6, "correct_answer": "失踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次展览因为资金不足，还没开幕就失踪了。", "explanation": "这里应该用〈取消〉。失踪指人下落不明，主语须是人；展览因故不办应说取消。"}, {"text": "这条河的水在夏天的高温下很快就失踪了。", "explanation": "这里应该用〈干涸〉。失踪指人下落不明，主语须是人；河水枯竭应说干涸。"}, {"text": "他的这个想法在讨论中突然失踪了，没人再提。", "explanation": "这里应该用〈放弃〉。失踪指人下落不明，主语须是人；想法被放弃应说放弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在失踪了三天。", "corrected_sentence": "他失踪了三天。", "error_description": "多出了一个“在”。“失踪”不表示进行中的动作，不能用“在”，应说“他失踪了三天”，不说“他在失踪了三天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "失踪那个孩子已经回家了。", "corrected_sentence": "失踪的那个孩子已经回家了。", "error_description": "错误在“失踪”后漏了“的”。“失踪”作定语修饰名词时要加“的”，应说“失踪的那个孩子”，不能说“失踪那个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
