INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故意惹别人生气，找麻烦。", "primary_collocate": null, "pronunciation": "zhǎo shì", "ipa": "tʂau˨˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你别没事找事，行不行？", "target_word": "找事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喝多了酒，到处找事。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人故意找事，想和我吵架。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没惹他，他为什么来找事？", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟总是找事，哥哥很生气。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们来这里找事，我们不要理他们。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她心情不好，就跟同学找事。", "target_word": "找事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人故意找事，说菜里有虫子。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不喜欢员工在会上找事。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再找事，我不跟你玩了。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "没事找事", "label": "固定搭配"}], "register": "口语", "sense_fingerprint": "故意惹人生气、找麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。找事（zhǎo shì）指故意惹人生气、找麻烦。"}, {"text": "早市", "is_correct": false, "explanation": "zǎo（第三声）与 zhǎo 只差声母 z 与 zh，意思是早上的集市，不是找麻烦。"}, {"text": "找死", "is_correct": false, "explanation": "第二音节 sǐ 与 shì 声母（s/zh 类平翘舌）和声调都不同，意思是寻死，与找麻烦不同。"}, {"text": "掌事", "is_correct": false, "explanation": "zhǎng 与 zhǎo 韵母不同（ang/ao），意思是主管事务，与找麻烦不同。"}], "explanations": {"找事": "正确。找事（zhǎo shì）指故意惹人生气、找麻烦。", "早市": "zǎo（第三声）与 zhǎo 只差声母 z 与 zh，意思是早上的集市，不是找麻烦。", "找死": "第二音节 sǐ 与 shì 声母（s/zh 类平翘舌）和声调都不同，意思是寻死，与找麻烦不同。", "掌事": "zhǎng 与 zhǎo 韵母不同（ang/ao），意思是主管事务，与找麻烦不同。"}, "sentence_index": null, "correct_answer": "找事"}, "level_3": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。“别没事找事”是固定说法，指别故意惹麻烦。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不惹人烦，与“行不行”这种请对方停止的语气不合。"}, {"text": "进行", "is_correct": false, "explanation": "语法：“进行”后面要带动作宾语，“没事进行”不成句。"}, {"text": "努力", "is_correct": false, "explanation": "语义：“努力”是积极的行为，不会惹人烦，与“别没事”的请求不合。"}], "explanations": {"找事": "正确。“别没事找事”是固定说法，指别故意惹麻烦。", "微笑": "语义：“微笑”不惹人烦，与“行不行”这种请对方停止的语气不合。", "进行": "语法：“进行”后面要带动作宾语，“没事进行”不成句。", "努力": "语义：“努力”是积极的行为，不会惹人烦，与“别没事”的请求不合。"}, "sentence_index": 0, "correct_answer": "找事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心找事，把窗户打破了。", "explanation": "这里应该用〈闯祸〉。找事指故意惹人，不能指无意中闯的祸。"}, {"text": "周末我们去公园找事玩，玩得很开心。", "explanation": "这里应该用〈找乐子〉。找事指故意惹人，找乐子指玩耍取乐，不能说“找事玩”。"}, {"text": "他不是故意的，只是无意中找事。", "explanation": "这里应该用〈惹事〉。找事含有故意的意思，与“无意”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。“就跟同学找事”表示心情不好时故意找茬。"}, {"text": "下雨", "is_correct": false, "explanation": "语法：“下雨”是天气现象，不能说“跟同学下雨”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不是因心情不好而对别人做的事，不能说“跟同学出生”。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“心情不好、跟同学”的语境完全不合。"}], "explanations": {"找事": "正确。“就跟同学找事”表示心情不好时故意找茬。", "下雨": "语法：“下雨”是天气现象，不能说“跟同学下雨”。", "出生": "语义：“出生”不是因心情不好而对别人做的事，不能说“跟同学出生”。", "结婚": "语义：“结婚”与“心情不好、跟同学”的语境完全不合。"}, "sentence_index": 6, "correct_answer": "找事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去找事，想问问他借的书。", "explanation": "这里应该用〈找人〉。找事指故意惹人，要表示去见某人，应说“找他”。"}, {"text": "我的钥匙丢了，我到处找事。", "explanation": "这里应该用〈找东西〉。找事指故意惹人，不能指寻找丢失的东西。"}, {"text": "谢谢你来找事，我很感动。", "explanation": "这里应该用〈帮忙〉。找事指故意惹人，不能用来表示感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天又找事我了。", "corrected_sentence": "他今天又找我的事了。", "error_description": "离合词位置错误。“找事”是离合词，宾语“我”要放在“找”和“事”之间，应说“找我的事”，不能说“找事我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找事找很厉害。", "corrected_sentence": "她找事找得很厉害。", "error_description": "补语结构错误。动词后带程度补语时，要用“得”连接，应说“找事找得很厉害”，不能直接用“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
