INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法外是不在法律管的范围里。", "primary_collocate": null, "pronunciation": "fǎ wài", "ipa": "fa˨˩˦ wai˥˩", "syllable_count": 2, "sentences": [{"text": "那些不受法律约束的人，常被称为法外之徒。", "target_word": "法外", "complexity_tier": "T3", "furigana": "nà xiē bú shòu fǎ lǜ yuē shù de rén, cháng bèi chēng wéi fǎ wài zhī tú", "sentence_source": "generated"}, {"text": "这类纠纷发生在法外之地，只能靠道德来解决。", "target_word": "法外", "complexity_tier": "T3", "furigana": "zhè lèi jiū fēn fā shēng zài fǎ wài zhī dì, zhǐ néng kào dào dé lái jiě jué", "sentence_source": "generated"}, {"text": "他以为自己是法外之徒，其实法律早已盯上了他。", "target_word": "法外", "complexity_tier": "T3", "furigana": "tā yǐ wéi zì jǐ shì fǎ wài zhī tú, qí shí fǎ lǜ zǎo yǐ dīng shàng le tā", "sentence_source": "generated"}, {"text": "网络不是法外之地，在网上说话也要守法。", "target_word": "法外", "complexity_tier": "T3", "furigana": "wǎng luò bú shì fǎ wài zhī dì, zài wǎng shàng shuō huà yě yào shǒu fǎ", "sentence_source": "generated"}, {"text": "警察说，这座城市绝不能成为法外之地。", "target_word": "法外", "complexity_tier": "T3", "furigana": "jǐng chá shuō, zhè zuò chéng shì jué bù néng chéng wéi fǎ wài zhī dì", "sentence_source": "generated"}, {"text": "那个小岛曾是法外之地，海盗常在那里藏身。", "target_word": "法外", "complexity_tier": "T3", "furigana": "nà ge xiǎo dǎo céng shì fǎ wài zhī dì, hǎi dào cháng zài nà lǐ cáng shēn", "sentence_source": "generated"}, {"text": "那些法外之地的交易，法律不会保护。", "target_word": "法外", "complexity_tier": "T3", "furigana": "nà xiē fǎ wài zhī dì de jiāo yì, fǎ lǜ bú huì bǎo hù", "sentence_source": "generated"}, {"text": "法律没有明文规定的地方，往往就是法外之地。", "target_word": "法外", "complexity_tier": "T3", "furigana": "fǎ lǜ méi yǒu míng wén guī dìng de dì fang, wǎng wǎng jiù shì fǎ wài zhī dì", "sentence_source": "generated"}, {"text": "他自以为是法外之人，最后还是被警察抓了。", "target_word": "法外", "complexity_tier": "T3", "furigana": "tā zì yǐ wéi shì fǎ wài zhī rén, zuì hòu hái shì bèi jǐng chá zhuā le", "sentence_source": "generated"}, {"text": "有人以为偏远山区是法外之地，这种想法是错的。", "target_word": "法外", "complexity_tier": "T3", "furigana": "yǒu rén yǐ wéi piān yuǎn shān qū shì fǎ wài zhī dì, zhè zhǒng xiǎng fǎ shì cuò de", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不在法律管的范围里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良民", "is_correct": false, "explanation": "语义：良民指守法的人，与“不受法律约束”的人相矛盾。"}, {"text": "法外", "is_correct": true, "explanation": "正确：“法外之徒”指不在法律管束之内的人，与“不受法律约束的人”的说法一致。"}, {"text": "君子", "is_correct": false, "explanation": "语义：君子指品德高尚的人，与“不受法律约束”的人相矛盾。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生之徒”不成说法，不能用来称呼这类人。"}], "explanations": {"良民": "语义：良民指守法的人，与“不受法律约束”的人相矛盾。", "法外": "正确：“法外之徒”指不在法律管束之内的人，与“不受法律约束的人”的说法一致。", "君子": "语义：君子指品德高尚的人，与“不受法律约束”的人相矛盾。", "学生": "搭配：“学生之徒”不成说法，不能用来称呼这类人。"}, "sentence_index": 0, "correct_answer": "法外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次交易是法外的，所以买卖双方都依法登记了。", "explanation": "这里应该用〈合法〉。「法外」指不在法律管的范围里，「合法」指符合法律；依法登记说明交易是合法的，不能说成法外。"}, {"text": "这是依据《劳动法》规定的法外假期。", "explanation": "这里应该用〈法定〉。「法外」指不在法律管的范围里，「法定」指法律规定的；假期由《劳动法》规定，应说法定假期。"}, {"text": "他违反了法外，被罚了款。", "explanation": "这里应该用〈法规〉。“法外”指法律管不到的地方，不是规定本身，不能说“违反”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规范", "is_correct": false, "explanation": "语义：规范之地指有秩序、守规矩的地方，与“法律不会保护”相矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园之地”不是常用说法，不能指交易的场所。"}, {"text": "法外", "is_correct": true, "explanation": "正确：“法外之地”指法律管不到的地方，与“法律不会保护”的语境一致。"}, {"text": "文明", "is_correct": false, "explanation": "语义：文明之地指秩序良好的地方，与“法律不会保护”相矛盾。"}], "explanations": {"规范": "语义：规范之地指有秩序、守规矩的地方，与“法律不会保护”相矛盾。", "花园": "搭配：“花园之地”不是常用说法，不能指交易的场所。", "法外": "正确：“法外之地”指法律管不到的地方，与“法律不会保护”的语境一致。", "文明": "语义：文明之地指秩序良好的地方，与“法律不会保护”相矛盾。"}, "sentence_index": 6, "correct_answer": "法外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同是法外的，却受法律保护。", "explanation": "这里应该用〈有效〉。「法外」指不在法律管的范围里；合同受法律保护说明它有效，不能说成法外。"}, {"text": "这笔开支是法外的，符合公司的财务规定。", "explanation": "这里应该用〈合理〉。「法外」指不在法律管的范围里；符合财务规定的开支应说合理，不能说法外。"}, {"text": "这家工厂的做法是法外的，已经通过了环保验收。", "explanation": "这里应该用〈合规〉。「法外」指不在法律管的范围里；通过环保验收说明做法符合规定，应说合规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片小镇成了一条法外之地，没人管。", "corrected_sentence": "这片小镇成了一块法外之地，没人管。", "error_description": "量词错误：“地”应配“块”或“片”，不能用“条”。正确说法是“一块法外之地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次纠纷发生在法外地，法院无法受理。", "corrected_sentence": "这次纠纷发生在法外之地，法院无法受理。", "error_description": "漏掉“之”：“法外之地”不能说成“法外地”，应加上“之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "粗鲁", "is_correct": false, "explanation": "与「客观」没有反义关系，「粗鲁」指言行没有礼貌。"}, {"text": "复杂", "is_correct": false, "explanation": "与「客观」没有反义关系，「复杂」指事情或关系不简单。"}, {"text": "灵活", "is_correct": false, "explanation": "与「客观」没有反义关系，「灵活」指不死板、能变通。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "粗鲁": "与「客观」没有反义关系，「粗鲁」指言行没有礼貌。", "复杂": "与「客观」没有反义关系，「复杂」指事情或关系不简单。", "灵活": "与「客观」没有反义关系，「灵活」指不死板、能变通。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "冷淡", "is_correct": false, "explanation": "与「客观」没有反义关系，「冷淡」指态度不热情。"}, {"text": "轻率", "is_correct": false, "explanation": "与「客观」没有反义关系，「轻率」指做事不认真考虑。"}, {"text": "懒惰", "is_correct": false, "explanation": "与「客观」没有反义关系，「懒惰」指不愿意做事。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "冷淡": "与「客观」没有反义关系，「冷淡」指态度不热情。", "轻率": "与「客观」没有反义关系，「轻率」指做事不认真考虑。", "懒惰": "与「客观」没有反义关系，「懒惰」指不愿意做事。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "客观是照着事情真的样子看，不加上自己的想法。", "primary_collocate": null, "pronunciation": "kè guān", "ipa": "kʰɤ˥˩ kuan˥", "syllable_count": 2, "sentences": [{"text": "看新闻要客观，别先有自己的想法。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲这件事讲得很客观，只说发生了什么。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评价别人时，我们要尽量客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章不客观，作者只写了好的一面。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判要客观，不能偏向自己喜欢的队。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看孩子的时候，常常不够客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很客观地说出了比赛的结果。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请客观一点，先把事实说清楚。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报道不客观，大家就不会相信它。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听你客观的看法，不要只说好听的。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客观地", "label": "副词形式"}, {"form": "客观性", "label": "复合"}], "register": "中性", "sense_fingerprint": "照事情真样子看、不加个人想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示照事情的真样子看，与「别先有自己的想法」相合。"}, {"text": "主观", "is_correct": false, "explanation": "语义：「主观」指加上自己的想法，与「别先有自己的想法」直接相反。"}, {"text": "偏颇", "is_correct": false, "explanation": "语义：「偏颇」指有失公允、偏向一方，与「别先有自己的想法」所要求的不偏不倚相反。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：「冷淡」形容对人或事不热情，与看新闻的要求无关。"}], "explanations": {"客观": "正确：「客观」表示照事情的真样子看，与「别先有自己的想法」相合。", "主观": "语义：「主观」指加上自己的想法，与「别先有自己的想法」直接相反。", "偏颇": "语义：「偏颇」指有失公允、偏向一方，与「别先有自己的想法」所要求的不偏不倚相反。", "冷淡": "语义：「冷淡」形容对人或事不热情，与看新闻的要求无关。"}, "sentence_index": 0, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对客人很客观，每次都很热情。", "explanation": "这里应该用〈客气〉。「客观」指不受个人想法影响，对客人的礼貌应说「客气」。"}, {"text": "小明很客观地哭了。", "explanation": "这里〈客观〉与情绪性动作不搭配；容易与〈冷静〉混淆。"}, {"text": "这盘菜很客观，大家都说好吃。", "explanation": "这里应该用〈可口〉。「客观」用于看法和判断，不用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示按事情的真样子说，与「说出了比赛的结果」相合。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：「拥挤」形容人或车多，不能修饰「说」这个动作。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：「雪白」形容颜色，不能用「雪白地说」。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：「便宜」形容价格低，不能修饰「说」这个动作。"}], "explanations": {"客观": "正确：「客观」表示按事情的真样子说，与「说出了比赛的结果」相合。", "拥挤": "语义：「拥挤」形容人或车多，不能修饰「说」这个动作。", "雪白": "语义：「雪白」形容颜色，不能用「雪白地说」。", "便宜": "语义：「便宜」形容价格低，不能修饰「说」这个动作。"}, "sentence_index": 6, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我客观地饿了，想吃点东西。", "explanation": "这里〈客观〉修饰身体感觉不合适；「客观」用于看法和判断，不指个人身体感受，容易与〈冷静〉混淆。"}, {"text": "我想听你客观的歌，不要只唱好听的。", "explanation": "这里应该用〈动听〉。「客观」用于看法和判断，不用来修饰歌曲。"}, {"text": "我想听你客观的情绪，不要只说好听的。", "explanation": "这里〈客观〉与个人感受的搭配不当；它容易与〈冷静〉混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他客观的讲述了事情的经过。", "corrected_sentence": "他客观地讲述了事情的经过。", "error_description": "「的」应为「地」：修饰动词「讲述」要用「地」，应说「客观地讲述」，「客观的讲述」中用了「的」，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师客观的评价了我的作业。", "corrected_sentence": "老师客观地评价了我的作业。", "error_description": "「客观的评价」应为「客观地评价」：修饰动词要用「地」，不用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "盲目", "is_correct": false, "explanation": "与「客观」没有反义关系，「盲目」指不加思考地行动。"}, {"text": "固执", "is_correct": false, "explanation": "与「客观」没有反义关系，「固执」指不肯改变想法。"}, {"text": "慷慨", "is_correct": false, "explanation": "与「客观」没有反义关系，「慷慨」指大方、不吝啬。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "盲目": "与「客观」没有反义关系，「盲目」指不加思考地行动。", "固执": "与「客观」没有反义关系，「固执」指不肯改变想法。", "慷慨": "与「客观」没有反义关系，「慷慨」指大方、不吝啬。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "热闹", "is_correct": false, "explanation": "与「客观」没有反义关系，「热闹」指场面人多、气氛活跃。"}, {"text": "随便", "is_correct": false, "explanation": "与「客观」没有反义关系，「随便」指不加认真考虑。"}, {"text": "热烈", "is_correct": false, "explanation": "与「客观」没有反义关系，「热烈」指情绪高涨。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "热闹": "与「客观」没有反义关系，「热闹」指场面人多、气氛活跃。", "随便": "与「客观」没有反义关系，「随便」指不加认真考虑。", "热烈": "与「客观」没有反义关系，「热烈」指情绪高涨。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "按照事物本来面貌，不受个人想法影响的。", "primary_collocate": null, "pronunciation": "kè guān", "ipa": "kʰɤ˥˩ kuan˥", "syllable_count": 2, "sentences": [{"text": "记者写新闻时，一定要客观，不能只说自己的看法。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师给分很客观，不看学生是谁。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要客观地看这件事，不能只听一个人说。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很客观，没有夸大，也没有少说。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "判断一个人，要客观，不能只看他的一面。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告很客观，里面都是真实的数字。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间说话，有时候不太容易客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官必须客观，不能因为喜欢谁就帮谁。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的评价很客观，知道哪里好，哪里不好。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你太生气了，说的话不够客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客观地", "label": "副词形式"}, {"form": "客观性", "label": "复合"}], "register": "中性", "sense_fingerprint": "按事物本来面貌、不受个人想法影响的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示不受个人想法影响，与「不能只说自己的看法」相合。"}, {"text": "主观", "is_correct": false, "explanation": "语义：「主观」指带有个人想法，与「不能只说自己的看法」的要求相反。"}, {"text": "随意", "is_correct": false, "explanation": "语义：「随意」指随便、不认真，与「一定要」所强调的严肃态度相反。"}, {"text": "武断", "is_correct": false, "explanation": "语义：「武断」指独断专行，与「不能只说自己的看法」直接冲突。"}], "explanations": {"客观": "正确：「客观」表示不受个人想法影响，与「不能只说自己的看法」相合。", "主观": "语义：「主观」指带有个人想法，与「不能只说自己的看法」的要求相反。", "随意": "语义：「随意」指随便、不认真，与「一定要」所强调的严肃态度相反。", "武断": "语义：「武断」指独断专行，与「不能只说自己的看法」直接冲突。"}, "sentence_index": 0, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很客观，总是请我们吃饭。", "explanation": "这里应该用〈客气〉。「客观」指不受个人想法影响，对人的礼貌应说「客气」。"}, {"text": "今天的天气很客观。", "explanation": "这里应该用〈晴朗〉之类形容气候的词；「客观」只用于看法和判断。"}, {"text": "他客观地吃了一碗饭。", "explanation": "这里应该用〈认真〉。「客观」修饰看法或判断，不修饰吃饭这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示不受个人想法影响，与「不太容易」的说话要求相合。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：「整齐」形容排列或样子，不能用来形容说话。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：「雪白」形容颜色，与说话的态度无关，句子荒谬。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：「粗糙」指质地不细或做事不细致，用在这里句子读不通。"}], "explanations": {"客观": "正确：「客观」表示不受个人想法影响，与「不太容易」的说话要求相合。", "整齐": "搭配：「整齐」形容排列或样子，不能用来形容说话。", "雪白": "语义：「雪白」形容颜色，与说话的态度无关，句子荒谬。", "粗糙": "语义：「粗糙」指质地不细或做事不细致，用在这里句子读不通。"}, "sentence_index": 6, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很客观地伤心了一整天。", "explanation": "这里〈客观〉与个人情绪搭配不当；它容易与〈冷静〉混淆。"}, {"text": "这件衣服很客观，我很喜欢。", "explanation": "这里应该用〈漂亮〉。「客观」用于看法和判断，不用来形容衣服。"}, {"text": "你一生气就很客观，说了很多不好听的话。", "explanation": "这里〈客观〉与情绪激动的语境相反，应用〈冷静〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇报道很客观性，没有偏向任何一方。", "corrected_sentence": "这篇报道很客观，没有偏向任何一方。", "error_description": "「很客观性」应为「很客观」：「客观性」是名词，不能受「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
