INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挑选；选择。", "primary_collocate": null, "pronunciation": "tiāo", "ipa": "tʰjɑu˥˥", "syllable_count": 1, "sentences": [{"text": "你帮我挑一件衣服吧。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在水果店里挑苹果。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多颜色，我不知道挑哪个。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈挑了一条红色的裙子。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买西瓜要会挑，不然不甜。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你挑一本喜欢的书。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以随便挑，喜欢哪个都行。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她挑了很久，还是没有买。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挑好了礼物，准备送给朋友。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们挑了一条好走的路去爬山。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑了", "label": "体标（了）"}, {"form": "挑过", "label": "体标（过）"}, {"form": "挑着", "label": "体标（着）"}, {"form": "挑挑", "label": "重叠"}, {"form": "挑选", "label": "复合"}], "register": "口语", "sense_fingerprint": "在几个选项中选择合适的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。"}, {"text": "跳", "is_correct": false, "explanation": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。"}, {"text": "条", "is_correct": false, "explanation": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。"}, {"text": "雕", "is_correct": false, "explanation": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。"}, {"text": "消", "is_correct": false, "explanation": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。"}, {"text": "标", "is_correct": false, "explanation": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。", "跳": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。", "条": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。", "天": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。", "雕": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。", "消": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。", "标": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“帮我挑一件衣服”表示从几件中选出一件，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃一件衣服”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能说“喝一件衣服”。"}, {"text": "忘", "is_correct": false, "explanation": "配价：“忘”的宾语必须是事情或经历，不能以“衣服”作宾语。"}], "explanations": {"挑": "正确。“帮我挑一件衣服”表示从几件中选出一件，符合句意。", "吃": "搭配：“吃”的宾语是食物，不能说“吃一件衣服”。", "喝": "搭配：“喝”的宾语是饮品，不能说“喝一件衣服”。", "忘": "配价：“忘”的宾语必须是事情或经历，不能以“衣服”作宾语。"}, "sentence_index": 0, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总爱挑我的毛病。", "explanation": "这里的挑是“挑剔、找出（缺点）”的意思，指挑毛病，与“从几样东西中选出一个”无关。"}, {"text": "他用扁担挑着两桶水。", "explanation": "这里的挑是“用扁担担”的意思，指用肩扛担，与“挑选”的意思完全不同。"}, {"text": "他用竹竿把门帘挑开了。", "explanation": "这里的挑读 tiǎo，是“用细长的东西拨起”的意思，与“选择”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。"}, {"text": "调", "is_correct": false, "explanation": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。"}, {"text": "添", "is_correct": false, "explanation": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。", "超": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。", "烧": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。", "调": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。", "添": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“随便挑，喜欢哪个都行”表示从多个中选择。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“喜欢哪个都行”的选择义矛盾。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指使东西跌落破碎，不用于从多个中选择。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与句中“随便……喜欢哪个都行”的挑选意思不符。"}], "explanations": {"挑": "正确。“随便挑，喜欢哪个都行”表示从多个中选择。", "扔": "语义：“扔”是丢弃，与“喜欢哪个都行”的选择义矛盾。", "摔": "搭配：“摔”指使东西跌落破碎，不用于从多个中选择。", "咬": "语义：“咬”是用牙齿咬，与句中“随便……喜欢哪个都行”的挑选意思不符。"}, "sentence_index": 6, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挑灯夜读，很认真。", "explanation": "这里的挑是“拨亮灯芯”的意思，指挑亮油灯，与“从多样东西中选择”无关。"}, {"text": "她在布上挑花，绣得很漂亮。", "explanation": "这里的挑是“刺绣挑花”的意思，指用针在布上绣出花纹，与“选择”的意思不同。"}, {"text": "他用针挑出了鱼刺。", "explanation": "这里的挑是“拨出、剔除”的意思，指用针拨出异物，与“选择”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在挑了一件很好看的外套。", "corrected_sentence": "他正在挑一件很好看的外套。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用，应去掉“了”。错误形式：正在挑了；正确形式：正在挑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹挑了一本红色的裙子。", "corrected_sentence": "妹妹挑了一条红色的裙子。", "error_description": "量词错误：“裙子”的量词是“条”，“本”用于书，不能说“一本裙子”。错误形式：一本裙子；正确形式：一条裙子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "泄漏是东西从小口子里漏出去。", "primary_collocate": null, "pronunciation": "xiè lòu", "ipa": "ɕje˥˩ lou˥˩", "syllable_count": 2, "sentences": [{"text": "水管坏了，水一直在泄漏。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤气罐有一个小洞，煤气正在泄漏。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油箱破了，汽油慢慢泄漏出来。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车下面有油泄漏，地上湿了一片。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里有煤气泄漏的味道。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管子裂了，热水从那里泄漏出去。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人很快发现了泄漏的地方。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓶子没拧紧，里面的水泄漏了。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个罐子不会泄漏，你放心用。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球上有小洞，气慢慢泄漏。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "泄漏了", "label": "完成体"}, {"form": "泄漏着", "label": "持续体"}, {"form": "泄漏过", "label": "经历体"}, {"form": "泄漏事故", "label": "复合词"}], "register": "中性", "sense_fingerprint": "液体或气体从小口子漏出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "泄漏", "is_correct": true, "explanation": "泄漏指液体从小口子漏出，与“水管坏了”搭配，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：水不会唱歌，句意不通。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”需要有生命的施动者和受动者，水不能拥抱。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：水不会睡觉，句意不通。"}], "explanations": {"泄漏": "泄漏指液体从小口子漏出，与“水管坏了”搭配，符合句意。", "唱歌": "语义：水不会唱歌，句意不通。", "拥抱": "配价：“拥抱”需要有生命的施动者和受动者，水不能拥抱。", "睡觉": "语义：水不会睡觉，句意不通。"}, "sentence_index": 0, "correct_answer": "泄漏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水太满，从杯子里泄漏出来了。", "explanation": "这里应该用〈溢出〉。杯子里的水满出来是溢出，泄漏指从破口漏出。"}, {"text": "他从口袋里泄漏出一支笔。", "explanation": "这里应该用〈掏出〉。泄漏指液体或气体从小口子漏出去，从口袋里拿出一支笔要用〈掏出〉。"}, {"text": "他把书泄漏在桌子上。", "explanation": "这里应该用〈放〉。泄漏指液体或气体从小口子漏出去，把书放在桌上要用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泄漏", "is_correct": true, "explanation": "泄漏指液体或气体从小口子漏出，修饰“地方”，符合句意。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠指无法入睡，不能用来修饰“地方”。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣是人的动作，不能修饰“地方”表示漏出的位置。"}, {"text": "叹息", "is_correct": false, "explanation": "搭配：“叹息”不与“地方”搭配，不能说“叹息的地方”。"}], "explanations": {"泄漏": "泄漏指液体或气体从小口子漏出，修饰“地方”，符合句意。", "失眠": "语义：失眠指无法入睡，不能用来修饰“地方”。", "哭泣": "语义：哭泣是人的动作，不能修饰“地方”表示漏出的位置。", "叹息": "搭配：“叹息”不与“地方”搭配，不能说“叹息的地方”。"}, "sentence_index": 6, "correct_answer": "泄漏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他泄漏了一笔钱。", "explanation": "这里不能用〈泄漏〉。泄漏只说液体或气体从小口子漏出，钱财丢失要用〈丢失〉。"}, {"text": "她泄漏了一只猫。", "explanation": "这里不能用〈泄漏〉。猫是活的动物，不会从小口子漏出，应说〈走失〉。"}, {"text": "他泄漏了一座大山。", "explanation": "这里不能用〈泄漏〉。大山是固定的地形，不能从口子漏出，应说〈坍塌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "煤气罐破了，煤气正在泄漏了。", "corrected_sentence": "煤气罐破了，煤气正在泄漏。", "error_description": "时态标记错误：“正在”表示动作正在进行，句中已有“正在”时，“泄漏”后不加“了”，应说“正在泄漏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水从裂缝里泄漏出了来。", "corrected_sentence": "水从裂缝里泄漏出来了。", "error_description": "补语中的「了」位置错误：「了」应放在复合趋向补语「出来」之后，不能插在「出」和「来」之间，应说「泄漏出来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
