INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "秘密、消息等未经允许被透露出去。", "primary_collocate": null, "pronunciation": "xiè lòu", "ipa": "ɕje˥˩ lou˥˩", "syllable_count": 2, "sentences": [{"text": "有人把公司的秘密泄漏给了别人。", "target_word": "泄漏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不要泄漏出去，谁都别说。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人泄漏了考试题目。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把还没公布的消息泄漏给了朋友。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心泄漏了我们的计划。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他偷偷把公司的合同内容泄漏出去了。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你替我保密，别泄漏我的名字。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告里的数字不能泄漏给记者。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些内部资料不能泄漏，请大家注意保密。", "target_word": "泄漏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我答应过他，不会泄漏这个消息。", "target_word": "泄漏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "泄漏了", "label": "完成体"}, {"form": "泄漏着", "label": "持续体"}, {"form": "泄漏过", "label": "经历体"}, {"form": "泄漏事故", "label": "复合词"}], "register": "中性", "sense_fingerprint": "秘密或消息被不当透露", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "泄漏", "is_correct": true, "explanation": "泄漏指秘密被不当地透露出去，与“把秘密”搭配，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "语义：秘密不能被种植，句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”一般用于食物，不与“秘密”搭配。"}, {"text": "烫", "is_correct": false, "explanation": "语义：秘密不能被烫，句意不通。"}], "explanations": {"泄漏": "泄漏指秘密被不当地透露出去，与“把秘密”搭配，符合句意。", "种植": "语义：秘密不能被种植，句意不通。", "煮": "搭配：“煮”一般用于食物，不与“秘密”搭配。", "烫": "语义：秘密不能被烫，句意不通。"}, "sentence_index": 0, "correct_answer": "泄漏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "领导决定把这份报告泄漏给大家。", "explanation": "这里应该用〈公开〉。泄漏指秘密在未经许可时被透露，有意公布要用〈公开〉。"}, {"text": "老师打算泄漏成绩，让全班同学都看看。", "explanation": "这里应该用〈公布〉。泄漏是未经许可的透露，正式宣布成绩要用〈公布〉。"}, {"text": "他在会议上泄漏了一个建议，大家都很同意。", "explanation": "这里应该用〈提出〉。泄漏指秘密或消息未经允许被透露，建议是公开提出的，不能说泄漏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泄漏", "is_correct": true, "explanation": "泄漏指秘密被透露，此处指不要让名字被透露，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：名字不能被修理，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "语义：名字不能被浇，句意不通。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”需要有生命的主体，名字不能被拥抱。"}], "explanations": {"泄漏": "泄漏指秘密被透露，此处指不要让名字被透露，符合句意。", "修理": "语义：名字不能被修理，句意不通。", "浇": "语义：名字不能被浇，句意不通。", "拥抱": "配价：“拥抱”需要有生命的主体，名字不能被拥抱。"}, "sentence_index": 6, "correct_answer": "泄漏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他泄漏了那位朋友。", "explanation": "这里不能用〈泄漏〉。泄漏的宾语是秘密、消息等，人不能被泄漏，应说〈出卖〉。"}, {"text": "她泄漏了一座房子。", "explanation": "这里不能用〈泄漏〉。房子不是秘密，不能泄漏，应说〈出售〉。"}, {"text": "他泄漏了一棵树。", "explanation": "这里不能用〈泄漏〉。树不是秘密，也不是液体、气体，应说〈砍伐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把秘密泄漏了给记者。", "corrected_sentence": "他把秘密泄漏给了记者。", "error_description": "“了”位置错误：补语“给”后面才接“了”，应说“泄漏给了记者”，不能说“泄漏了给记者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我会不泄漏你的秘密。", "corrected_sentence": "我不会泄漏你的秘密。", "error_description": "否定词位置错误：“不”应放在助动词“会”前面，应说“不会泄漏”，不能说“会不泄漏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
