INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牌局中坐在对面、与自己同一方的人（搭档）。", "primary_collocate": null, "pronunciation": "duì jiā", "ipa": "tweɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "打桥牌时，我和对家配合得很好。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家出了红桃，我马上跟了一张。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我多年的对家，我们常常一起赢牌。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是一方，对家要多给我提示。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家一出大牌，我就知道该怎么打。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这局我和对家输了，下局再来。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始前，我和对家先商量了一下暗号。", "target_word": "对家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的比赛中，我的对家是个很厉害的高手。", "target_word": "对家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和对家商量好了，用同一种打法。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家点了点头，我就明白了他的意思。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "牌局中坐在对面、与自己同一方的搭档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指桥牌中同一方的搭档，与“配合”的同伴关系相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手是竞争的一方，与“配合”的同伴关系相反。"}, {"text": "裁判", "is_correct": false, "explanation": "搭配：“配合”的对象须为同伴，不能是裁判。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不参与比赛，与“配合”的协作义不符。"}], "explanations": {"对家": "对家指桥牌中同一方的搭档，与“配合”的同伴关系相符。", "对手": "语义：对手是竞争的一方，与“配合”的同伴关系相反。", "裁判": "搭配：“配合”的对象须为同伴，不能是裁判。", "观众": "语义：观众不参与比赛，与“配合”的协作义不符。"}, "sentence_index": 0, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对家是我们的对手，我们一直想打败他。", "explanation": "这里把“对家”误作〈对手〉。“对家”是与自己同一方的搭档，不是要打败的对手。"}, {"text": "对家坐在我旁边，我们是一方。", "explanation": "这里把“对家”误作〈旁边的人〉，“对家”指坐在对面的人，应改用〈上家〉或〈下家〉。"}, {"text": "我的对家就是我自己。", "explanation": "这里把“对家”误作说话人自己，“对家”指牌局中另一位同方的人，应改用〈搭档〉指他人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指同一方的搭档，与“商量暗号”的合作关系相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手是竞争的一方，不会和自己商量暗号。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立的一方，与“商量暗号”的合作义不符。"}, {"text": "警察", "is_correct": false, "explanation": "搭配：“商量暗号”的对象通常是同伴，不能是警察。"}], "explanations": {"对家": "对家指同一方的搭档，与“商量暗号”的合作关系相符。", "对手": "语义：对手是竞争的一方，不会和自己商量暗号。", "敌人": "语义：敌人是对立的一方，与“商量暗号”的合作义不符。", "警察": "搭配：“商量暗号”的对象通常是同伴，不能是警察。"}, "sentence_index": 6, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出了一张对家，我就赢了。", "explanation": "这里把“对家”误作可以计牌的名词，“对家”指人，不能用牌的量词〈张〉计量，应说〈位〉。"}, {"text": "对家就坐在我左手边，离我最近。", "explanation": "这里把“对家”误作〈旁边的人〉。“对家”指坐在对面的人；坐在左右的人应叫〈上家〉或〈下家〉。"}, {"text": "我和对家是对手，每局都想赢他。", "explanation": "这里把“对家”误作〈对手〉。“对家”是与自己同一方的搭档，两人一起赢牌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这局我和对家们赢了三把。", "corrected_sentence": "这局我和对家赢了三把。", "error_description": "错误形式：“对家们”；正确形式：“对家”。桥牌一局中对家只有一位搭档，加“们”表示复数，与句意矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只很厉害的对家。", "corrected_sentence": "他是一位很厉害的对家。", "error_description": "错误形式：“一只对家”；正确形式：“一位对家”。“对家”指人，量词应用“位”或“个”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力气或刀枪，抢走别人的东西。", "primary_collocate": null, "pronunciation": "qiǎng jié", "ipa": "tɕʰjɑŋ˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "昨天有人在街上抢劫。", "target_word": "抢劫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人拿着刀抢劫了一家商店。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为抢劫被警察抓住了。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一个人走路，要小心有人抢劫。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人用枪抢劫银行。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刀，在路上抢劫路人的钱包。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在找昨晚抢劫的人。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢劫是犯法的事情，不能做。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个男人抢劫了一位老人的手机。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前抢劫过别人，现在后悔了。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢劫了", "label": "体标（了）"}, {"form": "抢劫过", "label": "体标（过）"}, {"form": "抢劫犯", "label": "复合"}, {"form": "抢劫案", "label": "复合"}, {"form": "搶劫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用力气或武器强行夺走别人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“抢劫”指用暴力夺取财物，与“在街上”的语境相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：街上不能洗澡，“在街上洗澡”句意说不通。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”需要教室，“在街上上课”说不通。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”描述身高变化，不指在街上发生的行为。"}], "explanations": {"抢劫": "正确。“抢劫”指用暴力夺取财物，与“在街上”的语境相符。", "洗澡": "语义：街上不能洗澡，“在街上洗澡”句意说不通。", "上课": "语义：“上课”需要教室，“在街上上课”说不通。", "长高": "体貌：“长高”描述身高变化，不指在街上发生的行为。"}, "sentence_index": 0, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地铁上抢劫了一个空座位。", "explanation": "这里应该用〈抢占〉。先于别人占据空位，并未夺取他人财物，不能说抢劫。"}, {"text": "他在网上抢劫了一张打折的机票。", "explanation": "这里应该用〈抢购〉。抢着买，并非用暴力夺取他人财物，不能说抢劫。"}, {"text": "他趁老师不注意，抢劫了同学的橡皮。", "explanation": "这里应该用〈偷〉。悄悄拿走，没有使用暴力或威胁，应说偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“抢劫的人”指作案的人，与“找”的语境相符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书刊，“昨晚出版的人”与找人的语境不符。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”说的是体形变化，不能用来修饰警察要找的作案人。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能说“下雨的人”，句意不通。"}], "explanations": {"抢劫": "正确。“抢劫的人”指作案的人，与“找”的语境相符。", "出版": "搭配：“出版”的对象是书刊，“昨晚出版的人”与找人的语境不符。", "变胖": "体貌：“变胖”说的是体形变化，不能用来修饰警察要找的作案人。", "下雨": "语义：“下雨”是天气现象，不能说“下雨的人”，句意不通。"}, "sentence_index": 6, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在超市抢劫了一瓶酒，还没付钱。", "explanation": "这里应该用〈偷窃〉。抢劫需要当场使用暴力或威胁，悄悄拿走商品而不付钱应说偷窃。"}, {"text": "他用假消息抢劫了老人的钱。", "explanation": "这里应该用〈骗〉。用欺骗手段获取钱财，没有暴力或威胁，不能说抢劫。"}, {"text": "很多人一早就去商场抢劫打折的商品。", "explanation": "这里应该用〈抢购〉。抢购是争着买，不是用力气或刀枪抢走财物，不能说抢劫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个青年在夜里被抢劫了一家便利店。", "corrected_sentence": "两个青年在夜里抢劫了一家便利店。", "error_description": "“被”把“两个青年”变成受害者，而“便利店”并非他们所有，句意不通；应去掉“被”。错误形式：被抢劫了一家便利店；正确形式：抢劫了一家便利店。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有抢劫了一家银行。", "corrected_sentence": "他没有抢劫过银行。", "error_description": "“没有”与“了”不能搭配，表示没有过的经历应用体标“过”。错误形式：没有抢劫了；正确形式：没有抢劫过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
