INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用暴力夺取他人财物。", "primary_collocate": null, "pronunciation": "qiǎng jié", "ipa": "tɕʰjɑŋ˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "几个年轻人在夜里抢劫路人。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用暴力抢劫别人的钱。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人抢劫后跑了。", "target_word": "抢劫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说，昨晚有人抢劫了一家珠宝店。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢劫的人被判了五年。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打了司机，还抢劫了他的车。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候家里穷，但从来没有抢劫过。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到了抢劫出租车的人。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她害怕晚上回家时有人抢劫。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢劫别人的东西，是严重的犯罪。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢劫了", "label": "体标（了）"}, {"form": "抢劫过", "label": "体标（过）"}, {"form": "抢劫犯", "label": "复合"}, {"form": "抢劫案", "label": "复合"}, {"form": "搶劫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使用暴力夺取他人的财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“抢劫路人”指用暴力夺取路人的财物，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃路人”说不通，句意荒谬。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗路人”不能指向人，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语是文字，不能说“写路人”。"}], "explanations": {"抢劫": "正确。“抢劫路人”指用暴力夺取路人的财物，符合句意。", "吃": "语义：“吃路人”说不通，句意荒谬。", "洗": "语义：“洗路人”不能指向人，句意不通。", "写": "搭配：“写”的宾语是文字，不能说“写路人”。"}, "sentence_index": 0, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一开会就抢劫了前排的座位。", "explanation": "这里应该用〈抢占〉。先于别人占据座位，并未夺取他人财物，不能说抢劫。"}, {"text": "她在网上抢劫了一台打折的电脑。", "explanation": "这里应该用〈抢购〉。抢着买，并非用暴力夺取他人财物，不能说抢劫。"}, {"text": "他夜里摸进邻居家，抢劫了一袋大米。", "explanation": "这里应该用〈偷〉。悄悄拿走，没有使用暴力或威胁，应说偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“从来没有抢劫过”与“家里穷，但”构成对比，符合句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与句中的转折语义不合，“从来没有洗澡过”句意说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不能与“家里穷，但从来没有……过”构成对比，句意不通。"}, {"text": "抛光", "is_correct": false, "explanation": "搭配：“抛光”的对象是物件表面，不用于人的行为。"}], "explanations": {"抢劫": "正确。“从来没有抢劫过”与“家里穷，但”构成对比，符合句意。", "洗澡": "语义：“洗澡”与句中的转折语义不合，“从来没有洗澡过”句意说不通。", "吃饭": "语义：“吃饭”不能与“家里穷，但从来没有……过”构成对比，句意不通。", "抛光": "搭配：“抛光”的对象是物件表面，不用于人的行为。"}, "sentence_index": 6, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一进门就抢劫了最好的位置。", "explanation": "这里应该用〈抢占〉。抢占是先于别人占据，不涉及夺取他人财物，不能说抢劫。"}, {"text": "他打电话抢劫了一位老人的存款。", "explanation": "这里应该用〈骗〉。通过电话欺骗取得钱财，不是靠暴力或威胁，不能说抢劫。"}, {"text": "他夜里抢劫了邻居家的自行车，没有被发现。", "explanation": "这里应该用〈偷〉。悄悄拿走、没有使用暴力，应说偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一名男子昨晚把抢劫了一辆出租车。", "corrected_sentence": "一名男子昨晚抢劫了一辆出租车。", "error_description": "“把”字句中“把”后须带宾语，此句“把”后直接接动词，缺少宾语；应去掉“把”。错误形式：把抢劫了一辆出租车；正确形式：抢劫了一辆出租车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在抢劫了路人的钱包。", "corrected_sentence": "他正在抢劫路人的钱包。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用，应去掉“了”。错误形式：正在抢劫了；正确形式：正在抢劫。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
