INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92341, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演绎是把故事一点点演出来或讲出来。", "primary_collocate": null, "pronunciation": "yǎn yì", "ipa": "jɛn˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷喜欢给孩子演绎老故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在台上演绎这个小故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用声音把故事一点点演绎出来。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，同学们演绎了一个童话故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个故事演绎得很生动，大家都笑了。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把那个传说演绎得很有意思。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家演绎课文里的故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人把这个故事演绎了一遍。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小剧团在街上演绎民间故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用动作和声音演绎这个故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演绎了", "label": "体标"}, {"form": "演绎过", "label": "体标"}, {"form": "演绎着", "label": "体标"}, {"form": "演繹", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把一个故事一点点演出来或讲出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演绎", "is_correct": true, "explanation": "演绎：把故事一点点演出来或讲出来，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理用于器物，不能用于给孩子讲故事。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指移动物体，与讲述故事不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不能与“故事”搭配。"}], "explanations": {"演绎": "演绎：把故事一点点演出来或讲出来，符合句意。", "修理": "语义：修理用于器物，不能用于给孩子讲故事。", "搬运": "语义：搬运指移动物体，与讲述故事不符。", "擦": "搭配：“擦”不能与“故事”搭配。"}, "sentence_index": 0, "correct_answer": "演绎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他演绎了一辆自行车。", "explanation": "这里应该用〈修〉。演绎不指修理，修自行车要说修。"}, {"text": "妈妈演绎了一顿饭。", "explanation": "这里应该用〈做〉。演绎不指做饭，做饭要说做。"}, {"text": "奶奶用毛线演绎了一件毛衣。", "explanation": "这里应该用〈织〉。演绎不指编织，织毛衣要说织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演绎", "is_correct": true, "explanation": "演绎：把故事演出来，符合句意。"}, {"text": "修补", "is_correct": false, "explanation": "语义：修补指修复破损的东西，不能用于讲课文中的故事。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指把物体分开，与讲述故事无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“故事”搭配。"}], "explanations": {"演绎": "演绎：把故事演出来，符合句意。", "修补": "语义：修补指修复破损的东西，不能用于讲课文中的故事。", "切割": "语义：切割指把物体分开，与讲述故事无关。", "洗": "搭配：“洗”不能与“故事”搭配。"}, "sentence_index": 6, "correct_answer": "演绎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们用推车演绎了这箱货物。", "explanation": "这里应该用〈搬〉。演绎不指移动物品，搬货物要说搬。"}, {"text": "她每天演绎一次地板。", "explanation": "这里应该用〈擦〉。演绎不表示清洁，擦地板要说擦。"}, {"text": "爸爸用胶水演绎了那张照片。", "explanation": "这里应该用〈粘〉。演绎不指粘贴，把照片粘上要说粘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手势把童话一点点的演绎出来。", "corrected_sentence": "他用手势把童话一点点演绎出来。", "error_description": "状语标记错误：“一点点”作状语修饰“演绎”时，应用“地”或不加助词，不能用“的”。正确形式：一点点（地）演绎出来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥把整段对话演绎的很有趣。", "corrected_sentence": "哥哥把整段对话演绎得很有趣。", "error_description": "补语标记错误：程度补语前要用“得”，写成“的”是错误的。正确形式：演绎得很有趣。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
