INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用表演或作品把角色或感觉展现出来。", "primary_collocate": null, "pronunciation": "yǎn yì", "ipa": "jɛn˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "这位演员把老人演绎得很真实。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演用新方法演绎了这个经典故事。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用歌声演绎了这首老歌。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师用衣服演绎夏天的感觉。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影演绎了一个普通人的梦想。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用音乐演绎自己的心情。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈演员用动作演绎了春天。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家用颜色演绎出城市的夜晚。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生演绎课文里的人物。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个角色，不同的演员演绎得不一样。", "target_word": "演绎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演绎了", "label": "体标"}, {"form": "演绎过", "label": "体标"}, {"form": "演绎着", "label": "体标"}, {"form": "演繹", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用表演、歌声、设计等作品把角色或感觉展现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演绎", "is_correct": true, "explanation": "演绎：用表演或作品把角色展现出来，与“把老人……得很真实”相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指修好器物，不能用来表现人物。"}, {"text": "计算", "is_correct": false, "explanation": "语义：计算指算出数目，不能把人物“计算”得真实。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是环境或物品，不能用于人物。"}], "explanations": {"演绎": "演绎：用表演或作品把角色展现出来，与“把老人……得很真实”相符。", "修理": "语义：修理指修好器物，不能用来表现人物。", "计算": "语义：计算指算出数目，不能把人物“计算”得真实。", "打扫": "搭配：“打扫”的对象是环境或物品，不能用于人物。"}, "sentence_index": 0, "correct_answer": "演绎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用扫帚演绎了这个房间。", "explanation": "这里应该用〈扫〉。演绎不指清扫，扫房间要说扫。"}, {"text": "这位师傅把冰箱演绎好了。", "explanation": "这里应该用〈修理〉。演绎不指修理机器，把冰箱弄好要说修理。"}, {"text": "他用吸尘器演绎了整个客厅。", "explanation": "这里应该用〈打扫〉。演绎不表示清洁，用吸尘器弄干净要说打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演绎", "is_correct": true, "explanation": "演绎：用动作把春天展现出来，符合句意。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪指剪去多余的枝叶，不能用于表现季节。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指移动物体，与用动作表现春天不符。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是可度量的事物，春天不能被测量。"}], "explanations": {"演绎": "演绎：用动作把春天展现出来，符合句意。", "修剪": "语义：修剪指剪去多余的枝叶，不能用于表现季节。", "搬运": "语义：搬运指移动物体，与用动作表现春天不符。", "测量": "搭配：“测量”的对象是可度量的事物，春天不能被测量。"}, "sentence_index": 6, "correct_answer": "演绎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用烤箱演绎了一块蛋糕。", "explanation": "这里应该用〈烤〉。演绎不表示烘烤食物，用烤箱做蛋糕要说烤。"}, {"text": "我每天用洗衣机演绎衣服。", "explanation": "这里应该用〈洗〉。演绎不表示清洗衣物，洗衣服要说洗。"}, {"text": "他把这张桌子演绎到了楼上。", "explanation": "这里应该用〈搬〉。演绎不指移动物体，把桌子搬上楼要说搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那个角色演绎的很自然。", "corrected_sentence": "他把那个角色演绎得很自然。", "error_description": "补语标记错误：“演绎”后带程度补语时要用“得”连接，写成“的”是错误的。正确形式：演绎得很自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用吉他演绎得这首老歌。", "corrected_sentence": "她用吉他演绎这首老歌。", "error_description": "结构助词错误：“演绎”后直接带宾语“这首老歌”时不加“得”，“得”只用于带补语的结构。正确形式：用吉他演绎这首老歌。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
