INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把两种事物放在一起比较，看出差别。", "primary_collocate": null, "pronunciation": "duì bǐ", "ipa": "tweɪ˥˩ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "对比两个城市，差别很大。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家对比了两种水的成分。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把中文和英文对比，会有新发现。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对比新旧产品的质量。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对比一下就知道哪个更好。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生对比两个故事的结尾。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生对比了病人前后的检查结果。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们对比过很多种品牌。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对比这两张图，你能看出什么？", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边看一边对比着价格。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对比了", "label": "体标"}, {"form": "对比过", "label": "体标"}, {"form": "对比着", "label": "体标"}, {"form": "对比度", "label": "复合"}], "register": "中性", "sense_fingerprint": "把两种事物放在一起比较以看出差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把两个城市放在一起看差别。"}, {"text": "烧", "is_correct": false, "explanation": "语义：城市不能用来烧，句子意思荒谬。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”不能带“城市”作宾语，搭配不当。"}, {"text": "闻", "is_correct": false, "explanation": "语义：闻城市无法看出差别，句子读不通。"}], "explanations": {"对比": "正确答案。“对比”指把两个城市放在一起看差别。", "烧": "语义：城市不能用来烧，句子意思荒谬。", "养": "搭配：“养”不能带“城市”作宾语，搭配不当。", "闻": "语义：闻城市无法看出差别，句子读不通。"}, "sentence_index": 0, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游对比了这座古城。", "explanation": "这里应该用〈介绍〉。对比要把两样东西放在一起看差别，介绍一座古城不用「对比」。"}, {"text": "护士对比了那个病人。", "explanation": "这里应该用〈照顾〉。对比不能只针对一个人，照顾病人要说「照顾」。"}, {"text": "她对比了一首歌。", "explanation": "这里应该用〈演唱〉。对比要求两样以上的东西，演唱一首歌不能说「对比」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把病人前后的检查结果放在一起比较。"}, {"text": "吃", "is_correct": false, "explanation": "语义：检查结果不能吃，句子读不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：检查结果不能喝，句子意思荒谬。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“检查结果”作宾语。"}], "explanations": {"对比": "正确答案。“对比”指把病人前后的检查结果放在一起比较。", "吃": "语义：检查结果不能吃，句子读不通。", "喝": "语义：检查结果不能喝，句子意思荒谬。", "跳": "配价：“跳”是不及物动词，不能带“检查结果”作宾语。"}, "sentence_index": 6, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对比了一台电脑。", "explanation": "这里应该用〈购买〉。对比要两样东西放在一起看，只针对一台电脑时不能用「对比」。"}, {"text": "他对比了房间。", "explanation": "这里应该用〈打扫〉。对比需要两样东西，只有一个房间时不能说「对比房间」。"}, {"text": "他对比了蜡烛。", "explanation": "这里应该用〈点燃〉。对比不用于只有一支蜡烛的动作，应说「点燃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们对比了出两款手机的差别。", "corrected_sentence": "他们对比出了两款手机的差别。", "error_description": "语序错误。「出」应紧跟「对比」，说「对比出」，「了」放在「出」之后，「对比了出」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们对比不到这两种药的区别。", "corrected_sentence": "我们对比不出这两种药的区别。", "error_description": "补语错误。可能补语的否定形式应是「对比不出」，用「出」表示看出差别；「对比不到」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
