INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92345, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放在前面遮住，不让看见或照到。", "primary_collocate": null, "pronunciation": "dǎng", "ipa": "tɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "大树挡住了太阳。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人很高，把电影挡住了。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手挡着脸，不让他拍照。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撑伞挡雨。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘挡着阳光，屋里很暗。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站开一点，别挡着我看黑板。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山挡着风，这里冬天不冷。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用书挡着头，跑进了教室。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙把外面挡住了，什么也看不见。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿帽子挡太阳。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挡了", "label": "体标"}, {"form": "挡着", "label": "体标"}, {"form": "挡住", "label": "复合"}, {"form": "遮挡", "label": "复合"}, {"form": "擋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挡：放在前面遮住，不让看见或照到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92345, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：挡（dǎng）意思是遮住，放在前面不让看见或照到。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎng 韵母不同（-n 与 -ng），声调相同，“胆”意思是胆子。"}, {"text": "当", "is_correct": false, "explanation": "dāng（第一声）与 dǎng（第三声）声调不同，“当”意思是应当、担任。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng 与 dǎng 声母不同（t 与 d），声调相同，“躺”意思是横卧。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 dǎng（第三声）声调不同，“荡”意思是摇动、晃动。"}], "explanations": {"挡": "正确：挡（dǎng）意思是遮住，放在前面不让看见或照到。", "胆": "dǎn 与 dǎng 韵母不同（-n 与 -ng），声调相同，“胆”意思是胆子。", "当": "dāng（第一声）与 dǎng（第三声）声调不同，“当”意思是应当、担任。", "躺": "tǎng 与 dǎng 声母不同（t 与 d），声调相同，“躺”意思是横卧。", "荡": "dàng（第四声）与 dǎng（第三声）声调不同，“荡”意思是摇动、晃动。"}, "sentence_index": null, "correct_answer": "挡"}, "level_3": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：“挡住了太阳”表示遮住太阳，符合句意。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是把东西换钱给别人，太阳不能被卖，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞食，太阳不是食物，句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是把组合的东西拆开，太阳不能被拆，句意不通。"}], "explanations": {"挡": "正确：“挡住了太阳”表示遮住太阳，符合句意。", "卖": "语义：“卖”是把东西换钱给别人，太阳不能被卖，句意不通。", "吃": "语义：“吃”指吞食，太阳不是食物，句意不通。", "拆": "语义：“拆”是把组合的东西拆开，太阳不能被拆，句意不通。"}, "sentence_index": 0, "correct_answer": "挡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把衣服挡进了箱子里。", "explanation": "这里应该用〈装〉。装是把东西放进容器，“挡”指放在前面遮住或不让通过，不能说“挡进箱子里”。"}, {"text": "她轻轻挡开了窗户。", "explanation": "这里应该用〈推〉。推是用力使物体移动，“挡”指遮住或阻拦，不能说“挡开窗户”。"}, {"text": "他挡上了一件外套，准备出门。", "explanation": "这里应该用〈穿〉。穿是把衣服套在身上，“挡”指放在前面遮住或不让通过，不能说“挡上外套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92345, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：挡（dǎng）意思是遮住，放在前面不让看见或照到。"}, {"text": "档", "is_correct": false, "explanation": "dàng（第四声）与 dǎng（第三声）声调不同，“档”意思是档次、档案。"}, {"text": "港", "is_correct": false, "explanation": "gǎng 与 dǎng 声母不同（g 与 d），声调相同，“港”意思是港口。"}, {"text": "绑", "is_correct": false, "explanation": "bǎng 与 dǎng 声母不同（b 与 d），声调相同，“绑”意思是用绳子捆住。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 dǎng 声母不同（l 与 d），声调相同，“朗”意思是明亮、清楚。"}], "explanations": {"挡": "正确：挡（dǎng）意思是遮住，放在前面不让看见或照到。", "档": "dàng（第四声）与 dǎng（第三声）声调不同，“档”意思是档次、档案。", "港": "gǎng 与 dǎng 声母不同（g 与 d），声调相同，“港”意思是港口。", "绑": "bǎng 与 dǎng 声母不同（b 与 d），声调相同，“绑”意思是用绳子捆住。", "朗": "lǎng 与 dǎng 声母不同（l 与 d），声调相同，“朗”意思是明亮、清楚。"}, "sentence_index": null, "correct_answer": "挡"}, "level_3": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：“挡着风”表示山遮住了风，符合句意。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”是用肩承担重物，山不能扛风。"}, {"text": "开", "is_correct": false, "explanation": "搭配：说风一般用“刮”“吹”，不说“开风”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，风不能被写。"}], "explanations": {"挡": "正确：“挡着风”表示山遮住了风，符合句意。", "扛": "语义：“扛”是用肩承担重物，山不能扛风。", "开": "搭配：说风一般用“刮”“吹”，不说“开风”。", "写": "语义：“写”指书写文字，风不能被写。"}, "sentence_index": 6, "correct_answer": "挡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人挡着桌子进了门。", "explanation": "这里应该用〈抬〉。抬是用手或肩托起物体移动，“挡”是遮住或阻拦，不能用于搬运桌子。"}, {"text": "他把手挡进了口袋里。", "explanation": "这里应该用〈揣〉。揣是把东西放进衣服或口袋里，“挡”指放在前面遮住或阻拦，不能说“挡进口袋里”。"}, {"text": "他把礼物挡给了朋友。", "explanation": "这里应该用〈送〉。送是把东西交给别人，“挡”是遮住或阻拦，不能说“挡给朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "云挡了住月亮。", "corrected_sentence": "云挡住了月亮。", "error_description": "错误：补语和“了”的语序错误。“挡住”中的补语“住”要紧跟动词，“了”放在“住”之后，应说“挡住了”，不能说“挡了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用手着挡太阳。", "corrected_sentence": "他用手挡着太阳。", "error_description": "错误：“着”位置错误。持续态标记“着”应紧跟动词“挡”，写作“挡着”，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
