INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻拦，不让人或东西通过。", "primary_collocate": null, "pronunciation": "dǎng", "ipa": "tɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "大雨挡不住他回家。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把车挡在了路口外。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也挡不了他去学校。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一座大山挡了我们的路。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想走，可是爸爸挡着门。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车挡了路，我过不去。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用木板把路挡起来了。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路这么窄，别在这儿挡路。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想去，爸爸也挡不住她。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往前一站，把我们挡在门外。", "target_word": "挡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挡了", "label": "体标"}, {"form": "挡着", "label": "体标"}, {"form": "挡过", "label": "体标"}, {"form": "挡住", "label": "复合"}, {"form": "擋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挡：阻拦，不让人或车通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：挡（dǎng）意思是阻拦，不让人或车通过。"}, {"text": "当", "is_correct": false, "explanation": "dāng（第一声）与 dǎng（第三声）声调不同，“当”意思是应当、担任。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 dǎng（第三声）声调不同，“荡”意思是摇动、晃动。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng 与 dǎng 声母不同（t 与 d），声调相同，“躺”意思是横卧。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 dǎng 声母不同（l 与 d），声调相同，“朗”意思是明亮、清楚。"}], "explanations": {"挡": "正确：挡（dǎng）意思是阻拦，不让人或车通过。", "当": "dāng（第一声）与 dǎng（第三声）声调不同，“当”意思是应当、担任。", "荡": "dàng（第四声）与 dǎng（第三声）声调不同，“荡”意思是摇动、晃动。", "躺": "tǎng 与 dǎng 声母不同（t 与 d），声调相同，“躺”意思是横卧。", "朗": "lǎng 与 dǎng 声母不同（l 与 d），声调相同，“朗”意思是明亮、清楚。"}, "sentence_index": null, "correct_answer": "挡"}, "level_3": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：“挡不住”表示阻止不了，符合句意。"}, {"text": "照", "is_correct": false, "explanation": "语义：“照”指光线照射，与“阻止他回家”的句意不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理、修补，“修不住”不成句，与“阻止他回家”的句意不符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西交给别人，与阻止行路无关。"}], "explanations": {"挡": "正确：“挡不住”表示阻止不了，符合句意。", "照": "语义：“照”指光线照射，与“阻止他回家”的句意不符。", "修": "语义：“修”指修理、修补，“修不住”不成句，与“阻止他回家”的句意不符。", "送": "语义：“送”指把东西交给别人，与阻止行路无关。"}, "sentence_index": 0, "correct_answer": "挡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把衣服挡在晾衣架上。", "explanation": "这里应该用〈挂〉。挂是把东西悬挂起来，“挡”指阻拦或遮住，不能用于晾衣服。"}, {"text": "他弯腰挡起一个硬币。", "explanation": "这里应该用〈捡〉。捡是弯腰拾起地上的东西，“挡”指阻拦或遮住，不能说“挡起硬币”。"}, {"text": "他把信挡进了信箱。", "explanation": "这里应该用〈投〉。投是把东西放进某处，“挡”指阻拦或遮住，不能说“挡进信箱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：挡（dǎng）意思是阻拦。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎng 韵母不同（-n 与 -ng），声调相同，“胆”意思是胆子。"}, {"text": "港", "is_correct": false, "explanation": "gǎng 与 dǎng 声母不同（g 与 d），声调相同，“港”意思是港口。"}, {"text": "绑", "is_correct": false, "explanation": "bǎng 与 dǎng 声母不同（b 与 d），声调相同，“绑”意思是用绳子捆住。"}, {"text": "嗓", "is_correct": false, "explanation": "sǎng 与 dǎng 声母不同（s 与 d），声调相同，“嗓”意思是嗓子。"}, {"text": "档", "is_correct": false, "explanation": "dàng（第四声）与 dǎng（第三声）声调不同，“档”意思是档次。"}], "explanations": {"挡": "正确：挡（dǎng）意思是阻拦。", "胆": "dǎn 与 dǎng 韵母不同（-n 与 -ng），声调相同，“胆”意思是胆子。", "港": "gǎng 与 dǎng 声母不同（g 与 d），声调相同，“港”意思是港口。", "绑": "bǎng 与 dǎng 声母不同（b 与 d），声调相同，“绑”意思是用绳子捆住。", "嗓": "sǎng 与 dǎng 声母不同（s 与 d），声调相同，“嗓”意思是嗓子。", "档": "dàng（第四声）与 dǎng（第三声）声调不同，“档”意思是档次。"}, "sentence_index": null, "correct_answer": "挡"}, "level_3": {"options": [{"text": "挡", "is_correct": true, "explanation": "正确：“挡起来”表示用东西遮住或拦住，符合“用木板”的句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与“用木板把路……起来”的句意不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”需要用水和火加热食物，不能用于木板和路。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是能清洗的东西，不能说“洗路”。"}], "explanations": {"挡": "正确：“挡起来”表示用东西遮住或拦住，符合“用木板”的句意。", "唱": "语义：“唱”指发声演唱，与“用木板把路……起来”的句意不符。", "煮": "语义：“煮”需要用水和火加热食物，不能用于木板和路。", "洗": "搭配：“洗”的对象是能清洗的东西，不能说“洗路”。"}, "sentence_index": 6, "correct_answer": "挡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一杯水挡给了妈妈。", "explanation": "这里应该用〈递〉。递是把东西交到别人手里，“挡”是阻拦，不能说“挡给妈妈”。"}, {"text": "他把那只大箱子挡进了卧室。", "explanation": "这里应该用〈搬〉。搬是用手或力气把东西从一处移到另一处，“挡”指阻拦或遮住，不能说“挡进卧室”。"}, {"text": "他挡了一本书，花了十块钱。", "explanation": "这里应该用〈买〉。买是用钱换得东西，“挡”指阻拦或遮住，不能说“挡了一本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面的人挡了住我的去路。", "corrected_sentence": "前面的人挡住了我的去路。", "error_description": "错误：补语和“了”的语序错误。“挡住”中的补语“住”要紧跟动词，“了”放在“住”之后，应说“挡住了”，不能说“挡了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把孩子挡身后。", "corrected_sentence": "他把孩子挡在身后。", "error_description": "错误：“挡”后缺少处所介词“在”。表示位置时要说“挡在身后”，不能说“挡身后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汉奸是帮外来的敌人欺负自己人的坏人。", "primary_collocate": null, "pronunciation": "hàn jiān", "ipa": "xan˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "他帮外人骗自己人，大家都骂他是汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个汉奸帮敌人带路，害了很多邻居。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人愿意当汉奸。", "target_word": "汉奸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里人看不起那个给敌人送信的汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲了一个汉奸的故事，我们听得很气愤。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱帮敌人，大家说他是汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影里的汉奸，最后没有好结果。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷最恨汉奸，因为他们帮敌人欺负中国人。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人以为他是汉奸，其实他在帮自己人。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个故事里，汉奸把朋友的消息告诉了敌人。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个汉奸", "label": "量词"}, {"form": "大汉奸", "label": "复合"}, {"form": "漢奸", "label": "繁体"}], "register": "口语", "sense_fingerprint": "帮外人欺负自己人的坏人，骂人或故事里的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汉奸", "is_correct": true, "explanation": "汉奸是帮外来的敌人欺负自己人的坏人，是本题的正确答案。"}, {"text": "函件", "is_correct": false, "explanation": "hán jiàn（第二声、第四声）与 hàn jiān（第四声、第一声）声调不同，意思是信件、公文。"}, {"text": "焊件", "is_correct": false, "explanation": "hàn jiàn 与 hàn jiān 第二个音节声调不同（jiàn 第四声，jiān 第一声），意思是焊接的工件。"}, {"text": "汉江", "is_correct": false, "explanation": "hàn jiāng 与 hàn jiān 第二个音节韵尾不同（ang 与 an），意思是汉江，是一条河流的名字。"}], "explanations": {"汉奸": "汉奸是帮外来的敌人欺负自己人的坏人，是本题的正确答案。", "函件": "hán jiàn（第二声、第四声）与 hàn jiān（第四声、第一声）声调不同，意思是信件、公文。", "焊件": "hàn jiàn 与 hàn jiān 第二个音节声调不同（jiàn 第四声，jiān 第一声），意思是焊接的工件。", "汉江": "hàn jiāng 与 hàn jiān 第二个音节韵尾不同（ang 与 an），意思是汉江，是一条河流的名字。"}, "sentence_index": null, "correct_answer": "汉奸"}, "level_3": {"options": [{"text": "汉奸", "is_correct": true, "explanation": "汉奸指帮外人骗自己人的人，与句中“骗自己人”“大家都骂他”相符。"}, {"text": "恩人", "is_correct": false, "explanation": "语义：“恩人”是帮助过自己的人，与“骗自己人”“大家都骂他”矛盾。"}, {"text": "英雄", "is_correct": false, "explanation": "语义：“英雄”是大家敬佩的人，与“骗自己人”“大家都骂他”矛盾。"}, {"text": "烈士", "is_correct": false, "explanation": "语义：“烈士”指为国牺牲的人，与“骗自己人”“大家都骂他”矛盾。"}], "explanations": {"汉奸": "汉奸指帮外人骗自己人的人，与句中“骗自己人”“大家都骂他”相符。", "恩人": "语义：“恩人”是帮助过自己的人，与“骗自己人”“大家都骂他”矛盾。", "英雄": "语义：“英雄”是大家敬佩的人，与“骗自己人”“大家都骂他”矛盾。", "烈士": "语义：“烈士”指为国牺牲的人，与“骗自己人”“大家都骂他”矛盾。"}, "sentence_index": 0, "correct_answer": "汉奸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一遇到危险就跑，真是个汉奸。", "explanation": "这里应该用〈懦夫〉。汉奸指投靠敌人、出卖国家和民族利益的人，形容遇事怕死要用“懦夫”。"}, {"text": "他冒着危险保护邻居，大家都夸他是个汉奸。", "explanation": "这里应该用〈好人〉。汉奸是帮敌人欺负自己人的坏人，保护邻居、被大家夸的人不能叫汉奸。"}, {"text": "这个村子的汉奸帮大家抗击了敌人。", "explanation": "这里应该用〈英雄〉。汉奸指投靠敌人的人，不能用来形容帮大家抗击敌人的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉奸", "is_correct": true, "explanation": "汉奸是电影里投靠敌人的坏人，“最后没有好结果”与之相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“没有好结果”用于人或事件，不能搭配“天气”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是电影里的人物或事件，不能说“最后没有好结果”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地点，不能作为电影里的人物或事件来说“没有好结果”。"}], "explanations": {"汉奸": "汉奸是电影里投靠敌人的坏人，“最后没有好结果”与之相符。", "天气": "搭配：“没有好结果”用于人或事件，不能搭配“天气”。", "桌子": "搭配：“桌子”不是电影里的人物或事件，不能说“最后没有好结果”。", "厨房": "语义：“厨房”是地点，不能作为电影里的人物或事件来说“没有好结果”。"}, "sentence_index": 6, "correct_answer": "汉奸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一只汉奸，常帮敌人欺负邻居。", "explanation": "这里应该用〈个〉。汉奸指人，量词用“个”，“只”多用于动物。"}, {"text": "那棵汉奸把朋友的消息告诉了敌人。", "explanation": "这里应该用〈个〉。“棵”用于植物，指人的汉奸要用“个”。"}, {"text": "这张汉奸在村里很有名。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，指人的汉奸要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里那个给敌人送信汉奸被抓了。", "corrected_sentence": "村里那个给敌人送信的汉奸被抓了。", "error_description": "语法错误：“给敌人送信”修饰“汉奸”，中间要加“的”，应说“给敌人送信的汉奸”，去掉“的”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们把那只汉奸送进了监狱。", "corrected_sentence": "村民们把那个汉奸送进了监狱。", "error_description": "量词错误：“汉奸”指人，应用量词“个”，“只”多用于动物，应说“那个汉奸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
