INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧指出卖国家和民族利益、投靠敌人的人。", "primary_collocate": null, "pronunciation": "hàn jiān", "ipa": "xan˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "历史书里写着，这个人是有名的汉奸。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，汉奸出卖了国家的秘密。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他投靠敌人，成了人人痛恨的汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家写过一本关于汉奸的小说。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，政府审判了那个汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉奸为了钱，把国家的地图交给敌人。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一些关于抗战时期汉奸的资料。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当时的人们不会原谅投靠敌人的汉奸。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们曾经把他的祖父叫作汉奸。", "target_word": "汉奸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史老师说，汉奸是民族的耻辱。", "target_word": "汉奸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个汉奸", "label": "量词"}, {"form": "大汉奸", "label": "复合"}, {"form": "漢奸", "label": "繁体"}], "register": "书面", "sense_fingerprint": "战争年代出卖国家和民族利益、投靠敌人的人，历史用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉奸", "is_correct": true, "explanation": "汉奸是旧时出卖国家和民族利益、投靠敌人的人，与“有名的”“历史书里写着”相符。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：“海鲜”是食物，不能指人。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：“饭店”是场所，不能指一个人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“有名的”多修饰人或作品，不能修饰“桌子”。"}], "explanations": {"汉奸": "汉奸是旧时出卖国家和民族利益、投靠敌人的人，与“有名的”“历史书里写着”相符。", "海鲜": "语义：“海鲜”是食物，不能指人。", "饭店": "语义：“饭店”是场所，不能指一个人。", "桌子": "搭配：“有名的”多修饰人或作品，不能修饰“桌子”。"}, "sentence_index": 0, "correct_answer": "汉奸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一遇到危险就跑，真是个汉奸。", "explanation": "这里应该用〈懦夫〉。汉奸指投靠敌人、出卖国家利益的人，形容遇事怕死要用“懦夫”。"}, {"text": "那个汉奸在战场上为国家英勇牺牲，大家都很敬佩他。", "explanation": "这里应该用〈烈士〉。汉奸指投靠敌人、出卖国家利益的人，为国牺牲的人要说“烈士”。"}, {"text": "那位汉奸冲进火场，救出了三个孩子。", "explanation": "这里应该用〈英雄〉。汉奸指投靠敌人的人，不能用来形容舍身救人的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉奸", "is_correct": true, "explanation": "汉奸是历史上的一类人，博物馆展出关于他们的资料，与句意相符。"}, {"text": "微信", "is_correct": false, "explanation": "语义：“微信”是当代的通讯软件，与博物馆里关于历史人物的资料不相符。"}, {"text": "外卖", "is_correct": false, "explanation": "语义：“外卖”是当代的服务，与博物馆里关于历史人物的资料不相符。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“关于……的资料”一般指历史人物或事件，“空调”不构成这类话题。"}], "explanations": {"汉奸": "汉奸是历史上的一类人，博物馆展出关于他们的资料，与句意相符。", "微信": "语义：“微信”是当代的通讯软件，与博物馆里关于历史人物的资料不相符。", "外卖": "语义：“外卖”是当代的服务，与博物馆里关于历史人物的资料不相符。", "空调": "搭配：“关于……的资料”一般指历史人物或事件，“空调”不构成这类话题。"}, "sentence_index": 6, "correct_answer": "汉奸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一只汉奸，在战争中出卖了国家。", "explanation": "这里应该用〈个〉。汉奸指人，量词用“个”，“只”多用于动物。"}, {"text": "那棵汉奸把国家的地图交给了敌人。", "explanation": "这里应该用〈个〉。“棵”用于植物，指人的汉奸要用“个”。"}, {"text": "那张汉奸在历史书里写得很清楚。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，指人的汉奸要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个出卖国家秘密汉奸。", "corrected_sentence": "他是一个出卖国家秘密的汉奸。", "error_description": "语法错误：“出卖国家秘密”修饰“汉奸”，中间要加“的”，应说“出卖国家秘密的汉奸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把那只汉奸判了刑。", "corrected_sentence": "政府把那个汉奸判了刑。", "error_description": "量词错误：汉奸指人，量词应用“个”，不能用“只”（“只”多用于动物）。应说“那个汉奸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
