INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建立国家。", "primary_collocate": null, "pronunciation": "jiàn guó", "ipa": "tɕjɛn⁵¹ kwo³⁵", "syllable_count": 2, "sentences": [{"text": "这个民族在一百年前建国了。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定在海边建国。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有一位国王，带着人民来到这里建国。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了十年时间才建国。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建国以后，他们先修了路。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年是谁带领人民建国的？", "target_word": "建国", "complexity_tier": "T3", "furigana": "dāng nián shì shéi dài lǐng rén mín jiàn guó de?", "sentence_source": "generated"}, {"text": "英雄带领大家打仗，最后成功建国。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想在这块土地上建国。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们建国后，第一件事是写法律。", "target_word": "建国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在岛上刚建国，还没有自己的货币。", "target_word": "建国", "complexity_tier": "T3", "furigana": "tā men zài dǎo shàng gāng jiàn guó, hái méi yǒu zì jǐ de huò bì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "建国了", "label": "体标"}, {"form": "建国者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "建立一个国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建国", "is_correct": true, "explanation": "正确答案：建国（jiàn guó），意思是建立国家。"}, {"text": "见过", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是曾经看到，与建立国家无关。"}, {"text": "坚果", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）、guǒ（第三声）与 guó（第二声）声调都不同，意思是坚硬的果实。"}, {"text": "煎锅", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）、guō（第一声）与 guó（第二声）声调都不同，意思是煎东西用的锅。"}], "explanations": {"建国": "正确答案：建国（jiàn guó），意思是建立国家。", "见过": "guò（第四声）与 guó（第二声）声调不同，意思是曾经看到，与建立国家无关。", "坚果": "jiān（第一声）与 jiàn（第四声）、guǒ（第三声）与 guó（第二声）声调都不同，意思是坚硬的果实。", "煎锅": "jiān（第一声）与 jiàn（第四声）、guō（第一声）与 guó（第二声）声调都不同，意思是煎东西用的锅。"}, "sentence_index": null, "correct_answer": "建国"}, "level_3": {"options": [{"text": "建国", "is_correct": true, "explanation": "正确。“建国”指建立国家，与一百年前的历史语境相合。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”要带宾语，句中没有讨论的对象。"}, {"text": "访问", "is_correct": false, "explanation": "配价：“访问”要带宾语，句中没有访问的对象。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指出游，不能说一个民族在一百年前旅游了。"}], "explanations": {"建国": "正确。“建国”指建立国家，与一百年前的历史语境相合。", "讨论": "配价：“讨论”要带宾语，句中没有讨论的对象。", "访问": "配价：“访问”要带宾语，句中没有访问的对象。", "旅游": "语义：“旅游”指出游，不能说一个民族在一百年前旅游了。"}, "sentence_index": 0, "correct_answer": "建国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司在十年前建国了。", "explanation": "这里应该用〈成立〉。建国只指建立国家，公司应说成立。"}, {"text": "这个乐队在十年前建国了。", "explanation": "这里应该用〈组建〉。建国指建立国家，乐队应说组建。"}, {"text": "这所学校在十年前建国了。", "explanation": "这里应该用〈创办〉。建国只用于国家，学校应说创办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建国", "is_correct": true, "explanation": "正确。“建国”指建立国家，与“成功”搭配，表示国家建成。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“成功”与“失败”矛盾，句子说的是成功。"}, {"text": "战败", "is_correct": false, "explanation": "语义：“战败”与“成功”矛盾，不能说成功战败。"}, {"text": "考取", "is_correct": false, "explanation": "语义：“考取”指通过考试被录取，与打仗无关，句子不能说考取。"}], "explanations": {"建国": "正确。“建国”指建立国家，与“成功”搭配，表示国家建成。", "失败": "语义：“成功”与“失败”矛盾，句子说的是成功。", "战败": "语义：“战败”与“成功”矛盾，不能说成功战败。", "考取": "语义：“考取”指通过考试被录取，与打仗无关，句子不能说考取。"}, "sentence_index": 6, "correct_answer": "建国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队去年刚建国，还没有比赛经验。", "explanation": "这里应该用〈组建〉。建国指建立国家，球队应说组建。"}, {"text": "这家银行今年刚建国，还没有开门营业。", "explanation": "这里应该用〈设立〉。建国只用于国家，银行应说设立。"}, {"text": "这家小店去年刚建国，生意还不错。", "explanation": "这里应该用〈开办〉。建国只指建立国家，小店应说开办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个民族曾经建国过。", "corrected_sentence": "这个民族曾经建过国。", "error_description": "错误：“建国过”；正确：“建过国”。“建国”是动宾式离合词，“过”要插在“建”和“国”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们刚建国着时，人口只有几百人。", "corrected_sentence": "他们刚建国时，人口只有几百人。", "error_description": "错误：“建国着”；正确：“建国”。“着”表示动作的持续状态，而“建国”是瞬间完成的动作，后面不能加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚", "is_correct": true, "explanation": "正确：「聚」指聚拢，与「散」指人群走开的义项相反。"}, {"text": "吃", "is_correct": false, "explanation": "「吃」指进食，与「散」没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "「写」指书写文字，与「散」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出歌声，与「散」没有反义关系。"}], "correct_answer": "聚", "explanations": {"聚": "正确：「聚」指聚拢，与「散」指人群走开的义项相反。", "吃": "「吃」指进食，与「散」没有反义关系。", "写": "「写」指书写文字，与「散」没有反义关系。", "唱": "「唱」指发出歌声，与「散」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚集", "is_correct": true, "explanation": "正确：「聚集」指人或物集中到一起，与「散」指人群走开的义项相反。"}, {"text": "吹", "is_correct": false, "explanation": "「吹」指风或口气的流动，与「散」没有反义关系。"}, {"text": "挂", "is_correct": false, "explanation": "「挂」指悬挂，与「散」没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」指发光或明白，与「散」没有反义关系。"}], "correct_answer": "聚集", "explanations": {"聚集": "正确：「聚集」指人或物集中到一起，与「散」指人群走开的义项相反。", "吹": "「吹」指风或口气的流动，与「散」没有反义关系。", "挂": "「挂」指悬挂，与「散」没有反义关系。", "亮": "「亮」指发光或明白，与「散」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚在一起的人走开了。", "primary_collocate": null, "pronunciation": "sàn", "ipa": "san˥˩", "syllable_count": 1, "sentences": [{"text": "会开完了，大家都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影结束后，看电影的人慢慢散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，广场上的人都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课铃一响，学生们就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会结束了，客人们都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛完了，球迷们很快就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下大了，街上的人一下子就散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等人都散了，老师才离开教室。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出一结束，观众就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，朋友们都散了，我才回家。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "散了", "label": "体标"}, {"form": "散场", "label": "复合"}, {"form": "散会", "label": "复合"}], "register": "中性", "sense_fingerprint": "聚在一起的人群离开、各自走开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指聚在一起的人走开。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 sàn 声母不同（m 与 s），意思是速度低。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}], "explanations": {"散": "正确：散（sàn，第四声），指聚在一起的人走开。", "三": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。", "赞": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。", "慢": "màn 与 sàn 声母不同（m 与 s），意思是速度低。", "看": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「大家都散了」指聚在一起的人走开，符合「会开完了」的语境。"}, {"text": "聚", "is_correct": false, "explanation": "语义：「聚」指聚拢，与「会开完了」之后人群离开的情景相反。"}, {"text": "解", "is_correct": false, "explanation": "搭配：「解」单用时不能指人群散去，要说「解散」。"}, {"text": "挤", "is_correct": false, "explanation": "语义：「挤」指拥挤推搡，与会议结束后大家离开的情景不合。"}], "explanations": {"散": "正确：「大家都散了」指聚在一起的人走开，符合「会开完了」的语境。", "聚": "语义：「聚」指聚拢，与「会开完了」之后人群离开的情景相反。", "解": "搭配：「解」单用时不能指人群散去，要说「解散」。", "挤": "语义：「挤」指拥挤推搡，与会议结束后大家离开的情景不合。"}, "sentence_index": 0, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下课以后，他一个人很快就散了。", "explanation": "这里应该用〈离开〉。散指聚在一起的一群人各自走开，单独一人离开不说散，要说离开。"}, {"text": "下课铃一响，学生们就散了教室。", "explanation": "这里应该用〈离开〉。散不带处所宾语，不能说「散了教室」；人从某处走开要说离开。"}, {"text": "保安很快就把人群散了。", "explanation": "这里应该用〈驱散〉。散表示聚在一起的人自行走开，不能用「把」加人群宾语表示外力使其散去；外力赶走人群要说驱散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指聚在一起的人走开。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 sàn 声母不同（b 与 s），意思是一半。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}], "explanations": {"散": "正确：散（sàn，第四声），指聚在一起的人走开。", "伞": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。", "饭": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。", "半": "bàn 与 sàn 声母不同（b 与 s），意思是一半。", "善": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。", "战": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「街上的人一下子就散了」指人群迅速走开，符合「雨下大了」的语境。"}, {"text": "集", "is_correct": false, "explanation": "语义：「集」指聚集，与「一下子就……了」描写的人群走开相反。"}, {"text": "游", "is_correct": false, "explanation": "语义：「游」指游泳或游玩，雨天街上的人不会「游」开。"}, {"text": "凑", "is_correct": false, "explanation": "搭配：「凑」通常说「凑在一起」，单说「一下子就凑了」不成句。"}], "explanations": {"散": "正确：「街上的人一下子就散了」指人群迅速走开，符合「雨下大了」的语境。", "集": "语义：「集」指聚集，与「一下子就……了」描写的人群走开相反。", "游": "语义：「游」指游泳或游玩，雨天街上的人不会「游」开。", "凑": "搭配：「凑」通常说「凑在一起」，单说「一下子就凑了」不成句。"}, "sentence_index": 6, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校宣布散社团，同学们都很难过。", "explanation": "这里应该用〈解散〉。散表示聚在一起的人自行走开，不能用「宣布散」让团体解散；使团体解散要说解散。"}, {"text": "吃完饭，大家都散到一起聊天。", "explanation": "这里应该用〈聚〉。散指聚在一起的人走开、分开，不能表示向一处集中；大家往一处集合要说聚。"}, {"text": "放学后，学生们都散家了。", "explanation": "这里应该用〈回〉。散不带处所宾语，不能说「散家」；人回到某处要用回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课以后，学生们散很快。", "corrected_sentence": "下课以后，学生们散得很快。", "error_description": "错误形式是「学生们散很快」，正确应为「学生们散得很快」。「散」后面要用「得」引出程度补语，漏掉「得」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音乐会一结束，听众就散着了。", "corrected_sentence": "音乐会一结束，听众就散了。", "error_description": "错误形式是「听众就散着了」，正确应为「听众就散了」。「散」表示人群走开这一变化，变化完成要用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚", "is_correct": true, "explanation": "正确：「聚」指聚拢，与「散」表示分开、消失的义项相反。"}, {"text": "挂", "is_correct": false, "explanation": "「挂」指悬挂，与「散」没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」指发光或明白，与「散」没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "「站」指站立，与「散」没有反义关系。"}], "correct_answer": "聚", "explanations": {"聚": "正确：「聚」指聚拢，与「散」表示分开、消失的义项相反。", "挂": "「挂」指悬挂，与「散」没有反义关系。", "亮": "「亮」指发光或明白，与「散」没有反义关系。", "站": "「站」指站立，与「散」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚集", "is_correct": true, "explanation": "正确：「聚集」指许多东西集中到一起，与「散」表示分开、消失相反。"}, {"text": "吃", "is_correct": false, "explanation": "「吃」指进食，与「散」没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "「写」指书写文字，与「散」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出歌声，与「散」没有反义关系。"}], "correct_answer": "聚集", "explanations": {"聚集": "正确：「聚集」指许多东西集中到一起，与「散」表示分开、消失相反。", "吃": "「吃」指进食，与「散」没有反义关系。", "写": "「写」指书写文字，与「散」没有反义关系。", "唱": "「唱」指发出歌声，与「散」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由聚集而分开；分离。", "primary_collocate": null, "pronunciation": "sàn", "ipa": "san˥˩", "syllable_count": 1, "sentences": [{"text": "早上的雾慢慢散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上的云都散了，太阳出来了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户开着，房间里的烟很快就散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，花香就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停以后，天上的黑云散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的味道一会儿就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热气慢慢散了，汤不烫了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾还没有散，路上看不清。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖上的水汽散了，能看见对岸了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等雾散了，我们再出发。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "散了", "label": "体标"}, {"form": "散开", "label": "复合"}, {"form": "散去", "label": "复合"}], "register": "中性", "sense_fingerprint": "云、雾、烟、气味等聚在一起的东西分开、消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指由聚到分、分开消失。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 sàn 声母不同（b 与 s），意思是一半。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}], "explanations": {"散": "正确：散（sàn，第四声），指由聚到分、分开消失。", "伞": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。", "饭": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。", "半": "bàn 与 sàn 声母不同（b 与 s），意思是一半。", "善": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「雾慢慢散了」指雾由聚而分、消失，符合句意。"}, {"text": "洒", "is_correct": false, "explanation": "搭配：「洒」多指液体或粉末撒落，不说「雾洒了」。"}, {"text": "飞", "is_correct": false, "explanation": "语义：「飞」强调迅速，与句中「慢慢」矛盾，雾不会「飞」走。"}, {"text": "吹", "is_correct": false, "explanation": "配价：「吹」需要施事（如风），单说「雾慢慢吹了」缺少施事，不成立。"}], "explanations": {"散": "正确：「雾慢慢散了」指雾由聚而分、消失，符合句意。", "洒": "搭配：「洒」多指液体或粉末撒落，不说「雾洒了」。", "飞": "语义：「飞」强调迅速，与句中「慢慢」矛盾，雾不会「飞」走。", "吹": "配价：「吹」需要施事（如风），单说「雾慢慢吹了」缺少施事，不成立。"}, "sentence_index": 0, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在汤里散了一点盐。", "explanation": "这里应该用〈撒〉。撒指把盐、糖之类细碎的东西放开、洒开；散用于云雾、气味等由聚而分，不用于撒调料。"}, {"text": "雨停以后，地上的积水慢慢散了。", "explanation": "这里应该用〈退〉。散用于云雾、气味等由聚而分，积水慢慢消去要说退；「散」不用于积水。"}, {"text": "一阵大风很快就散了这场雾。", "explanation": "这里应该用〈驱散〉。散是不及物用法，云雾自己分开，不能带宾语「这场雾」；要表示外力使其分开，用〈驱散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指由聚到分、分开消失。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 sàn 声母不同（m 与 s），意思是速度低。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}], "explanations": {"散": "正确：散（sàn，第四声），指由聚到分、分开消失。", "三": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。", "赞": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。", "慢": "màn 与 sàn 声母不同（m 与 s），意思是速度低。", "看": "kàn 与 sàn 声母不同（k 与 s），意思是看。", "战": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「热气慢慢散了」指热气由聚而分、消失，与「汤不烫了」相符。"}, {"text": "燃", "is_correct": false, "explanation": "语义：「燃」指燃烧起火，热气不会燃烧，句子不成立。"}, {"text": "扇", "is_correct": false, "explanation": "配价：「扇」需要施事去扇动某物，单说「热气慢慢扇了」缺少施事。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：「浇」的对象是水等液体，不说「浇热气」。"}], "explanations": {"散": "正确：「热气慢慢散了」指热气由聚而分、消失，与「汤不烫了」相符。", "燃": "语义：「燃」指燃烧起火，热气不会燃烧，句子不成立。", "扇": "配价：「扇」需要施事去扇动某物，单说「热气慢慢扇了」缺少施事。", "浇": "搭配：「浇」的对象是水等液体，不说「浇热气」。"}, "sentence_index": 6, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气一暖，地上的雪很快就散了。", "explanation": "这里应该用〈化〉。散指云雾、气味等由聚而分，雪由固态变成水要说化；散不用于雪的融化。"}, {"text": "这杯茶放了一夜，水都散了。", "explanation": "这里应该用〈蒸发〉。水分变成水汽跑掉要说蒸发；散用于云雾、气味等由聚而分，不能用来描述液体蒸发。"}, {"text": "一阵风把烟散了。", "explanation": "这里应该用〈吹散〉。散不带受事宾语直接搭配「把」，不能说「把烟散了」；要表示风施加作用，需用〈吹散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风把花香散了。", "corrected_sentence": "风把花香吹散了。", "error_description": "错误形式是「风把花香散了」，正确应为「风把花香吹散了」。「散」作结果补语，需要「吹」说明使花香分开的动作，缺少「吹」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳出来以后，烟散很快。", "corrected_sentence": "太阳出来以后，烟散得很快。", "error_description": "错误形式是「烟散很快」，正确应为「烟散得很快」。「散」后面要用「得」引出程度补语，漏掉「得」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
