INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "爵士是国王给的一种荣誉的称号。", "primary_collocate": null, "pronunciation": "jué shì", "ipa": "tɕye˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "国王给了他一个爵士的称号。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女王封他为爵士。", "target_word": "爵士", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是一位英国爵士。", "target_word": "爵士", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位爵士住在一座老城堡里。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爵士是一种很高的荣誉。", "target_word": "爵士", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "因为帮助过很多人，他成了爵士。", "target_word": "爵士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到爵士称号的那天很高兴。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老爵士常常给学校捐钱。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王没有给他爵士的称号。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家后来成了爵士，大家都很敬重他。", "target_word": "爵士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位爵士", "label": "量词"}], "register": "中性", "sense_fingerprint": "国王或女王授予的荣誉称号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爵士", "is_correct": true, "explanation": "爵士：国王或女王授予的荣誉称号，正确答案。"}, {"text": "绝食", "is_correct": false, "explanation": "jué shí（第二声）与 jué shì 后字声调不同（shí 为第二声，shì 为第四声），意思是绝食。"}, {"text": "学士", "is_correct": false, "explanation": "xué shì 与 jué shì 前字声母不同（x 与 j），意思是学士。"}, {"text": "局势", "is_correct": false, "explanation": "jú shì 与 jué shì 前字韵母不同（ú 与 üe），意思是局势。"}], "explanations": {"爵士": "爵士：国王或女王授予的荣誉称号，正确答案。", "绝食": "jué shí（第二声）与 jué shì 后字声调不同（shí 为第二声，shì 为第四声），意思是绝食。", "学士": "xué shì 与 jué shì 前字声母不同（x 与 j），意思是学士。", "局势": "jú shì 与 jué shì 前字韵母不同（ú 与 üe），意思是局势。"}, "sentence_index": null, "correct_answer": "爵士"}, "level_3": {"options": [{"text": "爵士", "is_correct": true, "explanation": "爵士：国王授予的荣誉称号，填入“一个___的称号”中合适。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能作为称号。"}, {"text": "奖章", "is_correct": false, "explanation": "语义：“奖章”是实物，不是称号，与“一个……的称号”不合。"}, {"text": "局势", "is_correct": false, "explanation": "搭配：“局势”不能用来修饰“称号”。"}], "explanations": {"爵士": "爵士：国王授予的荣誉称号，填入“一个___的称号”中合适。", "苹果": "语义：“苹果”是水果，不能作为称号。", "奖章": "语义：“奖章”是实物，不是称号，与“一个……的称号”不合。", "局势": "搭配：“局势”不能用来修饰“称号”。"}, "sentence_index": 0, "correct_answer": "爵士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爵士是男爵，世代相传。", "explanation": "这里应该用〈爵位〉。爵位指男爵、伯爵等等级，爵士是个人称号，不是等级，不能说“他的爵士是男爵”。"}, {"text": "这家公司的爵士很有钱。", "explanation": "这里应该用〈老板〉。爵士是国王授予的荣誉称号，不是职务，不能指公司的负责人。"}, {"text": "这座老城堡是一位爵士。", "explanation": "这里应该用〈主人〉。爵士是授予人的称号，城堡不能是爵士，应说城堡的主人是爵士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爵士", "is_correct": true, "explanation": "爵士：国王授予的荣誉称号，填入“他得到___称号的那天很高兴”中合适。"}, {"text": "户口", "is_correct": false, "explanation": "语义：“户口”是登记身份的凭证，不是称号，与语境不合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑物，不能作为称号。"}, {"text": "病毒", "is_correct": false, "explanation": "搭配：“称号”是授予人的，不能授予病毒。"}], "explanations": {"爵士": "爵士：国王授予的荣誉称号，填入“他得到___称号的那天很高兴”中合适。", "户口": "语义：“户口”是登记身份的凭证，不是称号，与语境不合。", "房子": "语义：“房子”是建筑物，不能作为称号。", "病毒": "搭配：“称号”是授予人的，不能授予病毒。"}, "sentence_index": 6, "correct_answer": "爵士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位科学家后来获得了爵士学位，大家都很敬重他。", "explanation": "这里应该用〈博士〉。学位要说“博士学位”，爵士是君主授予的称号，不是学位。"}, {"text": "这只狗后来成了爵士，大家都很敬重它。", "explanation": "这里应该用〈冠军〉。爵士是授予人的称号，动物不能获得，这只狗可以成为冠军。"}, {"text": "这位科学家后来被选为爵士，大家都很敬重他。", "explanation": "这里应该说〈被授予爵士称号〉。爵士由君主授予，不通过选举产生，不能说“被选为爵士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只爵士，住在伦敦。", "corrected_sentence": "他是一位爵士，住在伦敦。", "error_description": "“爵士”指人，量词应用“位”。用“只”是错误的，应改为「他是一位爵士，住在伦敦」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
