INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "欧洲某些国家授予的一种爵位或荣誉称号。", "primary_collocate": null, "pronunciation": "jué shì", "ipa": "tɕye˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "在英国，有的人可以成为爵士。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爵士是英国给的一种荣誉。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位爵士的名字很有名。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "欧洲有的国家会给人爵士的称号。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爷爷是一位爵士。", "target_word": "爵士", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位爵士在伦敦有一座大房子。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英国女王授予他爵士的荣誉，他很感动。", "target_word": "爵士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当上爵士以后，生活没有变。", "target_word": "爵士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的丈夫是英国的一位爵士，常去参加宴会。", "target_word": "爵士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为对国家有贡献，他得到了爵士的荣誉。", "target_word": "爵士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位爵士", "label": "量词"}], "register": "中性", "sense_fingerprint": "欧洲国家授予的爵位（英国的Sir）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation