is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爵士", "is_correct": true, "explanation": "爵士：国王授予的荣誉，填入“英国女王授予他___的荣誉”中合适。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“授予”的对象是称号或奖项，不说授予蛋糕。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以授予的荣誉，与语境不合。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”不能作为荣誉的内容，与语境不合。"}], "explanations": {"爵士": "爵士：国王授予的荣誉，填入“英国女王授予他___的荣誉”中合适。", "蛋糕": "搭配：“授予”的对象是称号或奖项，不说授予蛋糕。", "天气": "语义：“天气”不是可以授予的荣誉，与语境不合。", "家具": "语义：“家具”不能作为荣誉的内容，与语境不合。"}, "sentence_index": 6, "correct_answer": "爵士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为对国家有贡献，得到了爵士的等级。", "explanation": "这里应该用〈爵位〉。爵位指等级，爵士是称号，不能说“爵士的等级”。"}, {"text": "因为学习好，他获得了爵士学位。", "explanation": "这里应该用〈博士〉。学位要说“博士学位”，爵士是称号，不是学位。"}, {"text": "因为对国家有贡献，他每天在家里吃爵士。", "explanation": "这里不能用〈爵士〉。爵士是授予人的称号，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三位老爵士们都很和蔼。", "corrected_sentence": "这三位老爵士都很和蔼。", "error_description": "数词加量词后不能再加“们”。“这三位老爵士们”是错误的，应去掉“们”，改为「这三位老爵士都很和蔼」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只老爵士很和蔼。", "corrected_sentence": "这位老爵士很和蔼。", "error_description": "“爵士”指人，量词应用“位”。用“只”是错误的，应改为「这位老爵士很和蔼」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
