INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引进是把外面的东西带进来。", "primary_collocate": null, "pronunciation": "yǐn jìn", "ipa": "in˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校引进了一台新机器。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场从国外引进了很多好牛。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店引进了新的水果。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园从外地引进了两只熊猫。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一种新花引进到了我们这里。", "target_word": "引进", "complexity_tier": "T3", "furigana": "tā bǎ yì zhǒng xīn huā yǐnjìn dào le wǒmen zhè lǐ.", "sentence_source": "generated"}, {"text": "图书馆引进了一批新书。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里从南方引进了新种子。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民从南方引进了一种新鱼。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想引进几台新电脑。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树是三十年前引进的。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引进了", "label": "完成体"}, {"form": "引进过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把外面的物品、动物、植物带进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引进", "is_correct": true, "explanation": "正确：引进指从外部带入物品，与“新机器”的来源相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不说“唱一台机器”，句子不通。"}, {"text": "回收", "is_correct": false, "explanation": "语义：回收指收集旧物再利用，与“新机器”相矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃指扔掉不要的东西，与“学校引进”的意思相反。"}], "explanations": {"引进": "正确：引进指从外部带入物品，与“新机器”的来源相符。", "唱": "搭配：唱的对象是歌曲，不说“唱一台机器”，句子不通。", "回收": "语义：回收指收集旧物再利用，与“新机器”相矛盾。", "丢弃": "语义：丢弃指扔掉不要的东西，与“学校引进”的意思相反。"}, "sentence_index": 0, "correct_answer": "引进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事引进了大家的讨论。", "explanation": "这里应该用〈引发〉。引进指把外地或外国的人、物带进来，不能表示引起讨论。"}, {"text": "他在演讲中引进了一句名言。", "explanation": "这里应该用〈引用〉。引进指把外面的人、物带进来，引用名言、诗句要说“引用”。"}, {"text": "坏人引进了那个孩子。", "explanation": "这里应该用〈引诱〉。引进用于物品、动植物等从外部带入，不用于诱骗他人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引进", "is_correct": true, "explanation": "正确：引进指从外部带入种子，与“从南方”的来源相符。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁指使东西毁掉，与“引进新种子”的意思相反。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：收割针对成熟的庄稼，不说“收割种子”。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”指把东西吃下去，与“引进”的对象不搭配，句意不通。"}], "explanations": {"引进": "正确：引进指从外部带入种子，与“从南方”的来源相符。", "烧毁": "语义：烧毁指使东西毁掉，与“引进新种子”的意思相反。", "收割": "搭配：收割针对成熟的庄稼，不说“收割种子”。", "吃掉": "搭配：“吃掉”指把东西吃下去，与“引进”的对象不搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "引进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师引进学生认识世界。", "explanation": "这里应该用〈引导〉。引进用于物品、动植物等从外部带入，不用于指引学生。"}, {"text": "这个决定引进了很多麻烦。", "explanation": "这里应该用〈带来〉。引进指把外面的人、物带进来，麻烦是“带来”的，不说“引进麻烦”。"}, {"text": "这个问题引进了大家的关注。", "explanation": "这里应该用〈引起〉。引进指把东西带入，不能表示引起关注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司从国外引进出了一台新机器。", "corrected_sentence": "这家公司从国外引进了一台新机器。", "error_description": "“引进”后不能加补语“出”，应说“引进了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店正在从外地引进了一批新鲜海鲜。", "corrected_sentence": "这家饭店正在从外地引进一批新鲜海鲜。", "error_description": "“正在”表示动作进行中，不能与“了”同用，应说“正在从外地引进一批新鲜海鲜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
