INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外地或外国把人才、技术、物品等带进来。", "primary_collocate": null, "pronunciation": "yǐn jìn", "ipa": "in˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "公司从国外引进了新技术。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市想引进更多的人才。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校引进了几位有经验的老师。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂引进过很多先进的设备。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院从外地引进了一位好医生。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从国外引进了一套好办法。", "target_word": "引进", "complexity_tier": "T3", "furigana": "tā men cóng guówài yǐnjìn le yí tào hǎo bànfǎ.", "sentence_source": "generated"}, {"text": "政府正在引进新的技术。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引进人才要给他们好的条件。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家引进了不少外国的经验。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术是从日本引进的。", "target_word": "引进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引进了", "label": "完成体"}, {"form": "引进过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "从外地或外国引入人才、技术、设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引进", "is_correct": true, "explanation": "正确：引进指从外部带入技术，与“从国外”的来源相符。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除的对象多是建筑、设施，不说“拆除技术”。"}, {"text": "撤销", "is_correct": false, "explanation": "搭配：撤销的对象是决定、命令等，不说“撤销技术”。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：废弃指作废、丢掉，与“从国外引进”的意思相反。"}], "explanations": {"引进": "正确：引进指从外部带入技术，与“从国外”的来源相符。", "拆除": "搭配：拆除的对象多是建筑、设施，不说“拆除技术”。", "撤销": "搭配：撤销的对象是决定、命令等，不说“撤销技术”。", "废弃": "语义：废弃指作废、丢掉，与“从国外引进”的意思相反。"}, "sentence_index": 0, "correct_answer": "引进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题引进了大家的讨论。", "explanation": "这里应该用〈引发〉。引进指把外地或外国的人、技术、物品带进来，不能表示引起讨论。"}, {"text": "医生引进了这种病的病因。", "explanation": "这里应该用〈发现〉。引进指从外部带入人、物，病因是被发现的而不是引进的，不说“引进病因”。"}, {"text": "骗子引进了那个老人。", "explanation": "这里应该用〈引诱〉。引进是把人才、技术、物品带入，不用于诱骗他人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引进", "is_correct": true, "explanation": "正确：引进指从外部带入技术，与“政府正在”推进的语境相符。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：淘汰指把旧的、不合用的事物除去，与“新的技术”相矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：删除的对象多是文件、内容，不说“删除技术”。"}, {"text": "废除", "is_correct": false, "explanation": "搭配：废除的对象多是制度、法律，不说“废除技术”。"}], "explanations": {"引进": "正确：引进指从外部带入技术，与“政府正在”推进的语境相符。", "淘汰": "语义：淘汰指把旧的、不合用的事物除去，与“新的技术”相矛盾。", "删除": "搭配：删除的对象多是文件、内容，不说“删除技术”。", "废除": "搭配：废除的对象多是制度、法律，不说“废除技术”。"}, "sentence_index": 6, "correct_answer": "引进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师引进学生思考问题。", "explanation": "这里应该用〈引导〉。引进指把人才、技术、物品带入，不用于指引学生思考。"}, {"text": "他在文章里引进了一段古诗。", "explanation": "这里应该用〈引用〉。引进指把外面的人、物带进来，引用古诗、名言要说“引用”。"}, {"text": "这件事引进了大家的关注。", "explanation": "这里应该用〈引起〉。引进指把东西带入，不能表示引起关注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家企业从国外引进着一套先进的生产线。", "corrected_sentence": "这家企业从国外引进了一套先进的生产线。", "error_description": "体标错误。“引进一套生产线”是已经完成的动作，要用“了”，不能用表示持续的“着”，应说“从国外引进了一套先进的生产线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在引进了一批先进的技术。", "corrected_sentence": "政府正在引进一批先进的技术。", "error_description": "“正在”表示动作进行中，不能与“了”同用，应说“正在引进一批先进的技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "正确：「拆」指拆除建筑，与「新建」盖起建筑的义项相反。"}, {"text": "写", "is_correct": false, "explanation": "「写」指书写文字，与「新建」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出歌声，与「新建」没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "「吃」指进食，与「新建」没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "正确：「拆」指拆除建筑，与「新建」盖起建筑的义项相反。", "写": "「写」指书写文字，与「新建」没有反义关系。", "唱": "「唱」指发出歌声，与「新建」没有反义关系。", "吃": "「吃」指进食，与「新建」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：「拆除」指拆掉建筑，与「新建」盖起建筑的义项相反。"}, {"text": "吹", "is_correct": false, "explanation": "「吹」指风或口气的流动，与「新建」没有反义关系。"}, {"text": "挂", "is_correct": false, "explanation": "「挂」指悬挂，与「新建」没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」指发光或明白，与「新建」没有反义关系。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：「拆除」指拆掉建筑，与「新建」盖起建筑的义项相反。", "吹": "「吹」指风或口气的流动，与「新建」没有反义关系。", "挂": "「挂」指悬挂，与「新建」没有反义关系。", "亮": "「亮」指发光或明白，与「新建」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "新盖起来。", "primary_collocate": null, "pronunciation": "xīn jiàn", "ipa": "ɕin˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他在老家新建了一座房子。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河上新建了一座大桥。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼是去年新建的。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子东边新建了很多楼房。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家新建的房子又大又亮。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下新建了几间木屋。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷想在院子里新建一间小屋。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的楼房里住着很多年轻人。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里新建了一个凉亭。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座新建的塔有五十米高。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新建了", "label": "体标"}, {"form": "新建过", "label": "体标"}], "register": "中性", "sense_fingerprint": "新盖起房屋、桥梁、塔等实体建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：新建（xīn jiàn），指新盖起来。"}, {"text": "亲见", "is_correct": false, "explanation": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。"}, {"text": "新片", "is_correct": false, "explanation": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。"}, {"text": "新教", "is_correct": false, "explanation": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。"}, {"text": "新店", "is_correct": false, "explanation": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}], "explanations": {"新建": "正确：新建（xīn jiàn），指新盖起来。", "亲见": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。", "新片": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。", "新教": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。", "新店": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}, "sentence_index": null, "correct_answer": "新建"}, "level_3": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：「他在老家新建了一座房子」指新盖起房子，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不说「吃了一座房子」。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是文字，不说「读了一座房子」。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，与盖房子无关，不成立。"}], "explanations": {"新建": "正确：「他在老家新建了一座房子」指新盖起房子，符合句意。", "吃": "搭配：「吃」的对象是食物，不说「吃了一座房子」。", "读": "搭配：「读」的对象是文字，不说「读了一座房子」。", "唱": "语义：「唱」指发出歌声，与盖房子无关，不成立。"}, "sentence_index": 0, "correct_answer": "新建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村子东边新建了很多旧楼房。", "explanation": "这里应该用〈拆〉。新建指新盖起来，不能用于已有的旧楼房；拆掉旧楼房要说拆。"}, {"text": "他们很快就新建了一棵树。", "explanation": "这里应该用〈种〉。新建指盖起房屋、桥梁等建筑，树不是建筑，要说种。"}, {"text": "村里新建了几间老木屋。", "explanation": "这里应该用〈修复〉。新建指新盖起来，老木屋已经存在，不能说新建；修理旧房子要用修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_