INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：新建（xīn jiàn），指新盖起来。"}, {"text": "信件", "is_correct": false, "explanation": "xìnjiàn 与 xīnjiàn 第一个音节声调不同，意思是信件。"}, {"text": "心间", "is_correct": false, "explanation": "xīnjiān 与 xīnjiàn 第二个音节声调不同（jiān 与 jiàn），意思是心里。"}, {"text": "信笺", "is_correct": false, "explanation": "xìnjiān 与 xīnjiàn 两个音节声调都不同，意思是写信用的纸。"}], "explanations": {"新建": "正确：新建（xīn jiàn），指新盖起来。", "信件": "xìnjiàn 与 xīnjiàn 第一个音节声调不同，意思是信件。", "心间": "xīnjiān 与 xīnjiàn 第二个音节声调不同（jiān 与 jiàn），意思是心里。", "信笺": "xìnjiān 与 xīnjiàn 两个音节声调都不同，意思是写信用的纸。"}, "sentence_index": null, "correct_answer": "新建"}, "level_3": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：「爷爷想在院子里新建一间小屋」指打算盖一间小屋，符合句意。"}, {"text": "织", "is_correct": false, "explanation": "语义：「织」指用线编织，不能用于盖小屋。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」的对象是文字，不说「写一间小屋」。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指加热烹饪，不能用于建造房屋。"}], "explanations": {"新建": "正确：「爷爷想在院子里新建一间小屋」指打算盖一间小屋，符合句意。", "织": "语义：「织」指用线编织，不能用于盖小屋。", "写": "搭配：「写」的对象是文字，不说「写一间小屋」。", "煮": "语义：「煮」指加热烹饪，不能用于建造房屋。"}, "sentence_index": 6, "correct_answer": "新建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民新建了一些秧苗。", "explanation": "这里应该用〈育〉。新建指新盖起来的房屋、桥梁等建筑，不能用于秧苗；培育秧苗要说育秧。"}, {"text": "他很快就新建了一把椅子。", "explanation": "这里应该用〈做〉。新建指盖起房屋、桥梁等建筑，椅子不是建筑，要说做。"}, {"text": "作家新建了一本小说。", "explanation": "这里应该用〈写〉。新建指建造实体建筑，小说不是建筑，要说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座桥是前年新建了。", "corrected_sentence": "那座桥是前年新建的。", "error_description": "错误形式是「那座桥是前年新建了」，正确应为「那座桥是前年新建的」。「是……的」句式强调动作的时间，「新建」后要用「的」，不用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷想在后院新建了一间小屋。", "corrected_sentence": "爷爷想在后院新建一间小屋。", "error_description": "错误形式是「爷爷想在后院新建了一间小屋」，正确应为「爷爷想在后院新建一间小屋」。「想」表示打算，后面的动作还未发生，「新建」后不能加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
