INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "新近建造或设立。", "primary_collocate": null, "pronunciation": "xīn jiàn", "ipa": "ɕin˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "市里新建了一所小学。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司今年新建了一个部门。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市要新建三个公园。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校新建了一个图书馆。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里新建了一家医院。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府打算在这里新建一个体育场。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们新建了一个小组，专门做研究。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方新建了一个大市场。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司在南方新建了两家工厂。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路旁边要新建一所学校。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新建了", "label": "体标"}, {"form": "新建过", "label": "体标"}], "register": "中性", "sense_fingerprint": "新近建造或设立学校、医院、部门等机构和设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validat