INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法令、规章等公布后开始生效执行。", "primary_collocate": null, "pronunciation": "shī xíng", "ipa": "ʂɨ˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个新法律从明年一月一日开始施行。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的交通规定下个月施行。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条规定已经施行了三年。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律公布以后，要等到一月才能施行。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办法在全国一起施行。", "target_word": "施行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这项政策什么时候施行？", "target_word": "施行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新的税法已经正式施行了。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个条例明天起施行。", "target_word": "施行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部法令施行后，很多人都觉得方便。", "target_word": "施行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新规定先在北京施行。", "target_word": "施行", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "法令规章公布后生效执行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "施行", "is_correct": true, "explanation": "正确。“开始施行”指法律从某日起开始生效。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉已有的建筑、设施，与法律无关。"}, {"text": "通过", "is_correct": false, "explanation": "搭配：“通过”指表决结果，不说“开始通过”。"}, {"text": "施工", "is_correct": false, "explanation": "语义：“施工”指动工建造，与法律无关。"}], "explanations": {"施行": "正确。“开始施行”指法律从某日起开始生效。", "拆除": "语义：“拆除”指拆掉已有的建筑、设施，与法律无关。", "通过": "搭配：“通过”指表决结果，不说“开始通过”。", "施工": "语义：“施工”指动工建造，与法律无关。"}, "sentence_index": 0, "correct_answer": "施行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我决定从明天起施行早起锻炼。", "explanation": "这里应该用〈实行〉。施行用于法令规章的生效，个人计划要用实行。"}, {"text": "这条路明天起施行，请大家绕道。", "explanation": "这里应该用〈施工〉。施行用于法令规章的生效，修路等工程要用施工。"}, {"text": "双方施行了友好的谈判。", "explanation": "这里应该用〈进行〉。施行用于法令规定，谈判等活动要用进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施行", "is_correct": true, "explanation": "正确。“新的税法已经正式施行了”指税法正式开始生效。"}, {"text": "开办", "is_correct": false, "explanation": "搭配：“开办”多用于学校、公司，不说“开办税法”。"}, {"text": "开工", "is_correct": false, "explanation": "语义：“开工”指开始劳动，不用于法律。"}, {"text": "开设", "is_correct": false, "explanation": "搭配：“开设”多用于课程、店铺，不用于法律。"}], "explanations": {"施行": "正确。“新的税法已经正式施行了”指税法正式开始生效。", "开办": "搭配：“开办”多用于学校、公司，不说“开办税法”。", "开工": "语义：“开工”指开始劳动，不用于法律。", "开设": "搭配：“开设”多用于课程、店铺，不用于法律。"}, "sentence_index": 6, "correct_answer": "施行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校施行了阅读活动，效果很好。", "explanation": "这里应该用〈开展〉。施行用于法令规章的生效，活动要用开展。"}, {"text": "他对孩子施行了很大的压力。", "explanation": "这里应该用〈施加〉。施行用于法令规章，压力要用施加。"}, {"text": "她施行了自己的本领，大家都很佩服。", "explanation": "这里应该用〈施展〉。施行用于法令规章，本领要用施展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项法律下周一起施行过。", "corrected_sentence": "这项法律下周一起施行。", "error_description": "体标错误。“下周一起”指将来，不能用表示经历的“过”，应说“下周一起施行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新规定还没施行了。", "corrected_sentence": "新规定还没施行。", "error_description": "“没”与“了”不能同用。否定已发生的事情时，“没”后不加“了”，应说“还没施行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
