INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成人是已经长大了的人。", "primary_collocate": null, "pronunciation": "chéng rén", "ipa": "ʈʂʰɤŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "成人和小孩都可以进来。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不是给孩子，是给成人看的。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人每天要睡七八个小时，孩子要睡更久。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十八岁了，已经是成人了。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票时，成人要多付钱，小孩便宜。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子慢慢长大，最后变成了成人。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游乐场成人也可以玩，不只是孩子。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人要照顾好自己的孩子。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，成人每天要喝八杯水，孩子少一点。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明才十岁，做事却像成人一样认真。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "成人：已经长大的人，与小孩相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不能与“小孩”并列进来，句意不通。"}, {"text": "成人", "is_correct": true, "explanation": "正确：成人指已长大的人，与“小孩”相对，符合“都可以进来”的语境。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是无生命的物体，与“小孩”并列进门不合常理。"}, {"text": "人士", "is_correct": false, "explanation": "语域：“人士”偏书面、正式，用于这种口语化的说明句不合适。"}], "explanations": {"石头": "语义：石头是无生命的东西，不能与“小孩”并列进来，句意不通。", "成人": "正确：成人指已长大的人，与“小孩”相对，符合“都可以进来”的语境。", "雕像": "语义：雕像是无生命的物体，与“小孩”并列进门不合常理。", "人士": "语域：“人士”偏书面、正式，用于这种口语化的说明句不合适。"}, "sentence_index": 0, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里站着一棵成人。", "explanation": "这里把〈成人〉当作树木来数，用了量词〈棵〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "厨房里放着一台成人。", "explanation": "这里把〈成人〉当作机器来数，用了量词〈台〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "车库里停着一辆成人。", "explanation": "这里把〈成人〉当作车辆来数，用了量词〈辆〉；〈成人〉指人，应用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "儿童", "is_correct": false, "explanation": "语义：“儿童”就是“孩子”，与后句“不只是孩子”自相矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿本身就是孩子，且不适合在游乐场玩，与“不只是孩子”矛盾。"}, {"text": "成人", "is_correct": true, "explanation": "正确：成人指已长大的人，与“不只是孩子”呼应，表示游乐场对成人也开放。"}, {"text": "幼童", "is_correct": false, "explanation": "语域：“幼童”偏书面，且与“不只是孩子”同指儿童，句意前后矛盾。"}], "explanations": {"儿童": "语义：“儿童”就是“孩子”，与后句“不只是孩子”自相矛盾。", "婴儿": "语义：婴儿本身就是孩子，且不适合在游乐场玩，与“不只是孩子”矛盾。", "成人": "正确：成人指已长大的人，与“不只是孩子”呼应，表示游乐场对成人也开放。", "幼童": "语域：“幼童”偏书面，且与“不只是孩子”同指儿童，句意前后矛盾。"}, "sentence_index": 6, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口走来一条成人。", "explanation": "这里把〈成人〉当作细长的东西来数，用了量词〈条〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "车站门口走来一把成人。", "explanation": "这里把〈成人〉当作有柄的器物来数，用了量词〈把〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "教室里坐着一张成人。", "explanation": "这里把〈成人〉当作平面的东西来数，用了量词〈张〉；〈成人〉指人，应用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园门口走来一只成人，牵着一个孩子。", "corrected_sentence": "公园门口走来一位成人，牵着一个孩子。", "error_description": "“成人”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物）。错误在于量词用了“只”，应改为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子终于变成一条成人了。", "corrected_sentence": "这个孩子终于变成一个成人了。", "error_description": "“成人”指人，量词应用“个”或“位”，不能用“条”（“条”多用于细长的东西）。错误在于量词用了“条”，应改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "已经发育成熟、成年的人。", "primary_collocate": null, "pronunciation": "chéng rén", "ipa": "ʈʂʰɤŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "十八岁以后就算成人了。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人的骨头比孩子的硬。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药成人一次吃两片，儿童吃一片。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子很高，看起来像个成人。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人的身体不再长高了，孩子还在长。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法已经像成人一样了。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有成人的病房，也有儿童的病房。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人要对自己的行为负责。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子说话像成人一样。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成人的牙齿一共有三十二颗，小孩的少一些。", "target_word": "成人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "成人：身体发育成熟、已经成年的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孩", "is_correct": false, "explanation": "语义：十八岁以后已不是“小孩”，与句中的“十八岁”相矛盾。"}, {"text": "成人", "is_correct": true, "explanation": "正确：成人指身体发育成熟、已成年的人，与“十八岁”一致。"}, {"text": "老人", "is_correct": false, "explanation": "语义：十八岁不能算“老人”，与句意明显矛盾。"}, {"text": "壮年", "is_correct": false, "explanation": "语域：“壮年”是书面语，且指壮年时期，与“十八岁”的口语说明不合。"}], "explanations": {"小孩": "语义：十八岁以后已不是“小孩”，与句中的“十八岁”相矛盾。", "成人": "正确：成人指身体发育成熟、已成年的人，与“十八岁”一致。", "老人": "语义：十八岁不能算“老人”，与句意明显矛盾。", "壮年": "语域：“壮年”是书面语，且指壮年时期，与“十八岁”的口语说明不合。"}, "sentence_index": 0, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上摆着一本成人。", "explanation": "这里把〈成人〉当作书来数，用了量词〈本〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "山上矗立着一座成人。", "explanation": "这里把〈成人〉当作建筑或山峰来数，用了量词〈座〉；〈成人〉指人，应用〈个〉或〈位〉。"}, {"text": "窗边立着一扇成人。", "explanation": "这里把〈成人〉当作门窗来数，用了量词〈扇〉；〈成人〉指人，应用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是病人，病房不会为厨师专设，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是无生命的东西，不能与“病房”的对象相配，句意荒谬。"}, {"text": "成人", "is_correct": true, "explanation": "正确：成人指成年人，与后句“儿童的病房”形成对照，符合句意。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不是住院的病人，“司机的病房”不成话，也无法与“儿童的病房”构成对照。"}], "explanations": {"厨师": "语义：厨师不是病人，病房不会为厨师专设，句意不通。", "垃圾": "语义：垃圾是无生命的东西，不能与“病房”的对象相配，句意荒谬。", "成人": "正确：成人指成年人，与后句“儿童的病房”形成对照，符合句意。", "司机": "语义：司机不是住院的病人，“司机的病房”不成话，也无法与“儿童的病房”构成对照。"}, "sentence_index": 6, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路边停着一辆成人。", "explanation": "这里把〈成人〉当作车辆来数，用了量词〈辆〉；〈成人〉是人，应用〈个〉或〈位〉。"}, {"text": "桌上放着一块成人。", "explanation": "这里把〈成人〉当作块状物来数，用了量词〈块〉；〈成人〉是人，应用〈个〉或〈位〉。"}, {"text": "屋里站着一根成人。", "explanation": "这里把〈成人〉当作细长的东西来数，用了量词〈根〉；〈成人〉是人，应用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他二十三岁了，身体早已发育成熟，是一只真正的成人。", "corrected_sentence": "他二十三岁了，身体早已发育成熟，是一位真正的成人。", "error_description": "“成人”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物）。错误在于量词用了“只”，应改为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院的病房里住着一头成人。", "corrected_sentence": "这家医院的病房里住着一位成人。", "error_description": "“成人”指人，量词应用“位”或“个”，不能用“头”（“头”多用于牛、猪等动物）。错误在于量词用了“头”，应改为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
