INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里最先到的季节，天气变暖，花开了。", "primary_collocate": null, "pronunciation": "chūn", "ipa": "tʂʰuən˥", "syllable_count": 1, "sentences": [{"text": "春来了，天气暖和了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬去春来，花都开了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春到了，我们就去公园看花。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春来得早，花开得也早。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春到了，树绿了，鸟也唱歌了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春一来，大家就脱了厚衣服。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等春来了，我们去公园看花。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春来得慢，花还没开。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春还没过完，天就一下热了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春走了，花也落了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "春天", "label": "复合"}, {"form": "春季", "label": "复合"}], "register": "中性", "sense_fingerprint": "春：天气变暖、花开的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "春", "is_correct": true, "explanation": "春（chūn，第一声）：一年里最先到的季节，天气变暖，花开了。"}, {"text": "唇", "is_correct": false, "explanation": "chún（第二声）与 chūn（第一声）声调不同，意思是嘴唇。"}, {"text": "村", "is_correct": false, "explanation": "cūn 与 chūn 声母不同（c 与 ch），意思是村庄。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chūn（第一声）声调不同，意思是愚笨。"}], "explanations": {"春": "春（chūn，第一声）：一年里最先到的季节，天气变暖，花开了。", "唇": "chún（第二声）与 chūn（第一声）声调不同，意思是嘴唇。", "村": "cūn 与 chūn 声母不同（c 与 ch），意思是村庄。", "蠢": "chǔn（第三声）与 chūn（第一声）声调不同，意思是愚笨。"}, "sentence_index": null, "correct_answer": "春"}, "level_3": {"options": [{"text": "春", "is_correct": true, "explanation": "“春”指一年里最先到的季节，与“天气暖和了”相符。"}, {"text": "冬", "is_correct": false, "explanation": "语义：冬是最寒冷的季节，“冬来了，天气暖和了”与常识相反。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：雪来时天气多半转冷，“雪来了”不能与“天气暖和了”搭配。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是寒冷的东西，“冰来了，天气暖和了”自相矛盾。"}], "explanations": {"春": "“春”指一年里最先到的季节，与“天气暖和了”相符。", "冬": "语义：冬是最寒冷的季节，“冬来了，天气暖和了”与常识相反。", "雪": "搭配：雪来时天气多半转冷，“雪来了”不能与“天气暖和了”搭配。", "冰": "语义：冰是寒冷的东西，“冰来了，天气暖和了”自相矛盾。"}, "sentence_index": 0, "correct_answer": "春"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场春很暖和。", "explanation": "量词“场”多用于雨、雪、战斗等一次次发生的事，“春”是一段时间的季节，不能用“场”来计量。"}, {"text": "全家人都在春那天回老家团聚。", "explanation": "这里应该用〈春节〉。“春”只指季节，表示过年的节日要说“春节”。"}, {"text": "这一条春又长又暖和。", "explanation": "这里的量词“条”用于细长的东西，“春”作为季节不能用它来计量，应直接说“春”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春", "is_correct": true, "explanation": "“春”指一年里最先到的季节，与“去公园看花”相符。"}, {"text": "霜", "is_correct": false, "explanation": "语义：霜是寒冷时才有的，“等霜来了，我们去公园看花”不合情理。"}, {"text": "雹", "is_correct": false, "explanation": "语义：冰雹是恶劣天气，“等雹来了，我们去公园看花”与常理相悖。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾天看不清花，“等雾来了去看花”与常理相悖。"}], "explanations": {"春": "“春”指一年里最先到的季节，与“去公园看花”相符。", "霜": "语义：霜是寒冷时才有的，“等霜来了，我们去公园看花”不合情理。", "雹": "语义：冰雹是恶劣天气，“等雹来了，我们去公园看花”与常理相悖。", "雾": "语义：雾天看不清花，“等雾来了去看花”与常理相悖。"}, "sentence_index": 6, "correct_answer": "春"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只春很美。", "explanation": "量词“只”多用于动物，“春”是季节，不能用“只”来计量。"}, {"text": "这把春很暖和。", "explanation": "量词“把”用于有柄的东西，“春”是季节，不能用“把”来计量。"}, {"text": "这支春很长。", "explanation": "量词“支”用于杆状的东西，“春”是季节，这里的量词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张春来了，天很暖和。", "corrected_sentence": "春来了，天很暖和。", "error_description": "错误形式：“这张春”；正确形式：“春”（去掉量词）。原因：“张”用于平面的东西，季节不能用量词“张”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的一只春很暖和。", "corrected_sentence": "今年的春很暖和。", "error_description": "错误形式：“一只春”；正确形式：“春”（不加量词）。原因：“只”用于动物，季节不能用量词“只”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
