INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "四季之首，从立春到立夏的季节。", "primary_collocate": null, "pronunciation": "chūn", "ipa": "tʂʰuən˥", "syllable_count": 1, "sentences": [{"text": "一年有春、夏、秋、冬四个季节。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春是四季中的第一个季节。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春过去以后就是夏。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北京，春从三月开始。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四季里，春在夏的前面。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春、夏、秋、冬，你最爱哪个季节？", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春后面是夏，夏后面是秋。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春去夏来，天越来越热了。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年先有春，后有夏。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春和秋都不太冷也不太热。", "target_word": "春", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "春天", "label": "复合"}, {"form": "春季", "label": "复合"}], "register": "中性", "sense_fingerprint": "春：四季中排第一的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "春", "is_correct": true, "explanation": "春（chūn，第一声）：四季之首，从立春到立夏的季节。"}, {"text": "唇", "is_correct": false, "explanation": "chún（第二声）与 chūn（第一声）声调不同，意思是嘴唇。"}, {"text": "村", "is_correct": false, "explanation": "cūn 与 chūn 声母不同（c 与 ch），意思是村庄。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chūn（第一声）声调不同，意思是愚笨。"}], "explanations": {"春": "春（chūn，第一声）：四季之首，从立春到立夏的季节。", "唇": "chún（第二声）与 chūn（第一声）声调不同，意思是嘴唇。", "村": "cūn 与 chūn 声母不同（c 与 ch），意思是村庄。", "蠢": "chǔn（第三声）与 chūn（第一声）声调不同，意思是愚笨。"}, "sentence_index": null, "correct_answer": "春"}, "level_3": {"options": [{"text": "春", "is_correct": true, "explanation": "“春”是四季中的一个，与“一年有……四个季节”相符。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是季节，与“夏、秋、冬”并列不通。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“花”不能与季节名并列，“一年有花”不成说法。"}, {"text": "冬", "is_correct": false, "explanation": "语义：题干已有“冬”，再说一个“冬”就重复了，与四季的排列也不符。"}], "explanations": {"春": "“春”是四季中的一个，与“一年有……四个季节”相符。", "雨": "语义：雨不是季节，与“夏、秋、冬”并列不通。", "花": "搭配：“花”不能与季节名并列，“一年有花”不成说法。", "冬": "语义：题干已有“冬”，再说一个“冬”就重复了，与四季的排列也不符。"}, "sentence_index": 0, "correct_answer": "春"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵春很暖和。", "explanation": "量词“阵”多用于一段时间里的风、雨等，“春”是季节名词，这里不能用“阵”来计量。"}, {"text": "这场春很温和。", "explanation": "量词“场”多用于雨、雪、战斗等一次次发生的事，“春”是季节，不能用“场”来计量。"}, {"text": "这只春很可爱。", "explanation": "量词“只”多用于动物，“春”是季节，不能用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春", "is_correct": true, "explanation": "“春”是四季之首，排在夏的前面，与“春后面是夏”相符。"}, {"text": "秋", "is_correct": false, "explanation": "语义：秋在夏之后，不能排在夏的前面，“秋后面是夏”与顺序相反。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪不是季节，不能排进四季的顺序里。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“冰后面是夏”不成说法，季节的先后顺序不与冰搭配。"}], "explanations": {"春": "“春”是四季之首，排在夏的前面，与“春后面是夏”相符。", "秋": "语义：秋在夏之后，不能排在夏的前面，“秋后面是夏”与顺序相反。", "雪": "语义：雪不是季节，不能排进四季的顺序里。", "冰": "搭配：“冰后面是夏”不成说法，季节的先后顺序不与冰搭配。"}, "sentence_index": 6, "correct_answer": "春"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条春很长。", "explanation": "量词“条”用于细长的东西，“春”是季节，不能用“条”来计量。"}, {"text": "那块春很暖和。", "explanation": "量词“块”用于块状的东西，“春”是季节，不能用“块”来计量。"}, {"text": "这把春很温暖。", "explanation": "量词“把”用于有柄的东西，“春”是季节，不能用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张春很暖和。", "corrected_sentence": "春很暖和。", "error_description": "错误形式：“这张春”；正确形式：“春”（去掉量词）。原因：“张”用于平面的东西，季节不能用量词“张”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年的一朵春很暖和。", "corrected_sentence": "去年的春很暖和。", "error_description": "错误形式：“一朵春”；正确形式：“春”（不加量词）。原因：“朵”用于花朵，季节不能用量词“朵”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
