INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧是人们在台上演出的故事。", "primary_collocate": null, "pronunciation": "xì jù", "ipa": "ɕi˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "昨天晚上我们去剧院看了一部戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部戏剧讲的是一个老人的故事。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的演员正在表演一部有名的戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常常跟爷爷一起去看戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "furigana": "xì jù", "sentence_source": "generated"}, {"text": "这个周末，剧院里有一场戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹很喜欢这部戏剧，每次都看得很认真。", "target_word": "戏剧", "complexity_tier": "T3", "furigana": "xì jù", "sentence_source": "generated"}, {"text": "这部戏剧的舞台不大，可是观众很多。", "target_word": "戏剧", "complexity_tier": "T3", "furigana": "xì jù", "sentence_source": "generated"}, {"text": "老师请我们读一部简单的戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完戏剧以后，大家一起去吃饭。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家剧院每个月都演新的戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戲劇", "label": "繁体"}, {"form": "戏剧家", "label": "复合词"}], "register": "通用", "sense_fingerprint": "在舞台上演出的一部故事作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戏剧", "is_correct": true, "explanation": "“戏剧”指在舞台上演出的作品，可以用“一部”计量，与“看”搭配，符合句意。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，不是可以观看的作品，也不能用“一部”计量。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“看”一般不接“水果”作宾语，“水果”也不用“一部”计量。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然景物，不是剧院里演出的作品，句意不通。"}], "explanations": {"戏剧": "“戏剧”指在舞台上演出的作品，可以用“一部”计量，与“看”搭配，符合句意。", "老师": "语义：“老师”指人，不是可以观看的作品，也不能用“一部”计量。", "水果": "搭配：“看”一般不接“水果”作宾语，“水果”也不用“一部”计量。", "天空": "语义：“天空”是自然景物，不是剧院里演出的作品，句意不通。"}, "sentence_index": 0, "correct_answer": "戏剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候常常跟爷爷一起去戏剧看演出。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指作品或艺术，不指场所，表示地点要说“去剧院看演出”。"}, {"text": "他是一位很有名的戏剧。", "explanation": "〈戏剧〉指作品或艺术，不指人。指人应说〈戏剧家〉，这里用“一位”指人，句意不通。"}, {"text": "我的戏剧今天没来上课。", "explanation": "〈戏剧〉指作品或艺术，不指人，不能“来上课”。指人应说〈同学〉或〈戏剧演员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戏剧", "is_correct": true, "explanation": "“戏剧”是一部可以在舞台上演出的作品，与“这部”搭配，且有舞台，符合句意。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文字作品，没有舞台，与“舞台不大”不相关。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”用“首”计量，不说“这部歌曲”，也不说“歌曲的舞台”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”用“辆”计量，而且“汽车的舞台”不成立。"}], "explanations": {"戏剧": "“戏剧”是一部可以在舞台上演出的作品，与“这部”搭配，且有舞台，符合句意。", "小说": "语义：“小说”是文字作品，没有舞台，与“舞台不大”不相关。", "歌曲": "搭配：“歌曲”用“首”计量，不说“这部歌曲”，也不说“歌曲的舞台”。", "汽车": "搭配：“汽车”用“辆”计量，而且“汽车的舞台”不成立。"}, "sentence_index": 6, "correct_answer": "戏剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个周末我们去戏剧看一场电影。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指演出的作品，不指演出的场所，表示地点不能用〈戏剧〉。"}, {"text": "我在戏剧买了两张票。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指作品，不指买票的场所。"}, {"text": "这部戏剧是一个很老的剧院。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指作品，不指场所，不能与“剧院”画等号；“这个剧院很老”才成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们上周末在剧院看了一本戏剧。", "corrected_sentence": "我们上周末在剧院看了一部戏剧。", "error_description": "错误形式是“一本戏剧”，正确形式是“一部戏剧”。作为演出的作品，“戏剧”应用量词“部”，“本”多用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家剧院每个月都演一部的新戏剧。", "corrected_sentence": "这家剧院每个月都演一部新戏剧。", "error_description": "错误形式是“一部的新戏剧”，正确形式是“一部新戏剧”。量词短语“一部”后面直接接修饰语“新”，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
