INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过演员在舞台上表演故事来反映生活的艺术形式。", "primary_collocate": null, "pronunciation": "xì jù", "ipa": "ɕi˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "戏剧是一种很古老的艺术。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大学里学的是戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏剧能让我们看到不同人的生活。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的戏剧有很长的历史。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在研究戏剧。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏剧和电影都要有演员。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，戏剧可以反映社会生活。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人开始对戏剧感兴趣。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写了很多关于戏剧的书。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想通过戏剧告诉大家生活的道理。", "target_word": "戏剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戲劇", "label": "繁体"}, {"form": "戏剧家", "label": "复合词"}], "register": "通用", "sense_fingerprint": "作为艺术门类的戏剧，通过舞台表演反映生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戏剧", "is_correct": true, "explanation": "“戏剧”是通过演员在舞台上表演故事的艺术，说它是一种很古老的艺术，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是近代发明的交通工具，不能说是很古老的艺术。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：“白菜”是蔬菜，不是艺术形式，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是现代的电子设备，与“很古老的艺术”的描述相矛盾。"}], "explanations": {"戏剧": "“戏剧”是通过演员在舞台上表演故事的艺术，说它是一种很古老的艺术，符合句意。", "汽车": "语义：“汽车”是近代发明的交通工具，不能说是很古老的艺术。", "白菜": "语义：“白菜”是蔬菜，不是艺术形式，句意不通。", "电脑": "语义：“电脑”是现代的电子设备，与“很古老的艺术”的描述相矛盾。"}, "sentence_index": 0, "correct_answer": "戏剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天在戏剧里吃饭，觉得很有意思。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指艺术或作品，不指场所，“在戏剧里吃饭”说不通，应说“在剧院里”。"}, {"text": "这位老人是一位著名的戏剧。", "explanation": "〈戏剧〉指艺术或作品，不指人。指人应说〈戏剧家〉，这里用“一位”指人，句意不通。"}, {"text": "她在大学里学了很戏剧。", "explanation": "〈戏剧〉是名词，不能受〈很〉修饰，应说“她在大学里学了戏剧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戏剧", "is_correct": true, "explanation": "“戏剧”是通过舞台表演反映生活的艺术，句中说它能反映社会生活，符合语境。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不能用来反映社会生活。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，与“反映社会生活”的意义无关。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“反映社会生活”的主语多为文艺作品或新闻报道，不能用“饮料”作主语。"}], "explanations": {"戏剧": "“戏剧”是通过舞台表演反映生活的艺术，句中说它能反映社会生活，符合语境。", "沙发": "语义：“沙发”是家具，不能用来反映社会生活。", "冰箱": "语义：“冰箱”是家用电器，与“反映社会生活”的意义无关。", "饮料": "搭配：“反映社会生活”的主语多为文艺作品或新闻报道，不能用“饮料”作主语。"}, "sentence_index": 6, "correct_answer": "戏剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好在戏剧门口见面。", "explanation": "这里应该用〈剧院〉。〈戏剧〉指艺术或作品，不指场所，表示地点应说〈剧院〉门口。"}, {"text": "这位戏剧写了很多好作品。", "explanation": "〈戏剧〉指艺术，不指人，不能“写作品”。指人应说〈戏剧家〉。"}, {"text": "这个故事很有戏剧，大家都爱听。", "explanation": "这里应该用〈戏剧性〉。“很有”后面要接〈戏剧性〉，〈戏剧〉不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现代戏剧的常常反映社会问题。", "corrected_sentence": "现代戏剧常常反映社会问题。", "error_description": "错误形式是“戏剧的常常”，正确形式是“戏剧常常”。“的”不能加在名词“戏剧”后面再接副词“常常”，应直接说“戏剧常常反映社会问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把戏剧看很得重要。", "corrected_sentence": "他把戏剧看得很重要。", "error_description": "错误形式是“看很得重要”，正确形式是“看得很重要”。“得”应紧接在动词“看”后面，引出程度补语，不能放在“很”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
