INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里一下子明白了，笑一笑。", "primary_collocate": null, "pronunciation": "huì xīn", "ipa": "xuei⁵¹ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "听到这个笑话，大家会心地笑了。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读到那一句，忍不住会心一笑。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子的小把戏，妈妈会心地笑了。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明白了谜底，嘴角露出会心的笑。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到熟悉的歌，我会心地笑了起来。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看着照片，脸上有会心的笑容。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完故事，他对我会心一笑。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下观众看懂了这个笑点，发出会心的笑声。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她突然想通了，不由得会心一笑。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读到这句老话，我会心地笑了笑。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "心里忽然明白而微笑，多说会心一笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会心", "is_correct": true, "explanation": "“会心”表示心里一下子明白，修饰“笑”，与听到笑话后的反应相合。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物体，不能修饰“笑”这一神态。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能修饰“笑”的神态。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：听到笑话后是领会而笑，“愤怒”与这种轻松的心情相反，不合语境。"}], "explanations": {"会心": "“会心”表示心里一下子明白，修饰“笑”，与听到笑话后的反应相合。", "潮湿": "搭配：“潮湿”形容环境或物体，不能修饰“笑”这一神态。", "矮小": "体貌：“矮小”形容身材，不能修饰“笑”的神态。", "愤怒": "语义：听到笑话后是领会而笑，“愤怒”与这种轻松的心情相反，不合语境。"}, "sentence_index": 0, "correct_answer": "会心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被人当众指出错误，会心地咳了一声。", "explanation": "这里应该用〈尴尬〉。会心表示心里会意，不表示窘迫，用于咳嗽这类窘态不合适。"}, {"text": "他看见敌人来了，会心地躲到了树后。", "explanation": "这里应该用〈害怕〉。会心表示会意，不表示恐惧。"}, {"text": "看到朋友得了奖，他会心地咬紧了嘴唇。", "explanation": "这里应该用〈嫉妒〉。会心表示心里会意而微笑、点头，不表示妒忌地咬唇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会心", "is_correct": true, "explanation": "“会心一笑”是固定搭配，“会心”修饰“一笑”，表示领会后微微一笑。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“一笑”这类神态。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃，不能修饰表情动作“一笑”。"}, {"text": "矮胖", "is_correct": false, "explanation": "体貌：“矮胖”形容体型，不能修饰表情动作。"}], "explanations": {"会心": "“会心一笑”是固定搭配，“会心”修饰“一笑”，表示领会后微微一笑。", "清脆": "搭配：“清脆”形容声音，不能修饰“一笑”这类神态。", "锋利": "搭配：“锋利”形容刀刃，不能修饰表情动作“一笑”。", "矮胖": "体貌：“矮胖”形容体型，不能修饰表情动作。"}, "sentence_index": 6, "correct_answer": "会心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到那个消息，会心地咬牙切齿起来。", "explanation": "这里应该用〈愤恨〉。会心表示心里明白后的会意，不表示咬牙切齿的怨恨。"}, {"text": "他听了这句话，会心地大声喊了起来。", "explanation": "这里误把会心当成〈激动〉的意思。会心指心里明白后内敛的会意反应，不表示大声喊叫。"}, {"text": "他输掉比赛，会心地坐在地上。", "explanation": "这里应该用〈沮丧〉。会心表示心领神会，不表示灰心地坐倒在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家听了这段话，都会心的笑了。", "corrected_sentence": "大家听了这段话，都会心地笑了。", "error_description": "错误：“会心的笑了”；正确：“会心地笑了”。会心作状语修饰动词“笑”，按规范应该用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读完信，会心了地笑了笑。", "corrected_sentence": "他读完信，会心地笑了笑。", "error_description": "错误：“会心”后多加了“了”，成了“会心了地”。“会心”作状语修饰动词，不能带“了”，应说“会心地笑了笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
