INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92370, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "领会别人的心意；心领神会。", "primary_collocate": null, "pronunciation": "huì xīn", "ipa": "xuei⁵¹ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "他递来一个眼神，我就会心地点了点头。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友使了个眼色，他会心地停住了话头。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了我一眼，我们会心地对视着。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他朝门口看了一眼，我会心地把门关上了。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听懂了他的暗示，她会心地点了点头。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲没多说，儿子却会心地点点头。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子会心地把茶杯递给了他。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两人会心地交换了一下眼色。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看懂了我的手势，会心地点头回应。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两名队员一个眼神，会心地配合，漂亮地破门得分。", "target_word": "会心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "领会别人的心意，心领神会，常作状语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会心", "is_correct": true, "explanation": "“会心”表示心领神会，修饰“点头”，与“递来一个眼神”的无声示意相合。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“递来一个眼神”是无声示意，“大声”与之矛盾，不符合上下文。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度，不能修饰“点头”这一动作。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“点头”这一动作。"}], "explanations": {"会心": "“会心”表示心领神会，修饰“点头”，与“递来一个眼神”的无声示意相合。", "大声": "语义：“递来一个眼神”是无声示意，“大声”与之矛盾，不符合上下文。", "冰凉": "搭配：“冰凉”形容温度，不能修饰“点头”这一动作。", "雪白": "搭配：“雪白”形容颜色，不能修饰“点头”这一动作。"}, "sentence_index": 0, "correct_answer": "会心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看到比赛结果，会心地哭了。", "explanation": "这里应该用〈伤心〉。会心表示领会别人的心意，不表示悲伤，不能用于哭。"}, {"text": "被人误会，他会心地摔了门。", "explanation": "这里应该用〈生气〉。会心表示领会对方的心意，不表示恼怒，与“摔门”的情绪不符。"}, {"text": "听到这个消息，她会心地张大了嘴。", "explanation": "这里应该用〈惊讶〉。会心表示心领神会，不表示吃惊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会心", "is_correct": true, "explanation": "“会心”表示妻子领会丈夫的心意而主动递杯，修饰“把茶杯递给”的动作。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不能修饰“递杯”这一动作。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃，不能修饰“递杯”这一动作。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”形容颜色或光线，不能修饰“递杯”这一动作。"}], "explanations": {"会心": "“会心”表示妻子领会丈夫的心意而主动递杯，修饰“把茶杯递给”的动作。", "高大": "体貌：“高大”形容体型，不能修饰“递杯”这一动作。", "锋利": "搭配：“锋利”形容刀刃，不能修饰“递杯”这一动作。", "漆黑": "搭配：“漆黑”形容颜色或光线，不能修饰“递杯”这一动作。"}, "sentence_index": 6, "correct_answer": "会心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一拍桌子，会心地怒吼起来。", "explanation": "这里应该用〈愤怒〉。会心指心里明白后的会意反应，不表示怒吼。"}, {"text": "他一听到噪音，就会心地捂住了耳朵。", "explanation": "这里误把会心当成〈本能、条件反射〉的意思。会心指领会对方心意后的会意反应，不表示对噪音的本能躲避。"}, {"text": "得知中奖，他会心地跳了起来。", "explanation": "这里应该用〈惊喜〉。会心指心领神会后内敛的反应，不表示兴奋地跳起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看了我一眼，我就会心的笑了。", "corrected_sentence": "他看了我一眼，我就会心地笑了。", "error_description": "错误：“会心的笑了”；正确：“会心地笑了”。会心作状语修饰动词时要用“地”，用“的”会使它被当作名词修饰语，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈会心了地看了我一眼。", "corrected_sentence": "妈妈会心地看了我一眼。", "error_description": "错误：“会心”后多加了“了”，成了“会心了地”。“会心”作状语修饰动词，不能带动态助词“了”，应说“会心地看了我一眼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
