INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "所隶属的；归属。", "primary_collocate": null, "pronunciation": "suǒ shǔ", "ipa": "swɔ˨˩ ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "请填写你所属的单位。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构所属的部门是教育局。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他所属的公司很有名。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道这所学校所属的系统。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个医生都要写清楚所属医院。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂所属的集团很大。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请说明你所属的部门。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她所属的团队做得很好。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所属单位的电话是多少？", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车队所属的公司换了。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所属部门", "label": "复合"}, {"form": "所属单位", "label": "复合"}, {"form": "所屬", "label": "繁体"}], "register": "书面", "sense_fingerprint": "所属:所隶属的机构或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2be088-64c2-41e3-84d8-6c7e9081f3dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所属", "is_correct": true, "explanation": "所属：隶属于某个单位，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”搭配的是物体表面，单位不能被擦。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”搭配食物，单位不能被煮。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走人或动物，不能用于单位。"}], "explanations": {"所属": "所属：隶属于某个单位，符合句意。", "擦": "搭配：“擦”搭配的是物体表面，单位不能被擦。", "煮": "搭配：“煮”搭配食物，单位不能被煮。", "驱赶": "语义：“驱赶”指赶走人或动物，不能用于单位。"}, "sentence_index": 0, "correct_answer": "所属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不知道这所学校所属的年龄。", "explanation": "这里不能用〈所属〉。所属后面应是学校归属的机构或系统；年龄是属性，不是机构。"}, {"text": "我不知道这所学校所属的脾气。", "explanation": "这里不能用〈所属〉。所属后面应是机构或系统；脾气是性格特点，不是机构。"}, {"text": "我不知道这所学校所属的味道。", "explanation": "这里不能用〈所属〉。所属后面应是机构或系统；味道是事物的属性，不是机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所属", "is_correct": true, "explanation": "所属：隶属于某个部门，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”搭配的是可燃物，部门不能被烧。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象不能是部门。"}, {"text": "挑衅", "is_correct": false, "explanation": "语义：“挑衅”指故意激怒对方，不能用于部门。"}], "explanations": {"所属": "所属：隶属于某个部门，符合句意。", "烧": "搭配：“烧”搭配的是可燃物，部门不能被烧。", "咬": "搭配：“咬”的对象不能是部门。", "挑衅": "语义：“挑衅”指故意激怒对方，不能用于部门。"}, "sentence_index": 6, "correct_answer": "所属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个车队所属的重量很大。", "explanation": "这里不能用〈所属〉。所属后面应是车队归属的公司或单位；重量是属性，应说“车队的重量”。"}, {"text": "这个车队所属的速度很快。", "explanation": "这里不能用〈所属〉。所属后面应是公司或单位；速度是属性，应说“车队的速度”。"}, {"text": "这个车队所属的长度很长。", "explanation": "这里不能用〈所属〉。所属后面应是公司或单位；长度是属性，应说“车队的长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位记者所属了的报社很有名。", "corrected_sentence": "这位记者所属的报社很有名。", "error_description": "错在“了”的位置。“所属”后接“了”再带“的”做定语，很不自然；应说“所属的报社”，不说“所属了的报社”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她所属了的团队得了第一名。", "corrected_sentence": "她所属的团队得了第一名。", "error_description": "多了“了”。“所属”做定语时直接加“的”，不能带“了”；应说“所属的团队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每逢；每次遇到某种时候。", "primary_collocate": null, "pronunciation": "měi dāng", "ipa": "meɪ˨˩ tɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "每当遇到问题，他都问老师。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当我累，妈妈就给我做汤。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当有人说话，他都很认真听。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当考试，我就很紧张。", "target_word": "每当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每当生病，我都想回家。", "target_word": "每当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每当想放弃，我就看看这张照片。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当朋友有困难，他都会帮忙。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当下大雪，路上的车就很少。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每当我难过时，音乐总能让我好起来。", "target_word": "每当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每当他紧张，手就一直发抖。", "target_word": "每当", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每逢、每次遇到某种情况，后面接情况并引出固定的反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每当", "is_correct": true, "explanation": "正确答案：每当，表示每次遇到某种情况。"}, {"text": "每档", "is_correct": false, "explanation": "dàng（第四声）与 dāng（第一声）声调不同，意思是每一档次，不是每当。"}, {"text": "每堂", "is_correct": false, "explanation": "táng 与 dāng 声母不同（t 与 d），意思是每一节课，不是每当。"}, {"text": "每单", "is_correct": false, "explanation": "dān 与 dāng 韵尾不同（n 与 ng），意思是每一份订单，不是每当。"}], "explanations": {"每当": "正确答案：每当，表示每次遇到某种情况。", "每档": "dàng（第四声）与 dāng（第一声）声调不同，意思是每一档次，不是每当。", "每堂": "táng 与 dāng 声母不同（t 与 d），意思是每一节课，不是每当。", "每单": "dān 与 dāng 韵尾不同（n 与 ng），意思是每一份订单，不是每当。"}, "sentence_index": null, "correct_answer": "每当"}, "level_3": {"options": [{"text": "每当", "is_correct": true, "explanation": "正确：“每当”表示每次遇到某种情况，引出“他都问老师”。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求由人主动去做某事，“遇到问题”是遭遇，不能说“亲自遇到”。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，遇到问题不是有意的，句意不合。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是书面语，与口语化的“他都问老师”不协调。"}], "explanations": {"每当": "正确：“每当”表示每次遇到某种情况，引出“他都问老师”。", "亲自": "搭配：“亲自”要求由人主动去做某事，“遇到问题”是遭遇，不能说“亲自遇到”。", "故意": "语义：“故意”表示有意为之，遇到问题不是有意的，句意不合。", "遂": "语域：“遂”是书面语，与口语化的“他都问老师”不协调。"}, "sentence_index": 0, "correct_answer": "每当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每当上个星期的那场考试，我都很紧张。", "explanation": "这里应该用〈在……的时候〉。“每当”表示每次遇到某种时候、要反复出现；“上个星期的那场考试”只有一次，应表示一次性时点。"}, {"text": "每当我十岁生日那天，我就很开心。", "explanation": "这里混淆了〈每当〉的“每次”义与“一次时点”义：“十岁生日”只有一次，应去掉“每当”，说“我十岁生日那天……”。"}, {"text": "每当他第一次出国的时候，他就很紧张。", "explanation": "这里混淆了〈每当〉的“每次”义与“一次时点”义：“第一次出国”只发生一次，应去掉“每当”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每当", "is_correct": true, "explanation": "正确：“每当”表示每次遇到某种情况，引出“他都会帮忙”。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”指暗中做事、不让人知道，与“朋友有困难”后公开的帮忙不合。"}, {"text": "暗中", "is_correct": false, "explanation": "语法：“暗中”是副词，后面要接动作，不能放在“朋友有困难”这个小句前面引出情况。"}, {"text": "亲手", "is_correct": false, "explanation": "配价：“亲手”要求动作者用手完成具体的事，“有困难”是状态，不能亲手去做。"}], "explanations": {"每当": "正确：“每当”表示每次遇到某种情况，引出“他都会帮忙”。", "偷偷": "语义：“偷偷”指暗中做事、不让人知道，与“朋友有困难”后公开的帮忙不合。", "暗中": "语法：“暗中”是副词，后面要接动作，不能放在“朋友有困难”这个小句前面引出情况。", "亲手": "配价：“亲手”要求动作者用手完成具体的事，“有困难”是状态，不能亲手去做。"}, "sentence_index": 6, "correct_answer": "每当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每当那场比赛，我就很兴奋。", "explanation": "这里应该用〈在……的时候〉。“每当”表示每次遇到某种时候、要反复出现；“那场比赛”只发生一次，不能用“每当”引出。"}, {"text": "每当明年春天，我就去旅行。", "explanation": "这里应该用〈届时〉。“每当”表示已经反复出现的时候，“明年春天”只是将来的一次，不能用“每当”。"}, {"text": "每当他提的建议，大家都同意。", "explanation": "这里应该用〈凡是〉。“每当”引出的是时间，表示每次遇到某种时候；指建议、事物时要用“凡是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每当考场，我就很紧张。", "corrected_sentence": "每当进入考场，我就很紧张。", "error_description": "“每当”后面要接表示情境或行为的词语（如“进入考场”），不能直接接地点“考场”；应说“每当进入考场，我就很紧张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每当困难，我就去休息。", "corrected_sentence": "每当遇到困难，我就去休息。", "error_description": "“每当”后面要接完整的小句（如“遇到困难”），此处缺少谓语动词，“每当困难”不成句；应说“每当遇到困难，我就去休息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打的是招手叫一辆出租车坐。", "primary_collocate": null, "pronunciation": "dǎ dī", "ipa": "ta˨˩ ti˥", "syllable_count": 2, "sentences": [{"text": "路边没有车，我只好招手打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路口打的，等了十分钟。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我在门口打的，可是没有空车。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路口挥手打的，可是车都不停。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天很晚了，她一个人在路边打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起手，想在路边打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里车多，很容易打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在街上打的，司机停了下来。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班时间在这里很难打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别站在桥上打的，那里不能停车。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打个的", "label": "离合"}], "register": "口语", "sense_fingerprint": "在路边招手拦出租车的动作，强调叫车、拦车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开车", "is_correct": false, "explanation": "语义：路边没有车，就谈不上开车，句意矛盾。"}, {"text": "打的", "is_correct": true, "explanation": "打的：招手叫出租车，与“招手”“路边”相合，也与“没有车”形成对比。"}, {"text": "洗车", "is_correct": false, "explanation": "搭配：“招手”后不能接“洗车”，句意不通。"}, {"text": "修车", "is_correct": false, "explanation": "语义：没有车可修，“修车”与“没有车”矛盾。"}], "explanations": {"开车": "语义：路边没有车，就谈不上开车，句意矛盾。", "打的": "打的：招手叫出租车，与“招手”“路边”相合，也与“没有车”形成对比。", "洗车": "搭配：“招手”后不能接“洗车”，句意不通。", "修车": "语义：没有车可修，“修车”与“没有车”矛盾。"}, "sentence_index": 0, "correct_answer": "打的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电脑上打个的，很快写完了报告。", "explanation": "这里“打的”被用成了〈打字〉的意思；“打的”只指招手叫出租车，在电脑上写东西要说“打字”。"}, {"text": "我在路边打的，然后自己开车去公司。", "explanation": "这里“打的”被用成了〈自驾〉的意思；“打的”只指乘坐出租车，由司机驾驶，不能和“自己开车”同时出现。"}, {"text": "我在飞机上打的，想去机场。", "explanation": "这里“打的”被用成了〈坐飞机〉的意思；“打的”指在路上招手叫出租车，飞机上不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车", "is_correct": false, "explanation": "搭配：车多时“很容易停车”自相矛盾，车多反而难停。"}, {"text": "打的", "is_correct": true, "explanation": "打的：招手叫出租车，车多时容易叫到车，句意通顺。"}, {"text": "缺车", "is_correct": false, "explanation": "语义：“车多”与“缺车”意思相反，句意矛盾。"}, {"text": "打工", "is_correct": false, "explanation": "语义：“打工”与车多无关，句意不通。"}], "explanations": {"停车": "搭配：车多时“很容易停车”自相矛盾，车多反而难停。", "打的": "打的：招手叫出租车，车多时容易叫到车，句意通顺。", "缺车": "语义：“车多”与“缺车”意思相反，句意矛盾。", "打工": "语义：“打工”与车多无关，句意不通。"}, "sentence_index": 6, "correct_answer": "打的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈拿起毛衣针打个的，给孩子织围巾。", "explanation": "这里“打的”被用成了〈打毛衣〉的意思；“打的”只指招手叫出租车，织东西要说“打毛衣”。"}, {"text": "他和朋友在球场上打个的，赢了比赛。", "explanation": "这里“打的”被用成了〈打球〉的意思；“打的”只指招手叫出租车，不能用来指打球。"}, {"text": "他骑着自行车打的，去了公司。", "explanation": "这里“打的”被用成了〈骑车出行〉的意思；“打的”只指招手叫出租车，与骑自行车无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在路边打的了去车站。", "corrected_sentence": "我在路边打的去车站。", "error_description": "“打的”是完整的动词，后面不能直接加“了”。错误句在“的”后多加了“了”，写成“打的了去车站”；应去掉“了”，说“我在路边打的去车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨太大了，我在门口打的个去医院。", "corrected_sentence": "雨太大了，我在门口打个的去医院。", "error_description": "离合词“打个的”中，“个”要放在“打”和“的”之间。错误句把“个”放到“的”后面，写成“打的个”，语序错误，应改为“打个的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
