INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "乘坐出租车。", "primary_collocate": null, "pronunciation": "dǎ dī", "ipa": "ta˨˩ ti˥", "syllable_count": 2, "sentences": [{"text": "我们打的去火车站吧，比较快。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天打的上班，花很多钱。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，我不想坐公交车，想打的回家。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在北京打的，觉得很方便。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打的比坐地铁贵，但是很舒服。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打的去了医院。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打的过去要多长时间？", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李太多，我们只能打的。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了酒，不能开车，只好打的回家。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不迟到，我们决定打的去公司。", "target_word": "打的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打个的", "label": "离合"}], "register": "口语", "sense_fingerprint": "乘坐出租车去某地，强调出行方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：散步速度慢，与“比较快”矛盾。"}, {"text": "打的", "is_correct": true, "explanation": "打的：乘出租车去，与“比较快”相合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能用来表示去火车站的交通方式。"}, {"text": "爬山", "is_correct": false, "explanation": "语义：爬山不是去火车站的方式，句意不通。"}], "explanations": {"散步": "语义：散步速度慢，与“比较快”矛盾。", "打的": "打的：乘出租车去，与“比较快”相合。", "游泳": "搭配：“游泳”不能用来表示去火车站的交通方式。", "爬山": "语义：爬山不是去火车站的方式，句意不通。"}, "sentence_index": 0, "correct_answer": "打的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我第一次在北京打的，走路去了颐和园。", "explanation": "这里“打的”被用成了〈步行〉的意思；“打的”表示乘坐出租车，不能用来指走路去。"}, {"text": "我第一次在北京打的，坐的是地铁。", "explanation": "这里“打的”被用成了〈乘公共交通〉的意思；“打的”只指乘坐出租车，坐地铁不能说“打的”。"}, {"text": "我第一次在北京打的，开着自己的车去天安门。", "explanation": "这里“打的”被用成了〈自驾〉的意思；“打的”是乘坐出租车，由司机开车，不能说自己开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能用来表示去某处的方式，句意不通。"}, {"text": "打的", "is_correct": true, "explanation": "打的：乘出租车去某处，与“过去要多长时间”相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌过去”不成搭配，不能表示移动的方式。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与“过去”的路程无关，句意不通。"}], "explanations": {"睡觉": "语义：睡觉不能用来表示去某处的方式，句意不通。", "打的": "打的：乘出租车去某处，与“过去要多长时间”相合。", "唱歌": "搭配：“唱歌过去”不成搭配，不能表示移动的方式。", "吃饭": "语义：吃饭与“过去”的路程无关，句意不通。"}, "sentence_index": 6, "correct_answer": "打的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们决定给公司打的，问他们什么时候开会。", "explanation": "“打的”指乘出租车，不指打电话；给公司打电话要说“打电话”。"}, {"text": "为了不迟到，我们决定打的坐船去公司。", "explanation": "这里“打的”被用成了〈乘船〉的意思；“打的”只指乘坐出租车，不能用于乘船。"}, {"text": "我们在球场上打的，赢了比赛。", "explanation": "这里“打的”被用成了〈打球〉的意思；“打的”只指乘坐出租车，不能用来指打球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们打的了去机场吧，时间来不及了。", "corrected_sentence": "我们打的去机场吧，时间来不及了。", "error_description": "错误句在“打的”和“去机场”之间加了“了”，写成“打的了去机场吧”。这句是用“吧”提出建议，说的是还没发生的事，不能在连动结构中间加“了”。应去掉“了”，说“打的去机场吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈发烧了，我们打打的去医院。", "corrected_sentence": "妈妈发烧了，我们打的去医院。", "error_description": "“打的”不能重叠，应说“打的去医院”。错误句在前面多加了一个“打”，把动词重叠成“打打的”，不符合这个词的用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
