INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火车停下来，人上车下车的地方。", "primary_collocate": null, "pronunciation": "huǒ chē zhàn", "ipa": "xuɔ˨˩˦ ʈʂʰɤ˥ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "火车站在那边。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在火车站见面。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车站离我家很近。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去火车站接朋友。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车站里有很多人。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从这里走到火车站要二十分钟。", "target_word": "火车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天在火车站买了一张票。", "target_word": "火车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到火车站的时候，火车已经开走了。", "target_word": "火车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车站旁边有一家很大的饭店，我们去那儿吃饭吧。", "target_word": "火车站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说新火车站修好了，坐车去北京只要四个小时。", "target_word": "火车站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "火車站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车停靠、人们上下车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火车站", "is_correct": true, "explanation": "正确答案。“火车站在那边”指火车站位于那个方向。"}, {"text": "星期一", "is_correct": false, "explanation": "配价：“在那边”要求处所名词作主语，“星期一”不能表示处所。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能处于某个地方。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指日子，不能作为“在那边”的处所。"}], "explanations": {"火车站": "正确答案。“火车站在那边”指火车站位于那个方向。", "星期一": "配价：“在那边”要求处所名词作主语，“星期一”不能表示处所。", "感冒": "语义：“感冒”是疾病，不能处于某个地方。", "生日": "语义：“生日”指日子，不能作为“在那边”的处所。"}, "sentence_index": 0, "correct_answer": "火车站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐火车站去北京。", "explanation": "这里把〈火车站〉当成了〈交通工具〉来用。火车站是地点，不是可以乘坐的车，应说“去火车站”。"}, {"text": "我买了一张火车站。", "explanation": "这里应该用〈火车票〉。“买”的对象是票，火车站是地点，不能买。"}, {"text": "这只火车站很大。", "explanation": "这里应该用〈座〉。“只”用于动物或单件小物，车站这类大型建筑要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车站", "is_correct": true, "explanation": "正确答案。在火车站买票是合理的。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不卖票，“买票”的地点应是售票处或车站。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房不是买票的地方，与“买了一张票”的语境不合。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“买票”的场所应为售票处，“菜市场”是买菜的地方。"}], "explanations": {"火车站": "正确答案。在火车站买票是合理的。", "厨房": "语义：厨房不卖票，“买票”的地点应是售票处或车站。", "书房": "语义：书房不是买票的地方，与“买了一张票”的语境不合。", "菜市场": "搭配：“买票”的场所应为售票处，“菜市场”是买菜的地方。"}, "sentence_index": 6, "correct_answer": "火车站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都走到火车站上，等着进站的火车。", "explanation": "这里应该用〈站台〉。火车站是整个车站建筑，站台是乘客候车上车的平台，“走到火车站上”不这么说。"}, {"text": "火车站已经开走了。", "explanation": "这里应该用〈列车〉。火车站是地点，不能开走，开走的是列车。"}, {"text": "那颗火车站很新。", "explanation": "这里应该用〈座〉。“颗”多用于圆粒状的小东西，车站是大型建筑，要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天在火车站了等你。", "corrected_sentence": "我明天在火车站等你。", "error_description": "体标错误：“了”不能用在“在火车站”和“等”之间，而且“明天”的事还没发生，不用“了”。错误形式是“在火车站了等你”，正确形式是“在火车站等你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从学校到走火车站要十分钟。", "corrected_sentence": "从学校走到火车站要十分钟。", "error_description": "补语位置错误：“走到”是动词加结果补语，应说“走到火车站”，不能说“到走火车站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
