INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火车停靠、乘客上下车的场所。", "primary_collocate": null, "pronunciation": "huǒ chē zhàn", "ipa": "xuɔ˨˩˦ ʈʂʰɤ˥ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "火车站不远。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在火车站等我。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个火车站很大。", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车站有地铁吗？", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问，去火车站怎么走？", "target_word": "火车站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐出租车去火车站，路上花了半个小时。", "target_word": "火车站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站门口有很多人在等车。", "target_word": "火车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，我们快点儿走进火车站吧。", "target_word": "火车站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把行李放在火车站的椅子上，去买水了。", "target_word": "火车站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节的时候，火车站里到处都是回家的人。", "target_word": "火车站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "火車站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车停靠、乘客上下车的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火车站", "is_correct": true, "explanation": "正确答案。“火车站不远”描述火车站离这里的距离。"}, {"text": "星期六", "is_correct": false, "explanation": "配价：“不远”描述距离，需要地点或处所作主语，“星期六”不能这样用。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能说“不远”。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”不是地点，不能说离某处“不远”。"}], "explanations": {"火车站": "正确答案。“火车站不远”描述火车站离这里的距离。", "星期六": "配价：“不远”描述距离，需要地点或处所作主语，“星期六”不能这样用。", "感冒": "语义：“感冒”是疾病，不能说“不远”。", "笑话": "语义：“笑话”不是地点，不能说离某处“不远”。"}, "sentence_index": 0, "correct_answer": "火车站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐火车站去北京。", "explanation": "这里把〈火车站〉当成了〈交通工具〉来用。火车站是地点，不是可以乘坐的车，应说“去火车站”。"}, {"text": "我买了一张火车站。", "explanation": "这里应该用〈火车票〉。“买”的对象是票，火车站是地点，不能买。"}, {"text": "这张火车站很大。", "explanation": "这里应该用〈座〉。“张”用于平面的东西，车站是大型建筑，要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车站", "is_correct": true, "explanation": "正确答案。火车站门口是乘客等车的地方。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能有“门口”，也不是等车的地方。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“门口”需要有门的处所名词作主语，“空气”没有门口。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能有门口，也不是等车的地方。"}], "explanations": {"火车站": "正确答案。火车站门口是乘客等车的地方。", "电脑": "语义：电脑不能有“门口”，也不是等车的地方。", "空气": "配价：“门口”需要有门的处所名词作主语，“空气”没有门口。", "春天": "语义：“春天”是季节，不能有门口，也不是等车的地方。"}, "sentence_index": 6, "correct_answer": "火车站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都走到火车站上，等着上车。", "explanation": "这里应该用〈站台〉。火车站是整个车站建筑，站台是上车的平台，“走到火车站上”不这么说。"}, {"text": "火车站已经开走了。", "explanation": "这里应该用〈列车〉。火车站是地点，不能开走，开走的是列车。"}, {"text": "这根火车站很新。", "explanation": "这里应该用〈座〉。“根”多用于细长的东西，车站是大型建筑，要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近有一只火车站。", "corrected_sentence": "我家附近有一座火车站。", "error_description": "量词错误：火车站是大型建筑，应用“座”，“只”用于动物或单件小物。错误形式是“一只火车站”，正确形式是“一座火车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从家里走火车站要十五分钟。", "corrected_sentence": "从家里走到火车站要十五分钟。", "error_description": "补语缺失：“走到”是动词加结果补语，表示到达，应说“走到火车站”，不能说“走火车站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。"}, {"text": "学习", "is_correct": false, "explanation": "无反义关系：学习指获得知识或技能，与损害不构成相对关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：讨论指就问题交换意见，与“使事物受伤变坏”无相对关系。"}, {"text": "购买", "is_correct": false, "explanation": "无反义关系：购买指花钱取得物品，与损害无相对关系。"}], "correct_answer": "保护", "explanations": {"保护": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。", "学习": "无反义关系：学习指获得知识或技能，与损害不构成相对关系。", "讨论": "无反义关系：讨论指就问题交换意见，与“使事物受伤变坏”无相对关系。", "购买": "无反义关系：购买指花钱取得物品，与损害无相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。"}, {"text": "收集", "is_correct": false, "explanation": "无反义关系：收集指把分散的东西聚到一起，与损害无相对关系。"}, {"text": "设计", "is_correct": false, "explanation": "无反义关系：设计指规划图样或方案，与损害无相对关系。"}, {"text": "运输", "is_correct": false, "explanation": "无反义关系：运输指把物品从一处运到另一处，与损害无相对关系。"}], "correct_answer": "保护", "explanations": {"保护": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。", "收集": "无反义关系：收集指把分散的东西聚到一起，与损害无相对关系。", "设计": "无反义关系：设计指规划图样或方案，与损害无相对关系。", "运输": "无反义关系：运输指把物品从一处运到另一处，与损害无相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "损害是让东西变坏，受到伤害。", "primary_collocate": null, "pronunciation": "sǔn hài", "ipa": "swən˨˩˦ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "熬夜太多会损害你的健康。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大声听音乐会损害耳朵。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药会损害肝脏，所以不能多吃。", "target_word": "损害", "complexity_tier": "T3", "furigana": "zhè zhǒng yào huì sǔn hài gān zàng, suǒ yǐ bù néng duō chī.", "sentence_source": "generated"}, {"text": "长时间看手机会损害眼睛。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水损害了这幅旧画。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽烟不但损害自己，也损害别人的身体。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳晒得太久，会损害皮肤。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃得太咸，已经损害了身体。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的冷风损害过这些花。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不好的习惯会慢慢损害身体。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "损害了", "label": "完成体"}, {"form": "损害过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "让身体或物品变坏、受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "损害", "is_correct": true, "explanation": "正确：损害指使身体变坏、受伤，与“熬夜太多”对健康的影响相符。"}, {"text": "检查", "is_correct": false, "explanation": "语义：检查指查看、检验，熬夜不能让健康被“检查”，句意不通。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：享受的对象是生活、待遇等，不说“享受健康”。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：锻炼的对象是身体、能力，不说“锻炼健康”，且与熬夜的后果相反。"}], "explanations": {"损害": "正确：损害指使身体变坏、受伤，与“熬夜太多”对健康的影响相符。", "检查": "语义：检查指查看、检验，熬夜不能让健康被“检查”，句意不通。", "享受": "搭配：享受的对象是生活、待遇等，不说“享受健康”。", "锻炼": "搭配：锻炼的对象是身体、能力，不说“锻炼健康”，且与熬夜的后果相反。"}, "sentence_index": 0, "correct_answer": "损害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早睡早起损害了健康。", "explanation": "这里应该用〈增进〉。损害指使健康变坏，早睡早起应说“增进健康”。"}, {"text": "这次事故让公司损害了三万元。", "explanation": "这里应该用〈损失〉。损失指财物、钱款等丢失，损害用于使事物变坏或受伤，不说“损害了三万元”。"}, {"text": "这次演讲损害了大家的掌声。", "explanation": "这里应该用〈赢得〉。损害指使事物变坏，掌声应说“赢得”，不说“损害掌声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "损害", "is_correct": true, "explanation": "正确：损害指使皮肤受伤、变坏，与“晒得太久”的后果一致。"}, {"text": "滋润", "is_correct": false, "explanation": "语义：滋润指使皮肤湿润柔软，与“晒得太久”造成的伤害相反。"}, {"text": "保养", "is_correct": false, "explanation": "语义：保养指精心养护使其更好，与“晒得太久”的后果相矛盾。"}, {"text": "增进", "is_correct": false, "explanation": "搭配：增进多用于感情、了解、健康等，不说“增进皮肤”。"}], "explanations": {"损害": "正确：损害指使皮肤受伤、变坏，与“晒得太久”的后果一致。", "滋润": "语义：滋润指使皮肤湿润柔软，与“晒得太久”造成的伤害相反。", "保养": "语义：保养指精心养护使其更好，与“晒得太久”的后果相矛盾。", "增进": "搭配：增进多用于感情、了解、健康等，不说“增进皮肤”。"}, "sentence_index": 6, "correct_answer": "损害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药损害了他的病。", "explanation": "这里应该用〈治愈〉。损害是使事物变坏，不能用于消除病痛，应说“治愈了他的病”。"}, {"text": "这次会议损害了我们的时间。", "explanation": "这里应该用〈浪费〉。损害是使事物变坏，时间白白耗去要说“浪费”，不说“损害时间”。"}, {"text": "他的一句话损害了全班的笑声。", "explanation": "这里应该用〈引起〉。损害指使事物变坏，笑声应说“引起”，不说“损害笑声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期吸烟会对损害肺部。", "corrected_sentence": "长期吸烟会损害肺部。", "error_description": "错误：“损害”是及物动词，前面不能加介词“对”，应说“会损害肺部”，不说“会对损害肺部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长期熬夜会损害了记忆力。", "corrected_sentence": "长期熬夜会损害记忆力。", "error_description": "“会”表示将来或可能，后面的动词不能再带“了”，应说“会损害记忆力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。"}, {"text": "修建", "is_correct": false, "explanation": "无反义关系：修建指建造或修整房屋、道路等，与损害无相对关系。"}, {"text": "阅读", "is_correct": false, "explanation": "无反义关系：阅读指看文字内容，与损害无相对关系。"}, {"text": "训练", "is_correct": false, "explanation": "无反义关系：训练指有计划地教导或练习，与损害无相对关系。"}], "correct_answer": "保护", "explanations": {"保护": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。", "修建": "无反义关系：修建指建造或修整房屋、道路等，与损害无相对关系。", "阅读": "无反义关系：阅读指看文字内容，与损害无相对关系。", "训练": "无反义关系：训练指有计划地教导或练习，与损害无相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。"}, {"text": "观察", "is_correct": false, "explanation": "无反义关系：观察指仔细察看，与损害无相对关系。"}, {"text": "浇灌", "is_correct": false, "explanation": "无反义关系：浇灌指给植物供水，与损害无相对关系。"}, {"text": "批评", "is_correct": false, "explanation": "无反义关系：批评指指出缺点或错误，与损害无相对关系。"}], "correct_answer": "保护", "explanations": {"保护": "反义：损害指使受伤变坏，保护指使免受伤害，二者意思相对。", "观察": "无反义关系：观察指仔细察看，与损害无相对关系。", "浇灌": "无反义关系：浇灌指给植物供水，与损害无相对关系。", "批评": "无反义关系：批评指指出缺点或错误，与损害无相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物遭受破坏或伤害。", "primary_collocate": null, "pronunciation": "sǔn hài", "ipa": "swən˨˩˦ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "说假话会损害你的名声。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做会损害公司的利益。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架损害了他们的感情。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的废水损害了河流的生态。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为损害了学校的形象。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾会损害城市的环境。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事没有损害我们的友谊。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗人的广告损害过很多顾客的利益。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能为了钱而损害别人的权利。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次错误不会损害他多年的好名声。", "target_word": "损害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "损害了", "label": "完成体"}, {"form": "损害过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使名声、利益、环境等遭到破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "损害", "is_correct": true, "explanation": "正确：损害指使名声遭到破坏，与“说假话”的后果一致。"}, {"text": "提升", "is_correct": false, "explanation": "语义：提升指使名声变得更好，与“说假话”的后果相反。"}, {"text": "维护", "is_correct": false, "explanation": "语义：维护指保持并保护，与“说假话”的后果相矛盾。"}, {"text": "保卫", "is_correct": false, "explanation": "搭配：保卫的对象多是国家、领土等，不说“保卫名声”，且与“说假话”矛盾。"}], "explanations": {"损害": "正确：损害指使名声遭到破坏，与“说假话”的后果一致。", "提升": "语义：提升指使名声变得更好，与“说假话”的后果相反。", "维护": "语义：维护指保持并保护，与“说假话”的后果相矛盾。", "保卫": "搭配：保卫的对象多是国家、领土等，不说“保卫名声”，且与“说假话”矛盾。"}, "sentence_index": 0, "correct_answer": "损害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一拳损害了同学。", "explanation": "这里应该用〈伤害〉。损害多用于名声、利益、环境等，直接伤及他人的身体时用〈伤害〉。"}, {"text": "排队损害了我们很多时间。", "explanation": "这里应该用〈浪费〉。损害多指使事物变坏、受伤，时间白白耗去要说“浪费”，不说“损害时间”。"}, {"text": "他随手损害了那道数学题。", "explanation": "这里应该用〈解答〉。损害指使事物遭受破坏，解题应说“解答”，不说“损害题目”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "损害", "is_correct": true, "explanation": "正确：损害指使友谊遭到破坏，与“没有”构成否定语境后句意通顺。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：购买的对象是物品，不说“购买友谊”。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：讨论的主体须是人，“这件事”不能“讨论”什么，句意不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰指修饰外表，与友谊无关，句意不通。"}], "explanations": {"损害": "正确：损害指使友谊遭到破坏，与“没有”构成否定语境后句意通顺。", "购买": "搭配：购买的对象是物品，不说“购买友谊”。", "讨论": "语义：讨论的主体须是人，“这件事”不能“讨论”什么，句意不通。", "装饰": "语义：装饰指修饰外表，与友谊无关，句意不通。"}, "sentence_index": 6, "correct_answer": "损害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次治疗损害了他的病。", "explanation": "这里应该用〈治愈〉。损害是使事物变坏，不能用于消除病痛，应说“治愈了他的病”。"}, {"text": "他的努力损害了这场比赛的胜利。", "explanation": "这里应该用〈赢得〉。损害指使事物变坏，胜利应说“赢得”，不说“损害胜利”。"}, {"text": "他把坏掉的玩具损害好了。", "explanation": "这里应该用〈修好〉。损害是使事物变坏，“损害好了”自相矛盾，应说“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种做法会严重对损害公司的利益。", "corrected_sentence": "这种做法会严重损害公司的利益。", "error_description": "错误：“严重”修饰“损害”，二者之间不能插入介词“对”，应说“会严重损害公司的利益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的错误损害坏了我们的利益。", "corrected_sentence": "他的错误损害了我们的利益。", "error_description": "“损害坏”是“损害”与“损坏”的混用，“坏”不能作“损害”的补语；应说“损害了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
