INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人都在看、在说的事情。", "primary_collocate": null, "pronunciation": "rè diǎn", "ipa": "ʐɤ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这几天，这件事成了网上的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天大家都在聊的热点是什么？", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个热点一出来，大家都在讨论。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看手机，想知道最新的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星结婚的消息成了今天的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说最近的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的热点是新电影，朋友们都去看了。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个热点很快就过去了，没人再说。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对网上的热点不太感兴趣。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到晚上，同学们就聊起热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个热点", "label": "量词（个）"}, {"form": "热点话题", "label": "复合词"}, {"form": "热点新闻", "label": "复合词"}, {"form": "熱點", "label": "繁体"}], "register": "通用", "sense_fingerprint": "大家都在看、都在谈论的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是网上被大家讨论的事情。"}, {"text": "热点", "is_correct": true, "explanation": "正确：热点指大家都在关注、谈论的事情，与“网上”“这件事”相符。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田是耕种的土地，不能成为网上被讨论的事。"}, {"text": "冰川", "is_correct": false, "explanation": "搭配：“成了网上的……”要接可以被谈论的事件，“冰川”不能用于网上的谈论。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，不是网上被大家讨论的事情。", "热点": "正确：热点指大家都在关注、谈论的事情，与“网上”“这件事”相符。", "农田": "语义：农田是耕种的土地，不能成为网上被讨论的事。", "冰川": "搭配：“成了网上的……”要接可以被谈论的事件，“冰川”不能用于网上的谈论。"}, "sentence_index": 0, "correct_answer": "热点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚在网上翻到一把热点。", "explanation": "这里应该用〈个〉。热点指大家关注的事件，用“个”；“把”用于有柄的器具，不能修饰热点。"}, {"text": "我昨天看到一只热点。", "explanation": "这里应该用〈个〉。热点指大家关注的事件，用“个”；“只”多用于动物，不能修饰热点。"}, {"text": "电视台每天播出一幅最新的热点。", "explanation": "这里应该用〈个〉。热点指大家关注的事件，用“个”；“幅”用于图画、字画，不能修饰热点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墓地", "is_correct": false, "explanation": "语义：墓地与新电影和大家去看的场面不符。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“现在的……是新电影”要接可以被谈论的事物，“汽油”不能与电影并列。"}, {"text": "热点", "is_correct": true, "explanation": "正确：热点指大家都在关注的事情，“现在的热点是新电影”说得通。"}, {"text": "药材", "is_correct": false, "explanation": "语义：药材与“新电影”“大家去看”不相关，不能指大家关注的事情。"}], "explanations": {"墓地": "语义：墓地与新电影和大家去看的场面不符。", "汽油": "搭配：“现在的……是新电影”要接可以被谈论的事物，“汽油”不能与电影并列。", "热点": "正确：热点指大家都在关注的事情，“现在的热点是新电影”说得通。", "药材": "语义：药材与“新电影”“大家去看”不相关，不能指大家关注的事情。"}, "sentence_index": 6, "correct_answer": "热点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事成了一块热点。", "explanation": "这里应该用〈个〉。热点用“个”，“块”多用于有形的东西，不能修饰热点。"}, {"text": "这件事在网上成了一座热点。", "explanation": "这里应该用〈个〉。热点指大家关注的事件，用“个”；“座”多用于山、桥、楼房等大型固定建筑，不能修饰热点。"}, {"text": "一到晚上，同学们就聊起一张热点。", "explanation": "这里应该用〈个〉。热点指大家关注的事件，用“个”；“张”多用于纸张、桌子等平面的东西，不能修饰热点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事成了热点的。", "corrected_sentence": "这件事成了热点。", "error_description": "错误形式：“热点的”，句末的“的”后面没有中心语。正确形式：“成了热点”，“热点”后不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现在的热点们是新电影，朋友们都去看。", "corrected_sentence": "现在的热点是新电影，朋友们都去看。", "error_description": "错误形式：“热点”后加了“们”。正确形式：“热点”不加“们”，表示泛指时直接说“热点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
