INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受到广泛关注的地方或事件。", "primary_collocate": null, "pronunciation": "rè diǎn", "ipa": "ʐɤ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小城是今年的旅游热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，这里成了热点，人特别多。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁新线开通，成了市民关注的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥是游客最爱去的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界杯是今年全世界的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的小店是年轻人的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方是拍照的热点，每天都排队。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛是全国的热点，记者都来了。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的商场是购物的热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山以前很安静，现在成了热点。", "target_word": "热点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个热点", "label": "量词（个）"}, {"form": "旅游热点", "label": "复合词"}, {"form": "热点地区", "label": "复合词"}, {"form": "熱點", "label": "繁体"}], "register": "通用", "sense_fingerprint": "很多人关注的地方或事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地雷", "is_correct": false, "explanation": "语义：地雷是爆炸装置，不能作为游客喜爱的旅游地。"}, {"text": "垃圾场", "is_correct": false, "explanation": "语义：垃圾场不是游客聚集的地方，与“旅游”搭配不通。"}, {"text": "热点", "is_correct": true, "explanation": "正确：热点指受到很多人关注的地方，“今年的旅游热点”说得通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“旅游”后面要接游客前往的地方，厨房一般不作为旅游景点。"}], "explanations": {"地雷": "语义：地雷是爆炸装置，不能作为游客喜爱的旅游地。", "垃圾场": "语义：垃圾场不是游客聚集的地方，与“旅游”搭配不通。", "热点": "正确：热点指受到很多人关注的地方，“今年的旅游热点”说得通。", "厨房": "搭配：“旅游”后面要接游客前往的地方，厨房一般不作为旅游景点。"}, "sentence_index": 0, "correct_answer": "热点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老桥是游客最爱去的一把热点。", "explanation": "这里应该用〈个〉。热点指受关注的地方或事件，用“个”；“把”用于有柄的器具，不能修饰热点。"}, {"text": "这座老桥是游客最爱去的一只热点。", "explanation": "这里应该用〈个〉。“只”多用于动物，不能修饰表示地点的热点。"}, {"text": "这座老桥是游客最爱去的一幅热点。", "explanation": "这里应该用〈个〉。热点指受关注的地方或事件，用“个”；“幅”用于图画、字画，不能修饰热点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下水道", "is_correct": false, "explanation": "语义：下水道是排污的地下管道，不是大家拍照、排队前往的地方。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地与拍照、排队的场景不符。"}, {"text": "药房", "is_correct": false, "explanation": "搭配：“拍照的……”要接景色好、适合拍照的地方，药房不能与拍照搭配。"}, {"text": "热点", "is_correct": true, "explanation": "正确：热点指受到很多人关注的地方，“拍照的热点，每天都排队”说得通。"}], "explanations": {"下水道": "语义：下水道是排污的地下管道，不是大家拍照、排队前往的地方。", "墓地": "语义：墓地与拍照、排队的场景不符。", "药房": "搭配：“拍照的……”要接景色好、适合拍照的地方，药房不能与拍照搭配。", "热点": "正确：热点指受到很多人关注的地方，“拍照的热点，每天都排队”说得通。"}, "sentence_index": 6, "correct_answer": "热点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山现在是一张热点。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，不能修饰表示地点的热点。"}, {"text": "这座山以前很安静，现在成了一首热点。", "explanation": "这里应该用〈个〉。热点指受关注的地方，用“个”；“首”用于诗歌、歌曲，不能修饰热点。"}, {"text": "这座山以前很安静，现在成了一辆热点。", "explanation": "这里应该用〈个〉。热点指受关注的地方，用“个”；“辆”用于车辆，不能修饰热点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城成了热点的。", "corrected_sentence": "这座小城成了热点。", "error_description": "错误形式：“热点的”，句末的“的”后面没有中心语。正确形式：“成了热点”，“热点”后不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地方是拍照的热点们，每天都排队呢。", "corrected_sentence": "这个地方是拍照的热点，每天都排队呢。", "error_description": "错误形式：“热点”后加了“们”。正确形式：“热点”不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。"}, {"text": "哭", "is_correct": false, "explanation": "哭是情绪动作，与“安放”没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "跳是移动动作，与“安放”不在反义关系中。"}, {"text": "写", "is_correct": false, "explanation": "写是书写动作，与“安放”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。", "哭": "哭是情绪动作，与“安放”没有反义关系。", "跳": "跳是移动动作，与“安放”不在反义关系中。", "写": "写是书写动作，与“安放”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声动作，与“安放”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食动作，与“安放”不在反义关系中。"}, {"text": "说", "is_correct": false, "explanation": "说是言语动作，与“安放”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。", "唱": "唱是发声动作，与“安放”没有反义关系。", "吃": "吃是进食动作，与“安放”不在反义关系中。", "说": "说是言语动作，与“安放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摆是把东西一个一个放好。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把玩具一个一个摆在地上。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先摆碗，你再摆筷子。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在桌上摆了一排小汽车。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开饭前，爸爸把菜摆好了。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把鞋子摆得很整齐。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的小摊摆着各种水果。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把花瓶摆在窗户旁边。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师摆了五把椅子在前面。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢把照片摆在床边。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场里摆满了过年用的东西。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆了", "label": "体标"}, {"form": "摆着", "label": "体标"}, {"form": "摆过", "label": "体标"}, {"form": "摆放", "label": "复合"}, {"form": "擺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西一个一个放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西一个一个安放好。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bǎi 声调不同，意思是失败，与安放无关。"}, {"text": "北", "is_correct": false, "explanation": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西一个一个安放好。", "败": "bài 与 bǎi 声调不同，意思是失败，与安放无关。", "北": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。", "把": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把玩具一个一个安放在地上，与“一个一个”的动作相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与玩具和地面搭配，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”是发出歌声，不能用来安放玩具，句子不通。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指散落，与“一个一个”的有序安放相反。"}], "explanations": {"摆": "“摆”表示把玩具一个一个安放在地上，与“一个一个”的动作相符。", "吃": "搭配：“吃”的对象是食物，不能与玩具和地面搭配，句子不通。", "唱": "搭配：“唱”是发出歌声，不能用来安放玩具，句子不通。", "撒": "语义：“撒”指散落，与“一个一个”的有序安放相反。"}, "sentence_index": 0, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙摆进口袋里。", "explanation": "这里应该用〈放进〉。摆指在平面或一定位置排列，放入口袋这样的容器要用“放”。"}, {"text": "他把头发摆短了。", "explanation": "这里应该用〈剪〉。摆指安放或排列，不能表示把头发剪短。"}, {"text": "他把饭菜摆进嘴里。", "explanation": "这里应该用〈吃〉。摆指按次序放在一定位置，不能表示把食物送进嘴里吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西安放在一定位置。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bǎi 声调不同，意思是拜访或拜谢。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西安放在一定位置。", "拜": "bài 与 bǎi 声调不同，意思是拜访或拜谢。", "板": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把花瓶安放在窗户旁边，与“请把花瓶……在窗户旁边”相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿动作，与安放花瓶无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于清洁物品，不能说“洗在窗户旁边”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与安放花瓶的动作无关。"}], "explanations": {"摆": "“摆”表示把花瓶安放在窗户旁边，与“请把花瓶……在窗户旁边”相符。", "咬": "语义：“咬”是用牙齿动作，与安放花瓶无关。", "洗": "搭配：“洗”用于清洁物品，不能说“洗在窗户旁边”。", "煮": "语义：“煮”是加热食物，与安放花瓶的动作无关。"}, "sentence_index": 6, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把茶摆进杯子里。", "explanation": "这里应该用〈倒〉。摆指按次序放在一定位置，不能表示把液体注入容器。"}, {"text": "他把纸摆进垃圾桶里。", "explanation": "这里应该用〈扔〉。摆指安放或排列，不能表示把东西丢弃。"}, {"text": "他摆了一个噩梦。", "explanation": "这里应该用〈做〉。摆指安放或排列，不能表示做梦；做噩梦要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书一本一本摆了在桌上。", "corrected_sentence": "他把书一本一本摆在桌上。", "error_description": "“了”位置错误：“摆”后接处所时用“在”，动态助词“了”不能插在“摆”和“在”之间，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把相框摆得在床头。", "corrected_sentence": "他把相框摆在床头。", "error_description": "“得”误加：“摆”后直接接处所要用“在”，“得”须接程度或状态补语，“摆得在床头”不通，应去掉“得”，即“摆在床头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
