INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "安放；把东西按次序放在一定位置。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "请把杯子摆在桌子上。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把筷子一双一双摆好了。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书架上摆了很多书。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，快把椅子摆好。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上摆着一盆花。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员正在摆碗和盘子。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们把桌子摆成一个圆圈。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店门口摆着新鞋。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，家里会摆很多水果。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把书按大小摆整齐。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆了", "label": "体标"}, {"form": "摆着", "label": "体标"}, {"form": "摆过", "label": "体标"}, {"form": "摆放", "label": "复合"}, {"form": "擺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西按次序安放在一定位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西按次序安放。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bǎi 声调不同（第四声与第三声），意思是失败，与安放无关。"}, {"text": "白", "is_correct": false, "explanation": "bái 与 bǎi 声调不同（第二声与第三声），意思是白色。"}, {"text": "北", "is_correct": false, "explanation": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西按次序安放。", "败": "bài 与 bǎi 声调不同（第四声与第三声），意思是失败，与安放无关。", "白": "bái 与 bǎi 声调不同（第二声与第三声），意思是白色。", "北": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把杯子按位置安放，与“请把杯子……在桌子上”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，与把杯子放置在桌上无关。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿动作，与放杯子的动作不相容。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只用于衣服鞋帽，不能与杯子和桌子搭配。"}], "explanations": {"摆": "“摆”表示把杯子按位置安放，与“请把杯子……在桌子上”的语境相符。", "唱": "语义：“唱”是发出歌声，与把杯子放置在桌上无关。", "咬": "语义：“咬”是用牙齿动作，与放杯子的动作不相容。", "穿": "搭配：“穿”只用于衣服鞋帽，不能与杯子和桌子搭配。"}, "sentence_index": 0, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把信摆到邮局。", "explanation": "这里应该用〈寄〉。摆指把东西按次序放在一定位置，不能表示把东西送往别处；寄信要用寄。"}, {"text": "她摆了一个噩梦。", "explanation": "这里应该用〈做〉。摆指安放或排列，不能表示做梦；做噩梦要用做。"}, {"text": "他们摆了一个会。", "explanation": "这里应该用〈开〉。摆指安放或排列，不能表示召集会议；召开会议要用开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西按次序安放。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bǎi 声调不同，意思是拜访或拜谢。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西按次序安放。", "拜": "bài 与 bǎi 声调不同，意思是拜访或拜谢。", "把": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。", "板": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把桌子排列成圆圈，与“学生们把桌子……成一个圆圈”的语境相符。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于线和布料，不能用来形容桌子的排列。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物的动作，与排列桌子无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于水和物品的清洁，不能与桌子的圆圈排列搭配。"}], "explanations": {"摆": "“摆”表示把桌子排列成圆圈，与“学生们把桌子……成一个圆圈”的语境相符。", "织": "搭配：“织”用于线和布料，不能用来形容桌子的排列。", "煮": "语义：“煮”是加热食物的动作，与排列桌子无关。", "洗": "搭配：“洗”用于水和物品的清洁，不能与桌子的圆圈排列搭配。"}, "sentence_index": 6, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈摆了一个生日愿望。", "explanation": "这里应该用〈许〉。摆指安放或排列，不能表示许愿。"}, {"text": "老师摆了一首歌。", "explanation": "这里应该用〈唱〉。摆指安放或排列，不能表示唱歌；唱一首歌要用唱。"}, {"text": "他摆了一个笑话。", "explanation": "这里应该用〈讲〉。摆指安放或排列，不能表示说笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上摆了着三本字典。", "corrected_sentence": "桌上摆着三本字典。", "error_description": "“了”和“着”不能同时用在动词“摆”后面，表示持续状态应只用“着”，即“摆着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把碗筷摆了好。", "corrected_sentence": "妈妈把碗筷摆好了。", "error_description": "“了”位置错误：结果补语“好”后面要接“了”，应为“摆好了”，不能说“摆了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
