INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运输工具运行，载客载货以取得收入；也指机构的经营运作。", "primary_collocate": null, "pronunciation": "yíng yùn", "ipa": "iŋ˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的新线路下个月开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线路每天从早到晚营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家船公司已经营运了十年。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家连锁书店营运得很稳，没有亏钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司营运得很好，今年赚了不少钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商场营运了三年，一直不赚钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机坏了，这条航线只好停止营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥修好后，新线路马上开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算明年扩大营运的范围。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新船开始营运以后，游客多了很多。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营运了", "label": "体标"}, {"form": "营运过", "label": "体标"}, {"form": "营运成本", "label": "复合"}, {"form": "营运资金", "label": "复合"}], "register": "书面", "sense_fingerprint": "运输工具载客载货取得收入的运行，也指机构的经营运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营运", "is_correct": true, "explanation": "营运（yíng yùn）：运输工具运行、载客载货取得收入，或机构的经营运作，即本词。"}, {"text": "营业", "is_correct": false, "explanation": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。"}, {"text": "营养", "is_correct": false, "explanation": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。"}, {"text": "命运", "is_correct": false, "explanation": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。"}, {"text": "幸运", "is_correct": false, "explanation": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。"}, {"text": "盈余", "is_correct": false, "explanation": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}], "explanations": {"营运": "营运（yíng yùn）：运输工具运行、载客载货取得收入，或机构的经营运作，即本词。", "营业": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。", "营养": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。", "命运": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。", "幸运": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。", "盈余": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}, "sentence_index": null, "correct_answer": "营运"}, "level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：“开始营运”指新线路开始运行，与句意相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：线路不会唱歌，“开始唱歌”与线路不合。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：线路是运输服务，不能“装修”，“装修”只搭配房屋等。"}, {"text": "上课", "is_correct": false, "explanation": "配价：“开始上课”要求有学习的人作主语，“线路”不能上课。"}], "explanations": {"营运": "正确：“开始营运”指新线路开始运行，与句意相合。", "唱歌": "语义：线路不会唱歌，“开始唱歌”与线路不合。", "装修": "搭配：线路是运输服务，不能“装修”，“装修”只搭配房屋等。", "上课": "配价：“开始上课”要求有学习的人作主语，“线路”不能上课。"}, "sentence_index": 0, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司每天营运三十个员工。", "explanation": "这里应该用〈雇用〉。营运不带“员工”作宾语，应说“雇用”。"}, {"text": "这家工厂的机器每天营运八小时。", "explanation": "这里应该用〈运行〉。营运用于运输工具和机构，机器运转应说“运行”。"}, {"text": "我的小猫每天营运到十二点。", "explanation": "这里应该用〈玩〉。营运的主语是运输工具或机构，不能用动物作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：“停止营运”是固定搭配，指航线停止运营。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：航线不能唱歌，与“飞机坏了”的语境不合。"}, {"text": "上学", "is_correct": false, "explanation": "配价：“停止上学”的主语须是学生，航线不能上学。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：航线不能“考试”，“停止考试”与句中的交通情境不搭。"}], "explanations": {"营运": "正确：“停止营运”是固定搭配，指航线停止运营。", "唱歌": "语义：航线不能唱歌，与“飞机坏了”的语境不合。", "上学": "配价：“停止上学”的主语须是学生，航线不能上学。", "考试": "搭配：航线不能“考试”，“停止考试”与句中的交通情境不搭。"}, "sentence_index": 6, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天营运三百个零件。", "explanation": "这里应该用〈制造〉。营运不带产品作宾语，工厂生产零件应说“制造”。"}, {"text": "护士每晚在医院营运到十二点。", "explanation": "这里应该用〈值班〉。营运的主语是运输工具或机构，不能用人作主语。"}, {"text": "这盏台灯每晚营运到十二点。", "explanation": "这里应该用〈亮〉。营运只用于运输工具和机构，台灯应说“亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家物流公司的货车全年都被营运。", "corrected_sentence": "这家物流公司的货车全年都在营运。", "error_description": "“营运”是不及物动词，不能用“被”字句。表示正在进行应在动词前用“在”，应说“都在营运”，不说“都被营运”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家航空公司的新航班已经营运了着两个月。", "corrected_sentence": "这家航空公司的新航班已经营运了两个月。", "error_description": "体标错误：“了”和“着”不能叠用在同一个动词后。应说“已经营运了两个月”，不说“已经营运了着两个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期与早期相对，指某一时期的后一段，是标准反义词。"}, {"text": "花园", "is_correct": false, "explanation": "花园是具体场所，与“早期”没有反义关系。"}, {"text": "墙壁", "is_correct": false, "explanation": "墙壁是具体物体，与“早期”不构成反义。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚是一天中的时段，与“早期”不是同一义项，也不构成反义。"}], "correct_answer": "后期", "explanations": {"后期": "后期与早期相对，指某一时期的后一段，是标准反义词。", "花园": "花园是具体场所，与“早期”没有反义关系。", "墙壁": "墙壁是具体物体，与“早期”不构成反义。", "夜晚": "夜晚是一天中的时段，与“早期”不是同一义项，也不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期与早期相对，指某一时期的后一段，是标准反义词。"}, {"text": "石头", "is_correct": false, "explanation": "石头是具体物体，与“早期”没有反义关系。"}, {"text": "河水", "is_correct": false, "explanation": "河水与“早期”不是同一义项，也不构成反义。"}, {"text": "冬天", "is_correct": false, "explanation": "冬天是季节，与“早期”不在反义关系中。"}], "correct_answer": "后期", "explanations": {"后期": "后期与早期相对，指某一时期的后一段，是标准反义词。", "石头": "石头是具体物体，与“早期”没有反义关系。", "河水": "河水与“早期”不是同一义项，也不构成反义。", "冬天": "冬天是季节，与“早期”不在反义关系中。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "早期是一段时间最前面的那一段。", "primary_collocate": null, "pronunciation": "zǎo qī", "ipa": "tsɑʊ˨˩˦ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "清朝早期，国家很稳定。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的电脑要占满一个房间。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球队早期很弱，后来越来越强。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作早期遇到过很多困难。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的火车跑得很慢。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病在早期发现，治好的机会更大。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店早期卖衣服，现在卖咖啡。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷早期住在乡下，后期搬到了城里。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐朝早期，长安已经很热闹。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学说话的早期，爸爸妈妈要多和他说话。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一段时间最前面的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期指一段时间的前段，与“清朝”搭配，说明那一朝代的前段国家稳定。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：夏天是季节，不能与朝代名组合成时间段。"}, {"text": "周末", "is_correct": false, "explanation": "语义：周末是一周中的时段，与朝代不相容，句子不通。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学不是朝代的时间段，“清朝大学”无法说明国家状况。"}], "explanations": {"早期": "早期指一段时间的前段，与“清朝”搭配，说明那一朝代的前段国家稳定。", "夏天": "搭配：夏天是季节，不能与朝代名组合成时间段。", "周末": "语义：周末是一周中的时段，与朝代不相容，句子不通。", "大学": "语义：大学不是朝代的时间段，“清朝大学”无法说明国家状况。"}, "sentence_index": 0, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小吃摊的早期是五点到七点。", "explanation": "这里应该用〈营业时间〉。早期指某一时期的前段，不能表示一天中的营业时段。"}, {"text": "这次演唱会的早期定在三点。", "explanation": "这里应该用〈时间〉。早期指一段时期的前段，不能指具体钟点。"}, {"text": "孩子们的早期是周末。", "explanation": "这里应该用〈假日〉。早期指某一时期的前段，不能指具体的日子；表示休息的日子要用假日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期表示这家店经营衣服的前一阶段，与后文“现在卖咖啡”形成对照。"}, {"text": "墙上", "is_correct": false, "explanation": "搭配：“墙上”是位置，不能作“卖衣服”的时间状语。"}, {"text": "海里", "is_correct": false, "explanation": "语义：海里不是时间，“海里卖衣服”与店铺的经营时段无关，句子不通。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上指空中，与“这家店卖衣服”的经营情况直接矛盾。"}], "explanations": {"早期": "早期表示这家店经营衣服的前一阶段，与后文“现在卖咖啡”形成对照。", "墙上": "搭配：“墙上”是位置，不能作“卖衣服”的时间状语。", "海里": "语义：海里不是时间，“海里卖衣服”与店铺的经营时段无关，句子不通。", "天上": "语义：天上指空中，与“这家店卖衣服”的经营情况直接矛盾。"}, "sentence_index": 6, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节目的早期是今晚。", "explanation": "这里应该用〈播出时间〉。早期指某一时期的前段，不能指节目播出的具体时间。"}, {"text": "这次考试的早期定在半夜。", "explanation": "这里应该用〈时间〉。早期指某一时期的前段，不能指具体钟点。"}, {"text": "我们的会议早期定在周五上午。", "explanation": "这里应该用〈时间〉。早期指某一时期的前段，不能指会议安排的具体时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城在早期了很安静。", "corrected_sentence": "这座小城在早期很安静。", "error_description": "“了”误加：“在早期”是整体状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个球队早期了很弱，后来变强了。", "corrected_sentence": "那个球队早期很弱，后来变强了。", "error_description": "“了”误加：“早期”是时间名词作状语，后面不能接动态助词“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 8]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期与早期相对，指某一时期的后一段，是这一义项的标准反义词。"}, {"text": "河流", "is_correct": false, "explanation": "河流与“早期”没有反义关系，只是同为名词。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是具体物品，与表示时间段的“早期”不构成任何反义关系。"}, {"text": "黑夜", "is_correct": false, "explanation": "黑夜指一天中的时段，与“早期”不是同一义项，也不构成反义。"}], "correct_answer": "后期", "explanations": {"后期": "后期与早期相对，指某一时期的后一段，是这一义项的标准反义词。", "河流": "河流与“早期”没有反义关系，只是同为名词。", "桌子": "桌子是具体物品，与表示时间段的“早期”不构成任何反义关系。", "黑夜": "黑夜指一天中的时段，与“早期”不是同一义项，也不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期与早期相对，指某一时期的后一段，是标准反义词。"}, {"text": "墙壁", "is_correct": false, "explanation": "墙壁是具体物体，与“早期”没有反义关系。"}, {"text": "河水", "is_correct": false, "explanation": "河水与“早期”不是同一义项，也不构成反义。"}, {"text": "冬天", "is_correct": false, "explanation": "冬天是季节，与“早期”不在反义关系中。"}], "correct_answer": "后期", "explanations": {"后期": "后期与早期相对，指某一时期的后一段，是标准反义词。", "墙壁": "墙壁是具体物体，与“早期”没有反义关系。", "河水": "河水与“早期”不是同一义项，也不构成反义。", "冬天": "冬天是季节，与“早期”不在反义关系中。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一时期中最初的一段时间。", "primary_collocate": null, "pronunciation": "zǎo qī", "ipa": "tsɑʊ˨˩˦ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这座城市在早期只是一个小村子。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影早期都是黑白的，没有声音。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早期的画很简单，后来才越来越复杂。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病在早期很容易治好。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝早期，这里住着很多商人。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司早期只有五个人，现在有五百人了。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的手机很大，也很重。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学习汉字的早期，常常记不住字形。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家早期写小说，后期写诗。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题要在早期，不要拖到以后。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某一时期最初的一段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8fb1b2e-274c-4409-8f46-31e464d92e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期指某一时期的最初一段，与“只是一个小村子”描述的过去状况相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不能充当时间或地点，“在石头只是一个小村子”不通。"}, {"text": "汽水", "is_correct": false, "explanation": "语义：汽水是饮料，不能充当时间或地点，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能充当时间或地点，句子不通。"}], "explanations": {"早期": "早期指某一时期的最初一段，与“只是一个小村子”描述的过去状况相符。", "石头": "语义：石头是物体，不能充当时间或地点，“在石头只是一个小村子”不通。", "汽水": "语义：汽水是饮料，不能充当时间或地点，句子不通。", "书包": "语义：书包是物品，不能充当时间或地点，句子不通。"}, "sentence_index": 0, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的早期是七点到十点。", "explanation": "这里应该用〈早市〉。早期指某一时期的前段，不能表示一天中的营业时段；早上的集市要用早市。"}, {"text": "明天的早期是九点。", "explanation": "这里应该用〈上课时间〉。早期指某一时期的前段，不能指一天中的具体钟点。"}, {"text": "工厂的早期是六点半开工。", "explanation": "这里应该用〈早班〉。早期表示一段时期，不能指上班的具体时间；表示按时上班的时段要用早班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期修饰“手机”，表示手机出现的最初阶段，与“很大，也很重”的特点相符。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁体形极小，与“很大，也很重”直接矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语法：“唱”是动词，不能作“手机”的定语，句子不通。"}, {"text": "跑", "is_correct": false, "explanation": "语法：“跑”是动词，不能作“手机”的定语，句子不通。"}], "explanations": {"早期": "早期修饰“手机”，表示手机出现的最初阶段，与“很大，也很重”的特点相符。", "蚂蚁": "体貌：蚂蚁体形极小，与“很大，也很重”直接矛盾。", "唱": "语法：“唱”是动词，不能作“手机”的定语，句子不通。", "跑": "语法：“跑”是动词，不能作“手机”的定语，句子不通。"}, "sentence_index": 6, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早期七点起床。", "explanation": "这里应该用〈早上〉。早期指某一时期的前段，不能表示一天中的清晨。"}, {"text": "明天早期我们去公园跑步。", "explanation": "这里应该用〈早晨〉。早期指某一时期的前段，不能表示某一天的早晨。"}, {"text": "这次活动的早期是三号。", "explanation": "这里应该用〈日期〉。早期指一段时期的前段，不能指某个具体日子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家小店在早期了只有两个店员。", "corrected_sentence": "那家小店在早期只有两个店员。", "error_description": "“了”误加：“在早期”是时间状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期只有两个店员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种手机在早期了很贵，后来才便宜。", "corrected_sentence": "这种手机在早期很贵，后来才便宜。", "error_description": "“了”误加：“在早期”是时间状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期很贵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2aedba-2123-430c-a483-95e66c9bc791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
