INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92389, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "第一个做。", "primary_collocate": null, "pronunciation": "shuài xiān", "ipa": "ʂuai⁵¹ ɕiɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "他率先举起了手。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王率先跑到了终点。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，我们队就率先得分。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问完问题，小李率先回答。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她率先走进了教室。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司率先用上了这种新机器。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他率先把门打开了。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥率先跳进了河里。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发令枪一响，他率先冲了出去。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不敢说话，只有她率先开口。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "第一个做某事，作状语放在动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "率先", "is_correct": true, "explanation": "“率先”表示抢在别人前面，修饰“举起”，与句意相合。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求多人同时行动，“他”单独举手不能用。"}, {"text": "时常", "is_correct": false, "explanation": "语义：“时常”表示反复发生，与“举起了手”这一次性动作矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，多用于否定，不能修饰单次完成的“举起了手”。"}], "explanations": {"率先": "“率先”表示抢在别人前面，修饰“举起”，与句意相合。", "一起": "搭配：“一起”要求多人同时行动，“他”单独举手不能用。", "时常": "语义：“时常”表示反复发生，与“举起了手”这一次性动作矛盾。", "从来": "语义：“从来”表示一向如此，多用于否定，不能修饰单次完成的“举起了手”。"}, "sentence_index": 0, "correct_answer": "率先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他率先排在队伍的最后。", "explanation": "率先表示抢在别人前面做，和“排在队伍的最后”意思矛盾，不能这样用。"}, {"text": "每人率先发言一次。", "explanation": "这里误把率先当成〈依次〉的意思。率先强调抢在他人之前，每人都率先就没有先后之分。"}, {"text": "率先，我们要检查设备。", "explanation": "这里应该用〈首先〉。率先强调抢在别人之前行动，不用于列举步骤的开头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "率先", "is_correct": true, "explanation": "“率先”修饰“把门打开”，表示抢先完成这一动作。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常，与句中单次完成的“打开了”不符。"}, {"text": "一同", "is_correct": false, "explanation": "搭配：“一同”要求多人一起行动，“他”单独开门不能用。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”用于多人发声，不能修饰“开门”这一动作。"}], "explanations": {"率先": "“率先”修饰“把门打开”，表示抢先完成这一动作。", "总是": "语义：“总是”表示经常，与句中单次完成的“打开了”不符。", "一同": "搭配：“一同”要求多人一起行动，“他”单独开门不能用。", "齐声": "搭配：“齐声”用于多人发声，不能修饰“开门”这一动作。"}, "sentence_index": 6, "correct_answer": "率先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人率先同时开口，老师很高兴。", "explanation": "这里误把率先当成〈一起〉的意思。率先强调先于他人，两人同时行动就不能用率先。"}, {"text": "这个决定，他率先做了三遍。", "explanation": "这里误把率先当成〈反复〉的意思。率先只表示先于他人，不能用于重复多次的动作。"}, {"text": "每人都率先交了作业。", "explanation": "这里应该用〈各自〉。率先表示先于他人，每个人都率先就没有先后之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班率先的完成了作业。", "corrected_sentence": "我们班率先完成了作业。", "error_description": "错误：“率先的完成了作业”；正确：“率先完成了作业”。率先是副词，直接修饰动词，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
