INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92390, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "带头；最先。", "primary_collocate": null, "pronunciation": "shuài xiān", "ipa": "ʂuai⁵¹ ɕiɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "校长率先捐款，大家也纷纷跟着捐了。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师率先打扫教室，同学们也都来帮忙。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市率先实行了新的规定。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上率先发言，说了自己的看法。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸率先戒了烟，全家人都很支持。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里率先修了路，生活方便多了。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店率先推出了新菜。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长率先下水，队员们紧跟在后面。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她率先报名参加了比赛。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小张率先交了作业，老师夸了他。", "target_word": "率先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "带头、最先行动，别人随后跟进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "率先", "is_correct": true, "explanation": "“率先”表示带头先行，与“大家也纷纷跟着捐了”相合。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中进行，与“大家纷纷跟着”的公开跟进矛盾。"}, {"text": "凶猛", "is_correct": false, "explanation": "搭配：“凶猛”形容兽类或气势，不能修饰“捐款”这一行为。"}, {"text": "一齐", "is_correct": false, "explanation": "搭配：“一齐”要求多人同时行动，“校长”单独捐款不能用。"}], "explanations": {"率先": "“率先”表示带头先行，与“大家也纷纷跟着捐了”相合。", "偷偷": "语义：“偷偷”表示暗中进行，与“大家纷纷跟着”的公开跟进矛盾。", "凶猛": "搭配：“凶猛”形容兽类或气势，不能修饰“捐款”这一行为。", "一齐": "搭配：“一齐”要求多人同时行动，“校长”单独捐款不能用。"}, "sentence_index": 0, "correct_answer": "率先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班同学率先一起走进了教室。", "explanation": "这里误把率先当成〈一起〉的意思。率先强调带头、先于他人，全班一起行动就没有人带头。"}, {"text": "两位同学率先一齐开口，老师很高兴。", "explanation": "两人一齐开口，就没有谁带头、谁在先，不能用率先。"}, {"text": "率先，请大家检查设备。", "explanation": "这里应该用〈首先〉。率先强调抢在别人之前行动，不用于列举步骤的开头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "率先", "is_correct": true, "explanation": "“率先”修饰“推出新菜”，表示抢先行动，与句意相合。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容质地，不能修饰“推出”这一行为。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”用于多人发声，“这家店”推出新菜不能用。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有收获，与“推出新菜”的主动行为矛盾。"}], "explanations": {"率先": "“率先”修饰“推出新菜”，表示抢先行动，与句意相合。", "粗糙": "搭配：“粗糙”形容质地，不能修饰“推出”这一行为。", "齐声": "搭配：“齐声”用于多人发声，“这家店”推出新菜不能用。", "白白": "语义：“白白”表示徒然、没有收获，与“推出新菜”的主动行为矛盾。"}, "sentence_index": 6, "correct_answer": "率先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他率先跟在队伍最后走出了教室。", "explanation": "率先表示带头、走在别人前面，和“跟在队伍最后”矛盾。"}, {"text": "每个人率先交了作业。", "explanation": "这里应该用〈各自〉。率先表示先于他人，每个人都“率先”就没有先后之分。"}, {"text": "家里只有他一个人，他率先吃了晚饭。", "explanation": "这里应该用〈先〉。只有一个人，没有可以带头或比较先后的对象，不能用率先。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
