INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92391, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "现身是在大家面前出来。", "primary_collocate": null, "pronunciation": "xiàn shēn", "ipa": "ɕjɛn˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "魔术师突然在舞台中间现身了。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，那只小狐狸才现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家等了很久，老师终于现身了。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门打开了，新郎慢慢现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只黑猫在柜子底下躲了一下午，傍晚才现身。", "target_word": "现身", "complexity_tier": "T3", "furigana": "nà zhī hēi māo zài guìzi dǐxia duǒ le yí xiàwǔ, bàngwǎn cái xiànshēn.", "sentence_source": "generated"}, {"text": "小朋友们都在找他，他却不肯现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出开始时，歌手从台下现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等到半夜，他才在门口现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条大鱼在湖边现身，很多人拍照。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直躲着，今天终于现身了。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现身了", "label": "体标"}, {"form": "现身过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或东西从看不见的地方出来，让大家看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，不用来说人在舞台上。"}, {"text": "现身", "is_correct": true, "explanation": "“现身”指人或东西从隐蔽处出来、被大家看见，与“突然”和魔术的情境相合。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”多用于墙、房屋等建筑，不用于魔术师本人。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或灯光灭掉，不能用来说人。"}], "explanations": {"融化": "语义：“融化”指固体遇热变成液体，不用来说人在舞台上。", "现身": "“现身”指人或东西从隐蔽处出来、被大家看见，与“突然”和魔术的情境相合。", "倒塌": "搭配：“倒塌”多用于墙、房屋等建筑，不用于魔术师本人。", "熄灭": "语义：“熄灭”指火或灯光灭掉，不能用来说人。"}, "sentence_index": 0, "correct_answer": "现身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题突然现身了。", "explanation": "这里应该用〈出现〉。现身指人或动物从隐蔽处露面，“问题”是抽象的事，不能现身。"}, {"text": "昨天一个好消息现身了。", "explanation": "这里应该用〈传来〉。现身指人或动物从隐蔽处露面，“消息”看不见、摸不着，不能现身，应说“传来”。"}, {"text": "一个好主意从他脑中现身了。", "explanation": "这里应该用〈冒出〉。念头不能现身，应说“冒出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”指食物或植物变质，不能用于歌手。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变成固体，不能用于人。"}, {"text": "现身", "is_correct": true, "explanation": "“现身”指歌手从台下露面出场，与“演出开始时”相合。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多用于资金、账户、水等，不用于人从台下出来。"}], "explanations": {"腐烂": "语义：“腐烂”指食物或植物变质，不能用于歌手。", "凝固": "语义：“凝固”指液体变成固体，不能用于人。", "现身": "“现身”指歌手从台下露面出场，与“演出开始时”相合。", "冻结": "搭配：“冻结”多用于资金、账户、水等，不用于人从台下出来。"}, "sentence_index": 6, "correct_answer": "现身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事故昨天终于现身了。", "explanation": "这里应该用〈发生〉。现身指有形体的人或动物从隐蔽处露面，事故不能现身。"}, {"text": "他的人生目标今天终于现身了。", "explanation": "这里应该用〈明确〉。现身指人或动物从隐蔽处露面，目标不能现身，应说“明确”。"}, {"text": "这个数字今天终于现身了。", "explanation": "这里应该用〈公布〉。现身指人或动物从隐蔽处露面，数字不能现身，应说“公布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演员终于从幕后现身着。", "corrected_sentence": "演员终于从幕后现身了。", "error_description": "错误在于把表示完成的“了”误写成“着”。“终于”表示经过等待后完成，现身是完成的动作，应用“了”，说“从幕后现身了”，不能说“现身着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位明星在后台等了很久，最后很现身。", "corrected_sentence": "那位明星在后台等了很久，最后才现身。", "error_description": "“很”是程度副词，不能修饰“现身”这类动作动词。这里应该用表示时间的“才”，说“最后才现身”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
