INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出现在人前；露面。", "primary_collocate": null, "pronunciation": "xiàn shēn", "ipa": "ɕjɛn˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这位明星昨天在发布会现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛那天，市长也在现场现身了。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病很久，今天第一次公开现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们在机场等着，球星终于现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影首映礼上，导演现身讲话。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老歌手多年不见，最近在电视上现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，公司经理没有现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想看他，可他一直不现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位作家在书店现身，签了很多书。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他今晚会在学校现身。", "target_word": "现身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现身了", "label": "体标"}, {"form": "现身过", "label": "体标"}], "register": "中性", "sense_fingerprint": "名人或重要人物在公开场合露面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凋谢", "is_correct": false, "explanation": "语义：“凋谢”多指花朵枯萎落下，不用于明星。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属表面氧化，不能用于人。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多用于资金、账户、水等，不用于明星在发布会上的行为。"}, {"text": "现身", "is_correct": true, "explanation": "“现身”指名人在公开场合露面，与“发布会”和“昨天”相合。"}], "explanations": {"凋谢": "语义：“凋谢”多指花朵枯萎落下，不用于明星。", "生锈": "语义：“生锈”指金属表面氧化，不能用于人。", "冻结": "搭配：“冻结”多用于资金、账户、水等，不用于明星在发布会上的行为。", "现身": "“现身”指名人在公开场合露面，与“发布会”和“昨天”相合。"}, "sentence_index": 0, "correct_answer": "现身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个难题终于现身了。", "explanation": "这里应该用〈解决〉。现身指名人或重要人物在公开场合露面，“难题”不能现身，应说“解决”。"}, {"text": "一场突如其来的大雨在城市上空现身了。", "explanation": "这里应该用〈出现〉。现身指名人在公开场合露面，大雨不能现身，应说“出现”。"}, {"text": "一丝笑容在她脸上现身了。", "explanation": "这里应该用〈浮现〉。笑容不能现身，应说“浮现”在脸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，不能用于人。"}, {"text": "枯萎", "is_correct": false, "explanation": "语义：“枯萎”指植物失去水分变干，不能用于经理。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”多用于火、灯光，不说人熄灭。"}, {"text": "现身", "is_correct": true, "explanation": "“现身”指人在公开场合露面，“没有现身”说经理没有出席会议。"}], "explanations": {"融化": "语义：“融化”指固体遇热变成液体，不能用于人。", "枯萎": "语义：“枯萎”指植物失去水分变干，不能用于经理。", "熄灭": "搭配：“熄灭”多用于火、灯光，不说人熄灭。", "现身": "“现身”指人在公开场合露面，“没有现身”说经理没有出席会议。"}, "sentence_index": 6, "correct_answer": "现身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法昨天终于现身了。", "explanation": "这里应该用〈想出〉。现身指名人在公开场合露面，办法不能现身，应说“想出”。"}, {"text": "这个误会昨天终于现身了。", "explanation": "这里应该用〈解开〉。现身指名人在公开场合露面，误会不能现身，应说“解开”。"}, {"text": "这份友谊昨晚终于现身了。", "explanation": "这里应该用〈建立〉。现身指名人在公开场合露面，友谊不能现身，应说“建立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "导演终于在台上现身着。", "corrected_sentence": "导演终于在台上现身了。", "error_description": "错误在于把表示完成的“了”误写成“着”。“终于”表示经过等待后完成，应说“在台上现身了”，不能说“现身着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天会在学校现身了，大家都很期待。", "corrected_sentence": "他明天会在学校现身，大家都很期待。", "error_description": "错误在于把表示完成的“了”用在将来的动作上。句中有“明天会”，“现身”后不能带“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
