INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92393, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "某种是说有一种，但是不说清楚是哪种。", "primary_collocate": null, "pronunciation": "mǒu zhǒng", "ipa": "mou˨˩˦ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我觉得他心里有某种想法，只是没有告诉我们。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天没来上班，可能是因为某种原因。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯茶里有某种花的香味，我说不出是哪种花。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在门外叫，好像听到了某种声音。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次紧张，都会用某种方式让自己安静下来。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里放着某种机器，不知道有什么用。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在某种意义上，语言就是文化的一部分。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着窗外，好像在等某种消息。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说山里住着某种大鸟，可是没有人见过。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子好像都有某种共同的爱好。", "target_word": "某种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "某種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某种：有一种，但不说清楚是哪一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某种", "is_correct": true, "explanation": "某种：指说不清或不必说明是哪一种想法，与句中“只是没有告诉我们”相合。"}, {"text": "哪种", "is_correct": false, "explanation": "语义：「哪种」问的是“是哪一种”，用于疑问或任指；句中是陈述，不能说“有哪种想法”。"}, {"text": "每种", "is_correct": false, "explanation": "语义：「每种」指全部种类，而句中说的是心里有一种想法、只是没说清，两者不符。"}, {"text": "任何", "is_correct": false, "explanation": "搭配：「任何」用于肯定陈述时要与「都」「也」或否定词一起用，单说“有任何想法”语气不完整。"}], "explanations": {"某种": "某种：指说不清或不必说明是哪一种想法，与句中“只是没有告诉我们”相合。", "哪种": "语义：「哪种」问的是“是哪一种”，用于疑问或任指；句中是陈述，不能说“有哪种想法”。", "每种": "语义：「每种」指全部种类，而句中说的是心里有一种想法、只是没说清，两者不符。", "任何": "搭配：「任何」用于肯定陈述时要与「都」「也」或否定词一起用，单说“有任何想法”语气不完整。"}, "sentence_index": 0, "correct_answer": "某种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们下周要学这某种语言，就是汉语。", "explanation": "这里不该用「某种」。「某种」不能和指示词「这」连用；说话人能指明的语言，要用「这种」或直接说「汉语」。"}, {"text": "他在某种天突然来到我家，我很惊讶。", "explanation": "这里应该用〈某一天〉。「某种」指一类，不用来指一个具体的时间；说具体的哪一天要用「某一天」。"}, {"text": "我有某种三本书，都是中文的。", "explanation": "这里不该用「某种」。「某种」表示不确定的一类，不能和具体数量连用；说明数量直接用数词加量词即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某种", "is_correct": true, "explanation": "某种：指说不清或不必说明是哪一种意义，与“在……意义上”搭配自然。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」问的是“是哪几种”，用于疑问或任指；句中是陈述，不能说“在哪些意义上，语言就是文化的一部分”。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：「每个」强调逐一、个个都要，「在每个意义上」不这样说。"}, {"text": "各个", "is_correct": false, "explanation": "搭配：「各个」多用于“各个方面”“各个地方”，与「意义」搭配不自然，「在各个意义上」不说。"}], "explanations": {"某种": "某种：指说不清或不必说明是哪一种意义，与“在……意义上”搭配自然。", "哪些": "语义：「哪些」问的是“是哪几种”，用于疑问或任指；句中是陈述，不能说“在哪些意义上，语言就是文化的一部分”。", "每个": "搭配：「每个」强调逐一、个个都要，「在每个意义上」不这样说。", "各个": "搭配：「各个」多用于“各个方面”“各个地方”，与「意义」搭配不自然，「在各个意义上」不说。"}, "sentence_index": 6, "correct_answer": "某种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书里，某种书都很有用，大家都可以看。", "explanation": "这里应该用〈每种〉。「某种」表示不确定的一种，不能指全部；说“每一种都”要用「每种」。"}, {"text": "我昨天买了一本书，很有用。某种书我还想再买一本。", "explanation": "这里不该用「某种」。「某种」表示说不清或不必说明是哪一种；前文提到的那本书是具体所指，再指它要用「这本」或「这种」。"}, {"text": "我在路上遇到了某种同学，我正要跟他说话，他却走了。", "explanation": "这里应该用〈某个〉。「某种」指一类，不指一个具体的人；指某一个人要用「某个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她看见窗外有某种只鸟，但是叫不出名字。", "corrected_sentence": "她看见窗外有某种鸟，但是叫不出名字。", "error_description": "「某种」直接修饰名词，中间不能加量词「只」。错误写法「某种只鸟」应改为「某种鸟」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他好像在等某种的答案，一直不说话。", "corrected_sentence": "他好像在等某种答案，一直不说话。", "error_description": "「某种」后面不加「的」。「某种答案」是对的，「某种的答案」是错误的，因为「某种」直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
