INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92395, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走在前面，带着大家一起走。", "primary_collocate": null, "pronunciation": "shuài lǐng", "ipa": "ʂwai˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师率领同学们走进博物馆。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长率领大家走上山路。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游率领着游客走过小桥。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他率领孩子们走在队伍最前面。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长率领大家走出了大山。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师率领一群学生去公园参观。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他率领我们走到河边休息。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练率领队员们走回营地。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领队率领大家走进了树林。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨中，他率领同学们走向车站。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "率领了", "label": "体标（了）"}, {"form": "率领着", "label": "体标（着）"}, {"form": "率领过", "label": "体标（过）"}, {"form": "率領", "label": "繁体"}], "register": "书面", "sense_fingerprint": "走在最前面，带着大家一起行进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解散", "is_correct": false, "explanation": "语义：「解散」是让人群各自离开，与「一起走进博物馆」的同行动作矛盾。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车、船等交通工具，不能说驾驶同学们。"}, {"text": "率领", "is_correct": true, "explanation": "「率领」指带领一群人走在前面，与「老师率领同学们走进博物馆」相符。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：「驱散」是把人赶散，与「走进博物馆」的集体行动相反。"}], "explanations": {"解散": "语义：「解散」是让人群各自离开，与「一起走进博物馆」的同行动作矛盾。", "驾驶": "搭配：「驾驶」的对象是车、船等交通工具，不能说驾驶同学们。", "率领": "「率领」指带领一群人走在前面，与「老师率领同学们走进博物馆」相符。", "驱散": "语义：「驱散」是把人赶散，与「走进博物馆」的集体行动相反。"}, "sentence_index": 0, "correct_answer": "率领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她率领妹妹走在街上。", "explanation": "这里应该用〈牵〉。率领指带领一群人走在前面，牵着一个小妹妹走路应说「牵」。"}, {"text": "他率领一位老奶奶走进了医院。", "explanation": "这里应该用〈搀〉。率领指统率一群人前行，搀扶一位老奶奶走路应说「搀」。"}, {"text": "学生率领椅子走进教室。", "explanation": "这里应该用〈搬〉。率领的对象必须是人，搬着椅子走进教室应说「搬」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收留", "is_correct": false, "explanation": "语义：「收留」是接纳无处可去的人住下，与「走到河边休息」的行走动作矛盾。"}, {"text": "举起", "is_correct": false, "explanation": "搭配：「举起」的对象多是物体，不能说举起人并带着他们走到河边。"}, {"text": "率领", "is_correct": true, "explanation": "「率领」指带领一群人走在前面，与「走到河边休息」的行进路线一致。"}, {"text": "埋葬", "is_correct": false, "explanation": "语义：「埋葬」是把尸体入土，与活人一起走到河边休息的句意完全不符。"}], "explanations": {"收留": "语义：「收留」是接纳无处可去的人住下，与「走到河边休息」的行走动作矛盾。", "举起": "搭配：「举起」的对象多是物体，不能说举起人并带着他们走到河边。", "率领": "「率领」指带领一群人走在前面，与「走到河边休息」的行进路线一致。", "埋葬": "语义：「埋葬」是把尸体入土，与活人一起走到河边休息的句意完全不符。"}, "sentence_index": 6, "correct_answer": "率领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我率领小狗去公园散步。", "explanation": "这里应该用〈带〉。率领指统率一群人前行，带小狗去公园只说「带」。"}, {"text": "我率领外婆去超市买东西。", "explanation": "这里应该用〈陪〉。率领的对象是队伍，陪外婆买东西应说「陪」。"}, {"text": "车队率领这批货物到了港口。", "explanation": "这里应该用〈护送〉。率领的对象必须是人员或队伍，运送货物应说「护送」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长率领了着同学们走出了校门。", "corrected_sentence": "班长率领着同学们走出了校门。", "error_description": "错误：同一动词「率领」后不能同时带「了」和「着」。这里表示动作持续，应只用「着」，说「率领着同学们」，不说「率领了着同学们」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队长很率领队员们回到了营地。", "corrected_sentence": "队长率领队员们回到了营地。", "error_description": "错误：「率领」前面多加了程度副词「很」。「很」一般不修饰这类动作动词，应说「队长率领队员们」，不说「队长很率领队员们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
