INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带领；统率。", "primary_collocate": null, "pronunciation": "shuài lǐng", "ipa": "ʂwai˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "将军率领部队进入了城里。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他率领公司走过了最难的一年。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练率领球队拿到了冠军。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长率领代表团访问了日本。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理率领二十人的团队完成了任务。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她率领研究小组做出了新发现。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王率领军队打败了敌人。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长率领全体船员渡过了难关。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他率领着年轻的队伍走向成功。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂长率领工人们提前完成了生产任务。", "target_word": "率领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "率领了", "label": "体标（了）"}, {"form": "率领着", "label": "体标（着）"}, {"form": "率领过", "label": "体标（过）"}, {"form": "率領", "label": "繁体"}], "register": "书面", "sense_fingerprint": "带领并统率一支队伍或团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢送", "is_correct": false, "explanation": "语义：「欢送」是送别离开的人，与「部队进入了城里」的方向相反，句子自相矛盾。"}, {"text": "率领", "is_correct": true, "explanation": "「率领」指带领并统率队伍，与「将军」和「部队」搭配，表示将军带部队进城，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是场地或卫生，不能说打扫部队。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：「驱散」是使人群四处散去，与「进入了城里」的行动矛盾。"}], "explanations": {"欢送": "语义：「欢送」是送别离开的人，与「部队进入了城里」的方向相反，句子自相矛盾。", "率领": "「率领」指带领并统率队伍，与「将军」和「部队」搭配，表示将军带部队进城，符合句意。", "打扫": "搭配：「打扫」的对象是场地或卫生，不能说打扫部队。", "驱散": "语义：「驱散」是使人群四处散去，与「进入了城里」的行动矛盾。"}, "sentence_index": 0, "correct_answer": "率领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车队率领这批文件到了机场。", "explanation": "这里应该用〈护送〉。率领的对象必须是人员或队伍，运送文件应说「护送」。"}, {"text": "我率领小猫去医院看病。", "explanation": "这里应该用〈带〉。率领指统率一群人，带宠物去医院只说「带」。"}, {"text": "工人率领行李走出了车站。", "explanation": "这里应该用〈搬〉。率领不能用于行李，搬着行李走出车站应说「搬」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解雇", "is_correct": false, "explanation": "搭配：「解雇」针对受雇的人员，不能说解雇军队。"}, {"text": "救助", "is_correct": false, "explanation": "语义：「救助」是帮助遭遇危难的人，与「打败了敌人」的胜利情节不符。"}, {"text": "率领", "is_correct": true, "explanation": "「率领」指统率军队，与「国王」和「打败了敌人」的句意一致。"}, {"text": "屠杀", "is_correct": false, "explanation": "语义：「屠杀」是残害生灵，与国王统率军队作战的行动矛盾，句意不通。"}], "explanations": {"解雇": "搭配：「解雇」针对受雇的人员，不能说解雇军队。", "救助": "语义：「救助」是帮助遭遇危难的人，与「打败了敌人」的胜利情节不符。", "率领": "「率领」指统率军队，与「国王」和「打败了敌人」的句意一致。", "屠杀": "语义：「屠杀」是残害生灵，与国王统率军队作战的行动矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "率领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她率领朋友去机场了。", "explanation": "这里应该用〈送〉。率领指统率一群人前行，送朋友去机场应说「送」。"}, {"text": "我率领奶奶去公园散步。", "explanation": "这里应该用〈陪〉。率领要求统率一群人，陪长辈散步应说「陪」。"}, {"text": "妈妈率领一个小男孩过马路。", "explanation": "这里应该用〈牵〉。率领指统率一群人前行，牵着一个小男孩过马路应说「牵」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她率领了着团队走出了困境。", "corrected_sentence": "她率领着团队走出了困境。", "error_description": "错误：同一动词「率领」后不能同时带「了」和「着」。这里表示动作正在进行，应只用「着」，说「率领着团队」，不说「率领了着团队」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板很率领员工拿下了这份订单。", "corrected_sentence": "老板率领员工拿下了这份订单。", "error_description": "错误：「率领」前面多加了程度副词「很」。「很」一般不修饰这类动作动词，应说「老板率领员工」，不说「老板很率领员工」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
