INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92397, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用不了是不能用，或者用不完。", "primary_collocate": null, "pronunciation": "yòng bu liǎo", "ipa": "jʊŋ˥˩ pu liɑʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个插头太小，在这里用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有很多钱，一辈子都用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "笔坏了，写不出字，用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些菜油太多，我们半年也用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左手受伤了，现在用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给的练习本太多，我用不了这么多。", "target_word": "用不了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有密码，这台电脑用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张优惠券过期了，用不了了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你给我的纸太多，我用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子裂了，不能装水，用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用得了", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "不能用，或数量太多用不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用得了", "is_correct": false, "explanation": "语义：“用得了”说能用，与“插头太小”矛盾。"}, {"text": "用不了", "is_correct": true, "explanation": "“用不了”指不能使用，与“插头太小”相符。"}, {"text": "用不起", "is_correct": false, "explanation": "语义：“用不起”指没钱用，与插头的大小无关。"}, {"text": "用上了", "is_correct": false, "explanation": "体貌：“用上了”表示已经开始使用，与“在这里”的情况不符。"}], "explanations": {"用得了": "语义：“用得了”说能用，与“插头太小”矛盾。", "用不了": "“用不了”指不能使用，与“插头太小”相符。", "用不起": "语义：“用不起”指没钱用，与插头的大小无关。", "用上了": "体貌：“用上了”表示已经开始使用，与“在这里”的情况不符。"}, "sentence_index": 0, "correct_answer": "用不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌太难，我用不了。", "explanation": "这里应该用〈唱不了〉。用不了指物品、设备不能用或用不完，歌太难唱要用〈唱不了〉。"}, {"text": "这辆自行车太贵，我们用不了。", "explanation": "这里应该用〈用不起〉。用不了指物品不能用，表示买不起、负担不起要用〈用不起〉。"}, {"text": "这篇文章很长，我用不了。", "explanation": "这里应该用〈读不完〉。用不了指物品、设备能否使用或用不完，文章的长短要用〈读不完〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用不完", "is_correct": false, "explanation": "语义：“用不完”指数量多，与“没有密码”无关。"}, {"text": "用不了", "is_correct": true, "explanation": "“用不了”指不能使用，与“没有密码”相符。"}, {"text": "骑不了", "is_correct": false, "explanation": "搭配：“骑”只用于自行车等交通工具，不能用于电脑。"}, {"text": "穿不了", "is_correct": false, "explanation": "搭配：“穿”不能用于电脑，句子不成立。"}], "explanations": {"用不完": "语义：“用不完”指数量多，与“没有密码”无关。", "用不了": "“用不了”指不能使用，与“没有密码”相符。", "骑不了": "搭配：“骑”只用于自行车等交通工具，不能用于电脑。", "穿不了": "搭配：“穿”不能用于电脑，句子不成立。"}, "sentence_index": 6, "correct_answer": "用不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些作业太多，我一晚上用不了。", "explanation": "这里应该用〈写不完〉。用不了用于物品，不用于作业，表示写不完时要用〈写不完〉。"}, {"text": "这瓶饮料很好喝，我用不了。", "explanation": "这里应该用〈喜欢〉。用不了指能否使用或用不完，不能表达对味道的喜爱，要用〈喜欢〉。"}, {"text": "这件事很简单，我用不了。", "explanation": "这里应该用〈会做〉。用不了用于工具和物品，不用于事情，表示会不会做时要用〈会做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把剪刀太钝，我了用不了。", "corrected_sentence": "这把剪刀太钝，我用不了。", "error_description": "错误：“我了用不了”，“了”放在了动词“用”的前面。正确：“我用不了”。“用不了”是可能补语的否定形式，“了”不能插在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把钥匙断了，现在不用不了。", "corrected_sentence": "这把钥匙断了，现在用不了。", "error_description": "错误：“不用不了”，“用不了”前多加了一个“不”，形成双重否定，意思颠倒。正确：“用不了”，表示不能使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
