INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不能使用；也指用不完。", "primary_collocate": null, "pronunciation": "yòng bu liǎo", "ipa": "jʊŋ˥˩ pu liɑʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "手机没电了，现在用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑太旧，很多软件都用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的卡过期了，在这里用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多米，我们一个月也用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水龙头坏了，热水用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你买得太多，这些纸一年也用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把钥匙用不了，门打不开。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国外的网站在这里用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一大瓶盐，我们一年也用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有网，这个应用用不了。", "target_word": "用不了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用得了", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "东西无法使用，或数量多得用不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用得了", "is_correct": false, "explanation": "语义：“用得了”说能用，与“没电了”矛盾。"}, {"text": "用不了", "is_correct": true, "explanation": "“用不了”指不能使用，与“没电了”相符。"}, {"text": "用不起", "is_correct": false, "explanation": "语义：“用不起”指没钱用，与“没电”无关。"}, {"text": "用上了", "is_correct": false, "explanation": "体貌：“用上了”表示已经开始使用，与“现在”的状态不符。"}], "explanations": {"用得了": "语义：“用得了”说能用，与“没电了”矛盾。", "用不了": "“用不了”指不能使用，与“没电了”相符。", "用不起": "语义：“用不起”指没钱用，与“没电”无关。", "用上了": "体貌：“用上了”表示已经开始使用，与“现在”的状态不符。"}, "sentence_index": 0, "correct_answer": "用不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗太长，我用不了。", "explanation": "这里应该用〈背不了〉。用不了指物品、设备不能用或用不完，诗太长记不住要用〈背不了〉。"}, {"text": "这台电脑太贵，我们用不了。", "explanation": "这里应该用〈用不起〉。用不了指物品不能用，表示买不起、负担不起要用〈用不起〉。"}, {"text": "这部电影很长，我用不了。", "explanation": "这里应该用〈看不完〉。用不了指物品、设备能否使用或用不完，电影的长短要用〈看不完〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用不完", "is_correct": false, "explanation": "语义：“用不完”指数量多，与“钥匙”和“门打不开”的情况不符。"}, {"text": "用不了", "is_correct": true, "explanation": "“用不了”指不能使用，与“门打不开”相符。"}, {"text": "吃不了", "is_correct": false, "explanation": "搭配：“吃”不能用于钥匙，句子不成立。"}, {"text": "穿不了", "is_correct": false, "explanation": "搭配：“穿”不能用于钥匙，句子不成立。"}], "explanations": {"用不完": "语义：“用不完”指数量多，与“钥匙”和“门打不开”的情况不符。", "用不了": "“用不了”指不能使用，与“门打不开”相符。", "吃不了": "搭配：“吃”不能用于钥匙，句子不成立。", "穿不了": "搭配：“穿”不能用于钥匙，句子不成立。"}, "sentence_index": 6, "correct_answer": "用不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题太难，我用不了。", "explanation": "这里应该用〈做不了〉。用不了用于物品或工具，不用于题目，题太难要用〈做不了〉。"}, {"text": "这个问题很简单，我用不了。", "explanation": "这里应该用〈会做〉。用不了用于物品或工具，不用于问题，表示会不会做时要用〈会做〉。"}, {"text": "这个苹果很甜，我用不了。", "explanation": "这里应该用〈喜欢〉。用不了指能否使用或用不完，不能表达对味道的喜爱，要用〈喜欢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件太旧，我用不了过。", "corrected_sentence": "这个软件太旧，我用不了。", "error_description": "错误：“用不了”后面加了“过”。“用不了”是可能补语的否定形式，表示不能用，后面不能再加表示经历的“过”。正确：“这个软件太旧，我用不了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个程序在我的电脑上很用不了。", "corrected_sentence": "这个程序在我的电脑上用不了。", "error_description": "错误：“很用不了”。“用不了”是可能补语的否定形式，表示不能使用，前面不能加程度副词“很”。正确：“这个程序在我的电脑上用不了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "极为是非常非常。", "primary_collocate": null, "pronunciation": "jí wéi", "ipa": "tɕi˧˥ wei˧˥", "syllable_count": 2, "sentences": [{"text": "这件事对我们极为重要。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚极为安静。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟在城市里极为少见。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平极为出色。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的题目极为简单。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天在山上开车极为危险。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对老人的态度极为有礼貌。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的风景极为美丽。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的生活条件极为困难。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到这个消息后极为高兴。", "target_word": "极为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，放在形容词前，表示程度非常高，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极为", "is_correct": true, "explanation": "“极为”表示程度非常高，修饰形容词“重要”，句意是这件事对我们非常重要，符合语境。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作或状态正在进行，不能修饰“重要”这类表示性质的形容词。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间刚过去，与句中对事情性质的判断不相符。"}, {"text": "必须", "is_correct": false, "explanation": "搭配：“必须”表示必要或需要，多修饰动作，一般不直接修饰“重要”这样的形容词。"}], "explanations": {"极为": "“极为”表示程度非常高，修饰形容词“重要”，句意是这件事对我们非常重要，符合语境。", "正在": "语义：“正在”表示动作或状态正在进行，不能修饰“重要”这类表示性质的形容词。", "刚刚": "语义：“刚刚”表示时间刚过去，与句中对事情性质的判断不相符。", "必须": "搭配：“必须”表示必要或需要，多修饰动作，一般不直接修饰“重要”这样的形容词。"}, "sentence_index": 0, "correct_answer": "极为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他极为放弃了这次比赛。", "explanation": "这里应该用〈彻底〉。〈极为〉表示程度极高，不能修饰“放弃”这种一次性的动作；“彻底放弃”才自然。"}, {"text": "他极为是我的老师。", "explanation": "〈极为〉修饰形容词，表示程度高，不能修饰判断动词“是”。"}, {"text": "这个数字极为偶数，我很喜欢。", "explanation": "这里应该去掉〈极为〉。〈偶数〉是非此即彼的类别词，没有程度之分，不能用〈极为〉修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极为", "is_correct": true, "explanation": "“极为”修饰“有礼貌”，表示她对老人的态度非常有礼貌，符合句意。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间很快发生，与描述态度性质的“礼貌”不相容。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”修饰急切的动作，不能修饰“礼貌”这样描述态度的形容词。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”多修饰动作的发生，不能与形容词“礼貌”搭配。"}], "explanations": {"极为": "“极为”修饰“有礼貌”，表示她对老人的态度非常有礼貌，符合句意。", "马上": "语义：“马上”表示时间很快发生，与描述态度性质的“礼貌”不相容。", "连忙": "搭配：“连忙”修饰急切的动作，不能修饰“礼貌”这样描述态度的形容词。", "立即": "搭配：“立即”多修饰动作的发生，不能与形容词“礼貌”搭配。"}, "sentence_index": 6, "correct_answer": "极为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他极为会唱歌。", "explanation": "这里应该用〈很〉。〈极为〉表示程度极高，修饰能愿动词“会”时一般说“很会”，学习者易混淆。"}, {"text": "我极为到了北京。", "explanation": "〈极为〉表示程度高，不能修饰“到”这种没有程度之分的动作。"}, {"text": "他极为学习汉语。", "explanation": "这里应该用〈努力〉。〈极为〉修饰的是程度，不能修饰“学习”这种动作本身，应说“极为努力地学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行对我们极为的有意义。", "corrected_sentence": "这次旅行对我们极为有意义。", "error_description": "错误形式是“极为的有意义”，正确形式是“极为有意义”。“极为”后面直接接形容词或形容词性短语，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的表现极为很出色。", "corrected_sentence": "他的表现极为出色。", "error_description": "错误形式是“极为很出色”，正确形式是“极为出色”。“极为”和“很”都是程度副词，修饰形容词时不能叠用，只用其一。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
