INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92401, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一步一步走到上面。", "primary_collocate": null, "pronunciation": "dēng shàng", "ipa": "təŋ⁵⁵ ʂɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "他一步一步登上了长长的石阶。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢登上台阶，走进了小庙。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬了一个小时，终于登上了山顶。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地登上楼顶看星星。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她扶着栏杆，一步一步登上楼梯。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登上最后一级台阶，他累得说不出话。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没登上过这么高的塔。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸背着包，慢慢登上了小山。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一个跟着一个登上了山坡。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要登上那座桥，得先走完这些台阶。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登上了", "label": "体标（了）"}, {"form": "登上过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "沿着台阶等一步一步走到上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借走", "is_correct": false, "explanation": "语义：石阶固定在地上，不能被“借走”，“一步一步借走石阶”句意不通。"}, {"text": "登上", "is_correct": true, "explanation": "正确：“一步一步登上”指沿台阶慢慢走到上面，与“长长的石阶”相符。"}, {"text": "脱下", "is_correct": false, "explanation": "搭配：“脱下”接衣服、鞋帽，不能接石阶。"}, {"text": "飞上", "is_correct": false, "explanation": "语义：石阶不能飞上去，“一步一步”也与“飞”矛盾。"}], "explanations": {"借走": "语义：石阶固定在地上，不能被“借走”，“一步一步借走石阶”句意不通。", "登上": "正确：“一步一步登上”指沿台阶慢慢走到上面，与“长长的石阶”相符。", "脱下": "搭配：“脱下”接衣服、鞋帽，不能接石阶。", "飞上": "语义：石阶不能飞上去，“一步一步”也与“飞”矛盾。"}, "sentence_index": 0, "correct_answer": "登上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他登上平坦的马路，慢慢往家走。", "explanation": "这里应该用〈走上〉。“登上”强调往高处一步步走，平坦的马路没有高低，不能用“登上”。"}, {"text": "他登上了大厅，找到了服务台。", "explanation": "这里应该用〈走进〉。“登上”强调往高处一步步走，大厅是平地，不能说“登上大厅”。"}, {"text": "他登上了房间，关上了门。", "explanation": "这里应该用〈走进〉。“登上”指往高处走到上面，从外面进入房间不能用“登上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游上", "is_correct": false, "explanation": "语义：“游”是在水中活动，塔不能用“游上”。"}, {"text": "登上", "is_correct": true, "explanation": "正确：“我从没登上过这么高的塔”指攀登到塔的高处，与“这么高”相符。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”接衣服、鞋帽，不接塔，句意不通。"}, {"text": "放下", "is_correct": false, "explanation": "语义：“放下”指把能拿动的东西放低，塔无法被放下。"}], "explanations": {"游上": "语义：“游”是在水中活动，塔不能用“游上”。", "登上": "正确：“我从没登上过这么高的塔”指攀登到塔的高处，与“这么高”相符。", "穿上": "搭配：“穿上”接衣服、鞋帽，不接塔，句意不通。", "放下": "语义：“放下”指把能拿动的东西放低，塔无法被放下。"}, "sentence_index": 6, "correct_answer": "登上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们登上操场，急急忙忙去教室拿书。", "explanation": "这里应该用〈跑进〉。操场是平地，没有高处可以“登上”，进入操场应说“跑进”。"}, {"text": "我们登上一条小河，继续往前走。", "explanation": "这里应该用〈跨过〉。小河是低处，没有可以攀登的高处，不能说“登上一条小河”，应说“跨过”。"}, {"text": "他登上了平原，走到河边。", "explanation": "这里应该用〈穿过〉。平原是平地，没有高处，不能说“登上平原”，应说“穿过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她小时候曾经登上着一座雪山。", "corrected_sentence": "她小时候曾经登上过一座雪山。", "error_description": "体标用错。“曾经”表示经历，应接“登上过”，“着”表示动作持续，不能说“登上着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她花了三天，终于登上的那座雪山。", "corrected_sentence": "她花了三天，终于登上了那座雪山。", "error_description": "“了”写成了“的”，“登上的那座雪山”缺少谓语，应说“终于登上了那座雪山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
