INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走上去；攀登到高处。", "primary_collocate": null, "pronunciation": "dēng shàng", "ipa": "təŋ⁵⁵ ʂɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "周末我们打算登上泰山看日出。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次登上长城，高兴极了。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天不亮，爬山的人就登上了山顶。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她登上高高的城墙，看见了远处的河。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登上这座塔，可以看到整个城市。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了三天才登上那座雪山。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时登上过很多有名的山。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们登上山顶，拍了一张照片。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要登上高山，先得准备好水和鞋。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登上山顶以后，大家坐下来休息。", "target_word": "登上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登上了", "label": "体标（了）"}, {"form": "登上过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "攀登到山、塔、城墙等高处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘坐", "is_correct": false, "explanation": "搭配：“乘坐”接车、船等交通工具，不能接山。"}, {"text": "登上", "is_correct": true, "explanation": "正确：“登上泰山”指攀登到山顶，与“看日出”相符。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开泰山”与“看日出”的目的相反，句意不通。"}, {"text": "告别", "is_correct": false, "explanation": "语义：“告别泰山”是离开的意思，与“打算看日出”冲突。"}], "explanations": {"乘坐": "搭配：“乘坐”接车、船等交通工具，不能接山。", "登上": "正确：“登上泰山”指攀登到山顶，与“看日出”相符。", "离开": "语义：“离开泰山”与“看日出”的目的相反，句意不通。", "告别": "语义：“告别泰山”是离开的意思，与“打算看日出”冲突。"}, "sentence_index": 0, "correct_answer": "登上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她登上广场，买了一束花。", "explanation": "这里应该用〈路过〉。广场是平地，没有高处可登，不能用“登上”。"}, {"text": "她登上了办公室，坐下来开始工作。", "explanation": "这里应该用〈走进〉。“登上”指往高处走到上面，办公室是平地，不能说“登上办公室”，应说“走进”。"}, {"text": "我们登上山脚，走向河边。", "explanation": "这里应该用〈绕过〉。山脚在低处，不是需要攀登的高处，不能说“登上山脚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：山上不能游泳，“游泳过很多有名的山”句意不通。"}, {"text": "登上", "is_correct": true, "explanation": "正确：“爷爷年轻时登上过很多有名的山”指攀登过许多山的高处，与句意相符。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：山不能被打碎，“打碎过很多有名的山”句意不通。"}, {"text": "放飞", "is_correct": false, "explanation": "语义：“放飞”指放走鸟类、飞行物，不能用在山上。"}], "explanations": {"游泳": "语义：山上不能游泳，“游泳过很多有名的山”句意不通。", "登上": "正确：“爷爷年轻时登上过很多有名的山”指攀登过许多山的高处，与句意相符。", "打碎": "语义：山不能被打碎，“打碎过很多有名的山”句意不通。", "放飞": "语义：“放飞”指放走鸟类、飞行物，不能用在山上。"}, "sentence_index": 6, "correct_answer": "登上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他游过了宽阔的湖，终于登上了湖面。", "explanation": "这里应该用〈游到〉。湖面是水面，没有高处，不能说“登上湖面”，应说“游到”。"}, {"text": "这条小船登上宽阔的江面。", "explanation": "这里应该用〈驶过〉。船在水面行驶，江面没有高处，不能用“登上”。"}, {"text": "我们登上一道水沟，继续往前走。", "explanation": "这里应该用〈跨过〉。水沟是低处，要说“跨过”，不能说“登上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于登上的古城墙。", "corrected_sentence": "他们终于登上了古城墙。", "error_description": "“了”写成了“的”，“登上的古城墙”缺少谓语，应说“终于登上了古城墙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们还没登上了那座雪山。", "corrected_sentence": "他们还没登上那座雪山。", "error_description": "“还没”后不能再加“了”。否定句中要说“还没登上”，不能说“还没登上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
