INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "精神失常的人。", "primary_collocate": null, "pronunciation": "fēng zi", "ipa": "fɤŋ˥ tsɿ", "syllable_count": 2, "sentences": [{"text": "医生说他不是疯子，只是太累了。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个疯子需要住院治疗。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人叫他疯子，他很难过。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她照顾着一个疯子。", "target_word": "疯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个疯子不认识自己的家人。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前村里有一个疯子。", "target_word": "疯子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "疯子有时会听不懂别人的话。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个疯子见人就笑。", "target_word": "疯子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的邻居是个可怜的疯子。", "target_word": "疯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里住着一些疯子。", "target_word": "疯子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "瘋子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疯子：精神失常的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92404, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疯子", "is_correct": true, "explanation": "疯子（fēng zi）：精神失常的人，是正确答案。"}, {"text": "分子", "is_correct": false, "explanation": "fēn（第一声）与 fēng 的韵母不同：n 与 ng 不同，意思是分子。"}, {"text": "方子", "is_correct": false, "explanation": "fāng（第一声）与 fēng 的韵母不同：ang 与 eng 不同，意思是药方。"}, {"text": "风姿", "is_correct": false, "explanation": "第二音节 zī（第一声）与 zi（轻声）声调不同，意思是优美的姿态。"}], "explanations": {"疯子": "疯子（fēng zi）：精神失常的人，是正确答案。", "分子": "fēn（第一声）与 fēng 的韵母不同：n 与 ng 不同，意思是分子。", "方子": "fāng（第一声）与 fēng 的韵母不同：ang 与 eng 不同，意思是药方。", "风姿": "第二音节 zī（第一声）与 zi（轻声）声调不同，意思是优美的姿态。"}, "sentence_index": null, "correct_answer": "疯子"}, "level_3": {"options": [{"text": "疯子", "is_correct": true, "explanation": "疯子：精神失常的人，此句说他并非精神失常，只是太累。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不会“太累”，与“只是太累了”冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“累”通常用于人或能动的事物，不能说桌子累了。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是人，不会“太累”，句意荒谬。"}], "explanations": {"疯子": "疯子：精神失常的人，此句说他并非精神失常，只是太累。", "窗户": "语义：窗户不是人，不会“太累”，与“只是太累了”冲突。", "桌子": "搭配：“累”通常用于人或能动的事物，不能说桌子累了。", "雨": "语义：雨不是人，不会“太累”，句意荒谬。"}, "sentence_index": 0, "correct_answer": "疯子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的老狗是个疯子，见人就咬。", "explanation": "这里应该用〈疯狗〉。“疯子”指人，形容狗发狂要说〈疯狗〉。"}, {"text": "她的汽车是个疯子，天天自己发动。", "explanation": "这里“疯子”指精神失常的人，不能用于汽车；汽车出毛病应说〈故障〉。"}, {"text": "她家的门是个疯子，每天自己开关。", "explanation": "这里“疯子”指精神失常的人，不能用于门；门自己开关应说〈自动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疯子", "is_correct": true, "explanation": "疯子：精神失常的人，常常听不懂别人的话，与句意相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物没有听觉和语言能力，谈不上“听不懂别人的话”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯没有感知能力，不会“听不懂”别人的话。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“听不懂”需要有感知能力的施事，房子不能充当。"}], "explanations": {"疯子": "疯子：精神失常的人，常常听不懂别人的话，与句意相符。", "植物": "语义：植物没有听觉和语言能力，谈不上“听不懂别人的话”。", "灯": "语义：灯没有感知能力，不会“听不懂”别人的话。", "房子": "配价：“听不懂”需要有感知能力的施事，房子不能充当。"}, "sentence_index": 6, "correct_answer": "疯子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的老机器是个疯子，常常乱响。", "explanation": "这里“疯子”指人，不能用于机器；机器乱响应说〈故障〉。"}, {"text": "球场上的草皮是个疯子，长得乱七八糟。", "explanation": "这里“疯子”指人，不能用于草皮；草长得乱应说〈杂乱〉。"}, {"text": "医院里的小鸟是个疯子，见人就飞。", "explanation": "这里“疯子”指人，不能用于鸟；鸟受惊乱飞应说〈惊飞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生让那座疯子住进了病房。", "corrected_sentence": "医生让那个疯子住进了病房。", "error_description": "错误在量词：“疯子”指人，应用“个”，“座”用于建筑、山等，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上走过来一头疯子。", "corrected_sentence": "街上走过来一个疯子。", "error_description": "错误在量词：“疯子”指人，应用“个”，“头”多用于牛、猪等动物，不用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
