INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比做是说一样东西像另一样东西。", "primary_collocate": null, "pronunciation": "bǐ zuò", "ipa": "pi˨˩ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "人们常把老师比做蜡烛。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的家比做一个小公园。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把时间比做金钱。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把弟弟的房间比做垃圾站。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上把月亮比做一个大盘子。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常把朋友比做自己的家人。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把孩子们比做早上的太阳。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把爸爸的手比做大树。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着把这座城市比做一本书。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人把工作比做一场长跑。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比作", "label": "异形词"}, {"form": "比做了", "label": "完成体"}, {"form": "比做过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "常用“把A比做B”，说A像B，指出两样东西相似", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比做", "is_correct": true, "explanation": "正确。“把老师比做蜡烛”表示老师像蜡烛，是打比方的用法。"}, {"text": "卖掉", "is_correct": false, "explanation": "语义：“卖掉”指把东西出售，句中“老师”不能被卖掉，句意荒谬。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的宾语应是火、灯等具体事物，不能与“老师”搭配。"}, {"text": "吹灭", "is_correct": false, "explanation": "搭配：“吹灭”指把火吹熄，不能以“老师”作对象。"}], "explanations": {"比做": "正确。“把老师比做蜡烛”表示老师像蜡烛，是打比方的用法。", "卖掉": "语义：“卖掉”指把东西出售，句中“老师”不能被卖掉，句意荒谬。", "点燃": "搭配：“点燃”的宾语应是火、灯等具体事物，不能与“老师”搭配。", "吹灭": "搭配：“吹灭”指把火吹熄，不能以“老师”作对象。"}, "sentence_index": 0, "correct_answer": "比做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "按规定，一小时被比做六十分钟。", "explanation": "这里应该用〈等于〉。一小时就是六十分钟，是数量完全相等，比做只表示相像。"}, {"text": "经过投票，全班同学正式把她比做了班长。", "explanation": "这里应该用〈选为〉。投票是正式选定职务，比做只表示相像，不能用来任命。"}, {"text": "我们把一斤比做了五百克。", "explanation": "这里应该用〈等于〉。表示数量完全相同，比做只表示相似，不表示等同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比做", "is_correct": true, "explanation": "正确。“老人把孩子们比做早上的太阳”表示孩子们像早上的太阳，是比喻用法。"}, {"text": "拆成", "is_correct": false, "explanation": "语义：“拆成”指拆散后另组成别的样子，与句中的比喻无关，句意荒谬。"}, {"text": "误认成", "is_correct": false, "explanation": "语义：“误认成”表示看错、当作了另一样东西，并非打比方。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”的宾语须是可以摘取的东西，“孩子们”不能被摘下。"}], "explanations": {"比做": "正确。“老人把孩子们比做早上的太阳”表示孩子们像早上的太阳，是比喻用法。", "拆成": "语义：“拆成”指拆散后另组成别的样子，与句中的比喻无关，句意荒谬。", "误认成": "语义：“误认成”表示看错、当作了另一样东西，并非打比方。", "摘下": "搭配：“摘下”的宾语须是可以摘取的东西，“孩子们”不能被摘下。"}, "sentence_index": 6, "correct_answer": "比做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这张旧桌子比做了一张新床，结果真的搬去当床用了。", "explanation": "这里应该用〈改做〉。比做只表示相像，不表示实际把旧桌子改作床用。"}, {"text": "银行把这张一百元的钞票比做了十张十元的。", "explanation": "这里应该用〈换成〉。这是实际兑换钱，比做只表示相像。"}, {"text": "他把这个汉字的读音比做错了。", "explanation": "这里应该用〈读〉。比做只表示把一样东西说成像另一样东西，不能表示读出字音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常妈妈比做一棵大树。", "corrected_sentence": "我常把妈妈比做一棵大树。", "error_description": "“比做”的把字结构缺少“把”。应为“我常把妈妈比做一棵大树”，“把”用来引出被比作的对象，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把城市比做了了森林。", "corrected_sentence": "他把城市比做了森林。", "error_description": "完成体的“了”只用一次，“比做了”之后不应再加“了”；应为“他把城市比做了森林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
