INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某事物比喻成另一事物。", "primary_collocate": null, "pronunciation": "bǐ zuò", "ipa": "pi˨˩ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "诗人把春天比做一位年轻的姑娘。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家把母亲比做一盏不灭的灯。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课文里把白云比做白色的小羊。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗把时间比做流水。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在文章里把学校比做大花园。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要随便把人比做动物。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌里把爱情比做一朵玫瑰花。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写过一篇文章，把生活比做大海。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这首歌里，人们把月亮比做妈妈的脸。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把这本书比做一个朋友。", "target_word": "比做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比作", "label": "异形词"}, {"form": "比做了", "label": "完成体"}, {"form": "比做过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "修辞用法，在诗歌、文章、歌曲中把A比喻成B，让描写更形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比做", "is_correct": true, "explanation": "正确。“诗人把春天比做一位年轻的姑娘”是修辞上的比喻。"}, {"text": "误认成", "is_correct": false, "explanation": "语义：“误认成”表示看错，把春天当成了姑娘，并非修辞上的比喻。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”的宾语须是花、果等可以摘取的东西，“春天”不能被摘下。"}, {"text": "晒成", "is_correct": false, "explanation": "语义：“晒成”指晒干成形，与诗歌中的比喻无关，句意荒谬。"}], "explanations": {"比做": "正确。“诗人把春天比做一位年轻的姑娘”是修辞上的比喻。", "误认成": "语义：“误认成”表示看错，把春天当成了姑娘，并非修辞上的比喻。", "摘下": "搭配：“摘下”的宾语须是花、果等可以摘取的东西，“春天”不能被摘下。", "晒成": "语义：“晒成”指晒干成形，与诗歌中的比喻无关，句意荒谬。"}, "sentence_index": 0, "correct_answer": "比做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "按规定，二十四小时被比做一整天。", "explanation": "这里应该用〈算作〉。二十四小时就是一天，是完全相等，比做只表示相像。"}, {"text": "医生把他比做患了肺炎的人。", "explanation": "这里应该用〈认定〉。诊断结论是确定的事实，比做只表示相像，不表示判定。"}, {"text": "他的身高比做了一米八。", "explanation": "这里应该用〈是〉。比做只表示相像，不表示测量结果的完全相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比做", "is_correct": true, "explanation": "正确。“歌里把爱情比做一朵玫瑰花”是比喻用法，表示爱情像玫瑰。"}, {"text": "剪下", "is_correct": false, "explanation": "搭配：“剪下”指从植株上剪取，“爱情”不能被剪下作花。"}, {"text": "买下", "is_correct": false, "explanation": "语义：“买下”指购买，“爱情”不能被买下作花，句意不通。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”指把东西打破，与歌词中的比喻无关，句意荒谬。"}], "explanations": {"比做": "正确。“歌里把爱情比做一朵玫瑰花”是比喻用法，表示爱情像玫瑰。", "剪下": "搭配：“剪下”指从植株上剪取，“爱情”不能被剪下作花。", "买下": "语义：“买下”指购买，“爱情”不能被买下作花，句意不通。", "摔碎": "语义：“摔碎”指把东西打破，与歌词中的比喻无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "比做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这张桌子比做了一张床，结果真的搬进卧室当床用了。", "explanation": "这里应该用〈当做〉。比做只表示相像，不表示把桌子实际当作床来用。"}, {"text": "这位母亲把孩子的旧衣服比做了一件新外套，真的拿去改制了。", "explanation": "这里应该用〈改制〉。比做只表示相像，不表示实际把旧衣服改做成外套。"}, {"text": "老师把这道题的答案比做出来了。", "explanation": "这里应该用〈算〉。比做只表示相像，不能表示计算出结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "诗人常月亮比做一面镜子。", "corrected_sentence": "诗人常把月亮比做一面镜子。", "error_description": "“比做”的把字结构缺少“把”。应为“诗人常把月亮比做一面镜子”，“把”引出被比作的对象，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这首歌了比做一段回忆。", "corrected_sentence": "我把这首歌比做一段回忆。", "error_description": "体标记“了”的位置错误：“了”放在了“比做”之前。应为“我把这首歌比做一段回忆”，“比做”前不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
