INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让声音出来。", "primary_collocate": null, "pronunciation": "fā shēng", "ipa": "fa˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "唱歌前要先练习发声。", "target_word": "发声", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教我们怎么正确发声。", "target_word": "发声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具一按就会发声。", "target_word": "发声", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "感冒了，我今天很难发声。", "target_word": "发声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "歌手每天早上都要练发声。", "target_word": "发声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小提琴靠琴弦振动来发声。", "target_word": "发声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他紧张得一时没能发声。", "target_word": "发声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓是敲打鼓面发声的。", "target_word": "发声", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，他的声带受伤，暂时不能发声。", "target_word": "发声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先学会用腹部发声，再学唱歌。", "target_word": "发声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了声", "label": "体标（了）"}, {"form": "发过声", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "让声音出来；用嗓子或物体发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发声", "is_correct": true, "explanation": "正确：“发声”指发出声音，与“唱歌前练习”的语境相符。"}, {"text": "发胖", "is_correct": false, "explanation": "语义：“发胖”指身体变胖，不是唱歌前要练习的内容。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不能拿来练习，与唱歌前的准备不合。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：“倒退”与练习的目的相反，唱歌前不会去练习倒退。"}], "explanations": {"发声": "正确：“发声”指发出声音，与“唱歌前练习”的语境相符。", "发胖": "语义：“发胖”指身体变胖，不是唱歌前要练习的内容。", "发烧": "语义：“发烧”是身体状况，不能拿来练习，与唱歌前的准备不合。", "倒退": "语义：“倒退”与练习的目的相反，唱歌前不会去练习倒退。"}, "sentence_index": 0, "correct_answer": "发声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗星星一闪就发声，很奇怪。", "explanation": "这里应该用〈发光〉。“发声”指让声音出来；星星闪烁时发出的是光，不能说“发声”。"}, {"text": "他的脸一红就发声，大家都看着他。", "explanation": "“发声”指让声音出来；脸变红是颜色变化，不会发出声音，这里不能用“发声”，应说“他的脸一下子红了”。"}, {"text": "这朵云一飘过就发声，很奇怪。", "explanation": "这里应该用〈移动〉。云只能移动，不能发出声音，“发声”不能用于云。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发声", "is_correct": true, "explanation": "正确：“发声”指发出声音，与“紧张得一时没能”的语境相符。"}, {"text": "发财", "is_correct": false, "explanation": "语义：“发财”指获得财富，与句中紧张到说不出话的状态完全无关。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指失去工作，与句中紧张的状态无关。"}, {"text": "发亮", "is_correct": false, "explanation": "搭配：“发亮”多用于物体，不能用来描述人紧张时的状态。"}], "explanations": {"发声": "正确：“发声”指发出声音，与“紧张得一时没能”的语境相符。", "发财": "语义：“发财”指获得财富，与句中紧张到说不出话的状态完全无关。", "失业": "语义：“失业”指失去工作，与句中紧张的状态无关。", "发亮": "搭配：“发亮”多用于物体，不能用来描述人紧张时的状态。"}, "sentence_index": 6, "correct_answer": "发声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用眼睛发声，老师很生气。", "explanation": "这里应该用〈看〉。“发声”指让声音出来，眼睛不能发出声音；“用眼睛”后面应接〈看〉。"}, {"text": "这朵花一直在发声。", "explanation": "这里应该用〈开〉。“发声”指让声音出来；花只能开放，不能发出声音。"}, {"text": "他的眉毛开始发声了。", "explanation": "这里应该用〈动〉。眉毛不能发出声音，“发声”不能指身体部位的动作，应说眉毛“动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的玩具熊一按肚子，就会发声过。", "corrected_sentence": "我的玩具熊一按肚子，就会发声。", "error_description": "“发声”是动宾式词语，“过”不能直接加在“发声”之后；这里说的是一般性的“会……”，应说“就会发声”，不能说“就会发声过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小鸟一受惊就发声过，很吵。", "corrected_sentence": "这只小鸟一受惊就发声，很吵。", "error_description": "“发声”是动宾式离合词，“过”不能直接加在“发声”之后；此处是一般性的“一……就……”，不用体标，应说“这只小鸟一受惊就发声，很吵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
