INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "瘫痪是身体不能动，或者机器不能用。", "primary_collocate": null, "pronunciation": "tān huàn", "ipa": "tʰan˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷中风后，右腿瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器突然瘫痪了，工人们都很着急。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的双腿已经瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑中了病毒，整个系统瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为车祸瘫痪，只能坐轮椅。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的机器瘫痪着，没人会修。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的左手瘫痪过一段时间，后来好了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络瘫痪了，我们没办法上网。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瘫痪的病人需要家人照顾。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那台旧电梯瘫痪了，大家只好走楼梯。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瘫痪了", "label": "体标（了）"}, {"form": "瘫痪着", "label": "体标（着）"}, {"form": "瘫痪过", "label": "体标（过）"}, {"form": "癱瘓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体不能动或机器不能用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是呼吸道的动作，右腿不会咳嗽。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“失眠”只用于人睡不着，不能说腿失眠。"}, {"text": "思考", "is_correct": false, "explanation": "语义：思考需要头脑，右腿不能思考。"}, {"text": "瘫痪", "is_correct": true, "explanation": "正确：“瘫痪”指身体部位失去运动能力，与中风后右腿不能动相符。"}], "explanations": {"咳嗽": "语义：咳嗽是呼吸道的动作，右腿不会咳嗽。", "失眠": "搭配：“失眠”只用于人睡不着，不能说腿失眠。", "思考": "语义：思考需要头脑，右腿不能思考。", "瘫痪": "正确：“瘫痪”指身体部位失去运动能力，与中风后右腿不能动相符。"}, "sentence_index": 0, "correct_answer": "瘫痪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸被雨淋湿了，字迹瘫痪了。", "explanation": "这里应该用〈模糊〉。字迹被水弄得看不清是模糊；瘫痪不能用于字迹。"}, {"text": "坐了很久，我的左腿瘫痪了一下。", "explanation": "这里应该用〈麻木〉。坐久了腿发麻是麻木，瘫痪不是短暂的发麻。"}, {"text": "夏天没有雨，院子里的花叶子都瘫痪了。", "explanation": "这里应该用〈枯萎〉。枯萎指植物缺水后叶子干瘪、失去生机；瘫痪只用于人体或机器，不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打鼾", "is_correct": false, "explanation": "语义：打鼾是人睡觉时发出的呼吸声，左手不会打鼾。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣是人流泪出声，左手不能哭泣。"}, {"text": "脸红", "is_correct": false, "explanation": "搭配：“脸红”搭配的是脸和人，不能说左手脸红。"}, {"text": "瘫痪", "is_correct": true, "explanation": "正确：“瘫痪”指肢体失去运动能力，与左手暂时不能动、后来好了的情况相符。"}], "explanations": {"打鼾": "语义：打鼾是人睡觉时发出的呼吸声，左手不会打鼾。", "哭泣": "语义：哭泣是人流泪出声，左手不能哭泣。", "脸红": "搭配：“脸红”搭配的是脸和人，不能说左手脸红。", "瘫痪": "正确：“瘫痪”指肢体失去运动能力，与左手暂时不能动、后来好了的情况相符。"}, "sentence_index": 6, "correct_answer": "瘫痪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气太冷，湖面瘫痪了。", "explanation": "这里应该用〈结冰〉。水遇冷凝成冰是结冰；瘫痪不能用于湖面。"}, {"text": "这块蛋糕放了一周，已经瘫痪了。", "explanation": "这里应该用〈变质〉。食物放坏是变质；瘫痪不能用于食物。"}, {"text": "这种药的效果已经瘫痪了。", "explanation": "这里应该用〈失效〉。瘫痪只用于身体、机器或系统不能正常动作，药效不能说瘫痪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车祸后，他的双腿很瘫痪了。", "corrected_sentence": "车祸后，他的双腿瘫痪了。", "error_description": "错误形式“双腿很瘫痪了”，正确形式“双腿瘫痪了”。“瘫痪”是表示失去运动能力的动词，不能受程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的左手瘫痪着一段时间，后来好了。", "corrected_sentence": "他的左手瘫痪过一段时间，后来好了。", "error_description": "错误形式“瘫痪着一段时间”，正确形式“瘫痪过一段时间”。“着”表示状态正在持续，不能和已经结束的一段时间连用（“后来好了”）；这里说的是过去的经历，要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
