INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体部分失去运动能力；比喻机构或交通等无法正常运转。", "primary_collocate": null, "pronunciation": "tān huàn", "ipa": "tʰan˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "大雪让城市的交通瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的下半身瘫痪，已经十年了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，整个地铁线路瘫痪。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒让医院的系统一度瘫痪。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的右半边身体瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故使高速公路完全瘫痪。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有领导，管理几乎瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人中风后半身瘫痪，需要人照顾。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罢工让整个港口陷入瘫痪。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电以后，全城的交通都瘫痪了。", "target_word": "瘫痪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瘫痪了", "label": "体标（了）"}, {"form": "瘫痪着", "label": "体标（着）"}, {"form": "瘫痪过", "label": "体标（过）"}, {"form": "癱瘓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体部位丧失运动能力，比喻交通机构无法运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是人患的病，交通不会感冒。"}, {"text": "打喷嚏", "is_correct": false, "explanation": "语义：打喷嚏是人的生理动作，交通不能打喷嚏。"}, {"text": "怀孕", "is_correct": false, "explanation": "搭配：“怀孕”只用于女性，不能说交通怀孕。"}, {"text": "瘫痪", "is_correct": true, "explanation": "正确：“瘫痪”可比喻交通等无法正常运转，与大雪造成的情况相符。"}], "explanations": {"感冒": "语义：“感冒”是人患的病，交通不会感冒。", "打喷嚏": "语义：打喷嚏是人的生理动作，交通不能打喷嚏。", "怀孕": "搭配：“怀孕”只用于女性，不能说交通怀孕。", "瘫痪": "正确：“瘫痪”可比喻交通等无法正常运转，与大雪造成的情况相符。"}, "sentence_index": 0, "correct_answer": "瘫痪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服洗了很多次，颜色瘫痪了。", "explanation": "这里应该用〈褪色〉。衣服颜色变淡是褪色；瘫痪不能用于颜色。"}, {"text": "这盆多肉植物缺水后，叶子瘫痪了。", "explanation": "这里应该用〈枯萎〉。枯萎指植物缺水后失去水分、叶子干瘪；瘫痪不能用于植物。"}, {"text": "冰块在阳光下慢慢瘫痪了。", "explanation": "这里应该用〈融化〉。冰受热变成水是融化；瘫痪只用于身体，或机构、交通等无法正常运转的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发烧", "is_correct": false, "explanation": "语义：发烧是人或动物的病症，管理不会发烧。"}, {"text": "流泪", "is_correct": false, "explanation": "搭配：“流泪”的主体是人或眼睛，不能说管理流泪。"}, {"text": "失恋", "is_correct": false, "explanation": "语义：失恋指恋爱关系结束，管理不能失恋。"}, {"text": "瘫痪", "is_correct": true, "explanation": "正确：“瘫痪”比喻管理等无法正常运转，与没有领导时管理几乎停摆的情况相符。"}], "explanations": {"发烧": "语义：发烧是人或动物的病症，管理不会发烧。", "流泪": "搭配：“流泪”的主体是人或眼睛，不能说管理流泪。", "失恋": "语义：失恋指恋爱关系结束，管理不能失恋。", "瘫痪": "正确：“瘫痪”比喻管理等无法正常运转，与没有领导时管理几乎停摆的情况相符。"}, "sentence_index": 6, "correct_answer": "瘫痪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块面团放凉了，已经瘫痪了。", "explanation": "这里应该用〈变硬〉。面团放凉变硬是变硬；瘫痪不能用于食物。"}, {"text": "这个保险条款已经瘫痪了。", "explanation": "这里应该用〈失效〉。条款不再起作用要说失效，瘫痪只用于身体、机器或系统不能动作。"}, {"text": "这支笔的墨水瘫痪了。", "explanation": "这里应该用〈干涸〉。墨水用光或变干可以说干涸；瘫痪不能用于墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨过后，几条地铁线路都很瘫痪了。", "corrected_sentence": "暴雨过后，几条地铁线路都瘫痪了。", "error_description": "错误形式“都很瘫痪了”，正确形式“都瘫痪了”。“瘫痪”不能受程度副词“很”修饰，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震以后，全城的交通瘫痪着三天，后来才恢复。", "corrected_sentence": "地震以后，全城的交通瘫痪了三天，后来才恢复。", "error_description": "错误形式“瘫痪着三天”，正确形式“瘫痪了三天”。“着”表示状态正在持续，不能带已经完成的时段（“三天”“后来才恢复”）；表示完成的时段要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
