INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92411, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "比及是等到了某个时候。", "primary_collocate": null, "pronunciation": "bǐ jí", "ipa": "pi˨˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "比及天亮，大雨已经停了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及我赶到车站，火车早就开走了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及春天来了，山上的花都开了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及他回到家，饭菜已经凉了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及大家到齐，天已经黑了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及夜深人静，他才开始写信。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及孩子长大，父母已经老了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及我们找到路，天已经黑了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及秋天，这里的树叶就都黄了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及她醒来，医生已经走了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连词，等到某个时候，后面常接已经、早就等表示结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比及", "is_correct": true, "explanation": "“比及”表示等到某个时候，与“天亮，大雨已经停了”相符。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，与“已经停了”所说的既成事实不协调。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，天亮与大雨停之间并无让步关系。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，天亮与大雨停之间没有因果关系。"}], "explanations": {"比及": "“比及”表示等到某个时候，与“天亮，大雨已经停了”相符。", "如果": "语义：“如果”表示假设，与“已经停了”所说的既成事实不协调。", "虽然": "语义：“虽然”表示让步，天亮与大雨停之间并无让步关系。", "因为": "语义：“因为”表示原因，天亮与大雨停之间没有因果关系。"}, "sentence_index": 0, "correct_answer": "比及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比及我大三岁。", "explanation": "这里应该用〈比〉。比及表示等到某个时候，不能表示比较。"}, {"text": "我们在门口比及他。", "explanation": "这里应该用〈等〉。比及是连词，只用来引出时间，不能作“等待”的动词。"}, {"text": "他们比及跑步，看谁跑得快。", "explanation": "这里应该用〈比赛〉。比及是连词，只表示等到某个时候，不能作动词表示“比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比及", "is_correct": true, "explanation": "“比及”表示等到某个时候，与“孩子长大，父母已经老了”相符。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”表示充分条件，与“已经老了”的已然状态不协调。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”是并列连词，不能引出时间从句，与后句不搭配。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“父母已经老了”不能作目的，句子不通。"}], "explanations": {"比及": "“比及”表示等到某个时候，与“孩子长大，父母已经老了”相符。", "只要": "语义：“只要”表示充分条件，与“已经老了”的已然状态不协调。", "而且": "搭配：“而且”是并列连词，不能引出时间从句，与后句不搭配。", "为了": "语义：“为了”表示目的，“父母已经老了”不能作目的，句子不通。"}, "sentence_index": 6, "correct_answer": "比及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把生活比及成一条河。", "explanation": "这里应该用〈比喻〉。比及是连词，只表示等到某个时候，不能用来打比方。"}, {"text": "比及你可以先写作业，再看电视。", "explanation": "这里应该用〈比如〉。比及只表示等到某个时候，不能用来举例。"}, {"text": "这件事比及以前的规定办理。", "explanation": "这里应该用〈比照〉。比及只表示等到某个时候，不能用来表示参照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比及下班，他比及回家。", "corrected_sentence": "比及下班，他才回家。", "error_description": "错误形式：“他比及回家”；正确形式：“他才回家”。原因：“比及”是连词，只用来引出时间从句，不能放在主句的谓语前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比及孩子长大，他比及明白道理。", "corrected_sentence": "比及孩子长大，他才明白道理。", "error_description": "错误形式：“他比及明白道理”；正确形式：“他才明白道理”。原因：“比及”是连词，只能引出时间从句，不能放在主句的谓语前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
