INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92412, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "书面语，等到（某时）。", "primary_collocate": null, "pronunciation": "bǐ jí", "ipa": "pi˨˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "比及登上山顶，太阳已经落山了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及月底，这笔钱就能还清了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及客人来到，主人早已备好酒菜。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及毕业，他已经会说三种语言了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及雪化了，路上的人才多起来。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及我写完信，邮局已经关门了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及天黑，村里的灯都亮了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及他明白过来，事情已经晚了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及冬天来临，河水都结了冰。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比及他们赶来，火已经灭了。", "target_word": "比及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面连词，等到某时，引出时间从句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比及", "is_correct": true, "explanation": "“比及”表示等到某个时候，与“登上山顶，太阳已经落山了”相符。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”表示充分条件，与“太阳已经落山”的已然事实不协调。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”是并列连词，不能引出时间从句，与后句不搭配。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，到山顶与太阳落山之间没有因果关系。"}], "explanations": {"比及": "“比及”表示等到某个时候，与“登上山顶，太阳已经落山了”相符。", "只要": "语义：“只要”表示充分条件，与“太阳已经落山”的已然事实不协调。", "而且": "搭配：“而且”是并列连词，不能引出时间从句，与后句不搭配。", "因为": "语义：“因为”表示原因，到山顶与太阳落山之间没有因果关系。"}, "sentence_index": 0, "correct_answer": "比及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她比及我高一头。", "explanation": "这里应该用〈比〉。比及表示等到某个时候，不表示比较。"}, {"text": "我在车站比及朋友。", "explanation": "这里应该用〈等〉。比及是连词，只用来引出时间，不能作“等待”的动词。"}, {"text": "这事比及去年的办法办理。", "explanation": "这里应该用〈比照〉。比及只表示等到某个时候，不能表示参照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比及", "is_correct": true, "explanation": "“比及”表示等到某个时候，与“天黑，村里的灯都亮了”相符。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“村里的灯都亮了”不能作目的，句子不通。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”引出结果，不能与“天黑”这样的时间成分搭配。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，“天黑，灯亮了”之间并没有转折关系。"}], "explanations": {"比及": "“比及”表示等到某个时候，与“天黑，村里的灯都亮了”相符。", "为了": "语义：“为了”表示目的，“村里的灯都亮了”不能作目的，句子不通。", "因此": "搭配：“因此”引出结果，不能与“天黑”这样的时间成分搭配。", "不过": "语义：“不过”表示转折，“天黑，灯亮了”之间并没有转折关系。"}, "sentence_index": 6, "correct_answer": "比及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比及说，我们周末去爬山。", "explanation": "这里应该用〈比方〉。比及只表示等到某个时候，不能用来举例。"}, {"text": "他们比及游泳，看谁游得快。", "explanation": "这里应该用〈比赛〉。比及只表示等到某个时候，不能作动词表示“比赛”。"}, {"text": "他把人生比及成一场旅行。", "explanation": "这里应该用〈比喻〉。比及只表示等到某个时候，不能用来打比方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比及月亮升起，我们比及出发。", "corrected_sentence": "比及月亮升起，我们才出发。", "error_description": "错误形式：“我们比及出发”；正确形式：“我们才出发”。原因：“比及”只引出时间从句，不能放在主句的谓语前修饰动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比及大家都到了，比及开始开会。", "corrected_sentence": "比及大家都到了，才开始开会。", "error_description": "错误形式：“比及开始开会”；正确形式：“才开始开会”。原因：“比及”只引出时间从句，不能放在主句的谓语前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
