INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛看的样子。", "primary_collocate": null, "pronunciation": "mù guāng", "ipa": "mu˥˩ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "妈妈看着我，目光很温柔。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目光冷冷的，没有一点笑意。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用严厉的目光看着我们。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的目光里有一点担心。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子的目光很干净。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他目光坚定地说：“我不会走。”", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看我的目光总是很慈祥。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这个消息，他的目光变了。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用生气的目光看了我一眼。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的目光很友好，我一点也不紧张。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道目光", "label": "量词"}, {"form": "目光短浅", "label": "复合"}], "register": "中性", "sense_fingerprint": "眼睛看人看事时表现出的样子和神情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目光", "is_correct": true, "explanation": "正确：“目光很温柔”指眼神柔和，与“看着我”相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“温柔”形容的是目光、声音一类，不能用来形容身材。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：房间不会“温柔”，“温柔”不与房间搭配。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能“温柔”，句意不通。"}], "explanations": {"目光": "正确：“目光很温柔”指眼神柔和，与“看着我”相合。", "身材": "体貌：“温柔”形容的是目光、声音一类，不能用来形容身材。", "房间": "搭配：房间不会“温柔”，“温柔”不与房间搭配。", "作业": "语义：作业是学习任务，不能“温柔”，句意不通。"}, "sentence_index": 0, "correct_answer": "目光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的目光很大，看起来很可爱。", "explanation": "这里应该用〈眼睛〉。目光指眼神或神情，不能用“大”来形容，应说“眼睛很大”。"}, {"text": "他朝我投来一只目光。", "explanation": "这里应该用〈道〉。目光的量词是“道”，“只”多用于动物和器物，不说“一只目光”。"}, {"text": "这把椅子的目光很温柔。", "explanation": "这里应该用〈样子〉。目光指人或动物眼睛的神情，椅子没有眼睛，只能说样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目光", "is_correct": true, "explanation": "正确：“看我的目光”指眼神，与“慈祥”相合。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能“看我”，与“慈祥”的语境不合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“慈祥”形容神情，不能用来形容身高。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包不能“慈祥”，“慈祥”不与书包搭配。"}], "explanations": {"目光": "正确：“看我的目光”指眼神，与“慈祥”相合。", "饭菜": "语义：饭菜是食物，不能“看我”，与“慈祥”的语境不合。", "身高": "体貌：“慈祥”形容神情，不能用来形容身高。", "书包": "搭配：书包不能“慈祥”，“慈祥”不与书包搭配。"}, "sentence_index": 6, "correct_answer": "目光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处传来一阵清脆的目光。", "explanation": "这里应该用〈声音〉。目光指眼神或神情，不能指听到的声音。"}, {"text": "这朵花的目光很鲜艳。", "explanation": "这里应该用〈颜色〉。目光是人的眼神或神情，不能用来形容花的鲜艳。"}, {"text": "他流下了目光。", "explanation": "这里应该用〈眼泪〉。目光不会“流下”，流下的是眼泪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向我投来一张温柔的目光。", "corrected_sentence": "她向我投来一道温柔的目光。", "error_description": "量词错误：“张”用于纸张等平面物件，目光常用量词是“道”或“束”，不说“一张温柔的目光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她朝我投来一只温柔的目光。", "corrected_sentence": "她朝我投来一道温柔的目光。", "error_description": "目光常用量词是“道”或“束”，“一只”多用于动物和器物，不说“一只温柔的目光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
