INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛的神采；视线。", "primary_collocate": null, "pronunciation": "mù guāng", "ipa": "mu˥˩ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "她的目光落在桌上的那封信上。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到声音，大家的目光都转向门口。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目光一直跟着那只小鸟。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不好意思，赶紧移开了目光。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画吸引了很多人的目光。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目光一碰到我，就马上低下头。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的目光追着气球越飞越远。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把目光投向窗外的大树。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的目光里带着一点笑意。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目光碰到了一起。", "target_word": "目光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道目光", "label": "量词"}, {"form": "目光短浅", "label": "复合"}], "register": "中性", "sense_fingerprint": "视线所及的方向，或眼睛里的神采", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目光", "is_correct": true, "explanation": "正确：“目光落在”指视线落在某处，与句意相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是内心感受，不能“落在”某物上。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不能“落在”信上。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，与“落在信上”的动作不相容。"}], "explanations": {"目光": "正确：“目光落在”指视线落在某处，与句意相合。", "心情": "语义：心情是内心感受，不能“落在”某物上。", "脾气": "语义：脾气是性格特点，不能“落在”信上。", "年龄": "语义：年龄是岁数，与“落在信上”的动作不相容。"}, "sentence_index": 0, "correct_answer": "目光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子里的目光流了出来。", "explanation": "这里应该用〈水〉。目光不能像液体一样流出来。"}, {"text": "他朝门口投去一张目光。", "explanation": "这里应该用〈道〉。目光的量词是“道”，不说“一张目光”。"}, {"text": "他一脚把目光踢进了门。", "explanation": "这里应该用〈球〉。目光不是实物，不能被踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目光", "is_correct": true, "explanation": "正确：“目光追着”指视线跟随，与“越飞越远”相合。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不能追着气球跑，与句中孩子追逐气球的动作不合。"}, {"text": "力气", "is_correct": false, "explanation": "语义：力气不能追着东西飞，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“追着”要求有视线或行动的主体，课本不能作主语。"}], "explanations": {"目光": "正确：“目光追着”指视线跟随，与“越飞越远”相合。", "耳朵": "语义：耳朵不能追着气球跑，与句中孩子追逐气球的动作不合。", "力气": "语义：力气不能追着东西飞，句意不通。", "课本": "配价：“追着”要求有视线或行动的主体，课本不能作主语。"}, "sentence_index": 6, "correct_answer": "目光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光透过树叶，在地上投下斑驳的目光。", "explanation": "这里应该用〈光线〉。目光指眼睛的神采或视线，不能指照在地上的光。"}, {"text": "目光下了一整天。", "explanation": "这里应该用〈雨〉。目光不会“下”，“下”只用于雨雪一类。"}, {"text": "目光很香，我们都想吃。", "explanation": "这里应该用〈饭菜〉。目光不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向窗外的大树投去一只目光。", "corrected_sentence": "她向窗外的大树投去一道目光。", "error_description": "量词错误：目光的量词应为“道”，不用“只”。“只”多用于动物和器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师用一把锐利的目光扫过全班同学。", "corrected_sentence": "老师用一道锐利的目光扫过全班同学。", "error_description": "量词错误：“把”用于有柄的器物，目光常用量词是“道”或“束”，不说“一把锐利的目光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
