INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用各种能源产生电力的工厂。", "primary_collocate": null, "pronunciation": "fā diàn chǎng", "ipa": "fa˥ tjɛn˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这座发电厂用煤来发电。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河上的发电厂靠水发电。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里有一座太阳能发电厂。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家发电厂用风力产生电力。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新发电厂建好后，村里不会停电了。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座发电厂烧的是天然气。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的发电厂利用风来发电。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发电厂需要很多煤和水。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这座发电厂能给十万家供电。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市有三家发电厂。", "target_word": "发电厂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "水力发电厂", "label": "复合词"}, {"form": "發電廠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "利用煤、水、风、太阳等能源产生电力的工厂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电厂", "is_correct": true, "explanation": "发电厂：利用各种能源产生电力的工厂，烧煤发电，与句意相符。"}, {"text": "工人", "is_correct": false, "explanation": "搭配：“座”用于建筑、山等，不能修饰工人。"}, {"text": "风车", "is_correct": false, "explanation": "语义：风车靠风转动，不用煤来发电。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库储水，不烧煤发电，与“用煤来发电”冲突。"}], "explanations": {"发电厂": "发电厂：利用各种能源产生电力的工厂，烧煤发电，与句意相符。", "工人": "搭配：“座”用于建筑、山等，不能修饰工人。", "风车": "语义：风车靠风转动，不用煤来发电。", "水库": "语义：水库储水，不烧煤发电，与“用煤来发电”冲突。"}, "sentence_index": 0, "correct_answer": "发电厂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家发电厂用机器生产衣服。", "explanation": "这里应该用〈工厂〉。发电厂只生产电，不生产衣服；生产衣服要用〈工厂〉。"}, {"text": "这座发电厂靠河水转动，用来磨面。", "explanation": "这里应该用〈水车〉。发电厂用来发电，不用来磨面；靠河水转动磨面要用〈水车〉。"}, {"text": "这座发电厂用来给汽车加油。", "explanation": "这里应该用〈加油站〉。发电厂用来发电，不给汽车加油；给汽车加油要用〈加油站〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电厂", "is_correct": true, "explanation": "发电厂：利用各种能源产生电力的工厂，利用风发电，与句意相符。"}, {"text": "太阳能板", "is_correct": false, "explanation": "语义：太阳能板利用阳光发电，不利用风，与句中“利用风”冲突。"}, {"text": "煤矿", "is_correct": false, "explanation": "语义：煤矿是挖煤的地方，不利用风发电。"}, {"text": "渔船", "is_correct": false, "explanation": "配价：“利用……发电”的施事应是发电机构，渔船不能充当。"}], "explanations": {"发电厂": "发电厂：利用各种能源产生电力的工厂，利用风发电，与句意相符。", "太阳能板": "语义：太阳能板利用阳光发电，不利用风，与句中“利用风”冲突。", "煤矿": "语义：煤矿是挖煤的地方，不利用风发电。", "渔船": "配价：“利用……发电”的施事应是发电机构，渔船不能充当。"}, "sentence_index": 6, "correct_answer": "发电厂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们城市有三座发电厂，藏书很多。", "explanation": "这里应该用〈图书馆〉。发电厂不藏书，藏书的是〈图书馆〉。"}, {"text": "这座发电厂用来出版报纸。", "explanation": "这里应该用〈报社〉。发电厂用来发电，不出版报纸；出版报纸要用〈报社〉。"}, {"text": "我们城市有三家发电厂，专门看牙病。", "explanation": "这里应该用〈医院〉。发电厂不看病，看牙病要用〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只发电厂用水力发电。", "corrected_sentence": "这座发电厂用水力发电。", "error_description": "错误在量词：发电厂是建筑，应用“座”（或“家”），“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边那条发电厂已经停用了。", "corrected_sentence": "海边那座发电厂已经停用了。", "error_description": "错误在量词：发电厂是建筑，应用“座”，“条”不能用于发电厂。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
