INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92417, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无上是最高，再也没有比它更高的了。", "primary_collocate": null, "pronunciation": "wú shàng", "ipa": "u˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "作为医生，救人是无上的光荣。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝在古代有无上的权力。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站上领奖台，是运动员无上的荣誉。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子长大，是父母无上的幸福。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛教里，佛有无上的智慧。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对战士来说，保护人民是无上的责任。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在她看来，自由是无上的快乐。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人在村里有无上的威望。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得到大家的信任，是我无上的骄傲。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是国王无上的命令。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "无上：最高，再也没有比它更高的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可耻", "is_correct": false, "explanation": "语义：“光荣”是褒义词，说“可耻的光荣”与句意相反。"}, {"text": "无上", "is_correct": true, "explanation": "正确：无上表示最高、再没有比它更高的，与“光荣”搭配，符合句意。"}, {"text": "可怕", "is_correct": false, "explanation": "语义：“可怕”是贬义，与“救人”“光荣”的褒义相反，句意不通。"}, {"text": "可笑", "is_correct": false, "explanation": "语义：“可笑”与“救人”的褒义不合，句意不通。"}], "explanations": {"可耻": "语义：“光荣”是褒义词，说“可耻的光荣”与句意相反。", "无上": "正确：无上表示最高、再没有比它更高的，与“光荣”搭配，符合句意。", "可怕": "语义：“可怕”是贬义，与“救人”“光荣”的褒义相反，句意不通。", "可笑": "语义：“可笑”与“救人”的褒义不合，句意不通。"}, "sentence_index": 0, "correct_answer": "无上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事只有无上的一点了解。", "explanation": "这里把〈无上〉当成“程度高”来用，但〈无上〉表示最高，不能与“只有一点”的限定搭配；〈无上〉不用于表示少量。"}, {"text": "大家向去世的老人表示无上的哀悼。", "explanation": "这里把〈无上〉当成“深切”来用，但〈无上〉表示最高，不修饰哀悼这类情感；应用〈沉痛〉。"}, {"text": "他只领到无上的工资。", "explanation": "这里把〈无上〉当成“多、高”来用，但〈无上〉表示最高，不用于工资的多少；应用〈微薄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "致命", "is_correct": false, "explanation": "语义：“自由”不会是“致命的”，与句意相悖。"}, {"text": "无上", "is_correct": true, "explanation": "正确：无上表示最高，与“快乐”搭配，符合句意。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“快乐”通常不说“沉重的”，与“自由”的轻快语境不合。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“快乐”不与“粗糙的”搭配，句子不通。"}], "explanations": {"致命": "语义：“自由”不会是“致命的”，与句意相悖。", "无上": "正确：无上表示最高，与“快乐”搭配，符合句意。", "沉重": "搭配：“快乐”通常不说“沉重的”，与“自由”的轻快语境不合。", "粗糙": "搭配：“快乐”不与“粗糙的”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "无上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的态度比以前更无上。", "explanation": "这里把〈无上〉当成可以比较高低的形容词来用；〈无上〉已是最高，没有“比以前更高”的比较。"}, {"text": "老人的话在村里非常无上。", "explanation": "这里把〈无上〉当成可以分程度的形容词来用，说成“非常高”；〈无上〉本身已是最高，不分程度。"}, {"text": "这次比赛的成绩很无上。", "explanation": "这里把〈无上〉当成可以分程度的形容词来用，说成“很高”；〈无上〉本身已是最高，不分程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作为老师，育人是我无上地使命。", "corrected_sentence": "作为老师，育人是我无上的使命。", "error_description": "“无上”修饰名词“使命”时应用“的”，不能用“地”（“地”用于修饰动词或形容词）。错误在于用了“地”，应改为“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把诚信看作很无上的追求。", "corrected_sentence": "他把诚信看作无上的追求。", "error_description": "“无上”表示最高，不分程度，不能用“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
