INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92418, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "书面语，最高的，没有更高的。", "primary_collocate": null, "pronunciation": "wú shàng", "ipa": "u˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "能为国家工作，是他无上的光荣。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，国王有无上的权力。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得到这个奖，是我无上的荣誉。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对母亲来说，孩子的笑是无上的快乐。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这是无上的责任。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们说，健康是无上的财富。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们认为，神有无上的智慧。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在学生心中有无上的地位。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能上台唱歌，对她来说是无上的幸福。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他心里，母亲的爱是无上的。", "target_word": "无上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "无上：书面语，最高的，没有更高的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "私人", "is_correct": false, "explanation": "语义：“为国家工作”是公共的事，说成“私人的光荣”与句意相矛盾。"}, {"text": "无上", "is_correct": true, "explanation": "正确：无上表示最高、没有更高，与“光荣”搭配，符合句意。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”与“光荣”的褒义相反，句意不通。"}, {"text": "耻辱", "is_correct": false, "explanation": "语义：“耻辱”与“光荣”正相反，与句中“为国家工作”的正面语境相悖。"}], "explanations": {"私人": "语义：“为国家工作”是公共的事，说成“私人的光荣”与句意相矛盾。", "无上": "正确：无上表示最高、没有更高，与“光荣”搭配，符合句意。", "无聊": "语义：“无聊”与“光荣”的褒义相反，句意不通。", "耻辱": "语义：“耻辱”与“光荣”正相反，与句中“为国家工作”的正面语境相悖。"}, "sentence_index": 0, "correct_answer": "无上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故造成了无上的损失。", "explanation": "这里把〈无上〉当成“极大、很多”来用，但〈无上〉表示最高、没有更高，只用于荣誉、快乐等正面事物；损失应用〈巨大〉。"}, {"text": "他对朋友表示无上的歉意。", "explanation": "这里把〈无上〉当成“程度很深”来用，但〈无上〉表示最高，不修饰歉意这类情感；应用〈深深〉。"}, {"text": "这份工作给她带来了无上的负担。", "explanation": "这里把〈无上〉当成“极重”来用，但〈无上〉表示最高，不用于负担；应用〈沉重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通", "is_correct": false, "explanation": "语义：神的智慧不会是“普通的”，与句中“神”的身份相矛盾。"}, {"text": "无上", "is_correct": true, "explanation": "正确：无上表示最高，与“神”的智慧相符，符合句意。"}, {"text": "廉价", "is_correct": false, "explanation": "搭配：“智慧”不说“廉价的”，搭配不当。"}, {"text": "粗浅", "is_correct": false, "explanation": "语义：“粗浅”与“神”的智慧相悖，句意不通。"}], "explanations": {"普通": "语义：神的智慧不会是“普通的”，与句中“神”的身份相矛盾。", "无上": "正确：无上表示最高，与“神”的智慧相符，符合句意。", "廉价": "搭配：“智慧”不说“廉价的”，搭配不当。", "粗浅": "语义：“粗浅”与“神”的智慧相悖，句意不通。"}, "sentence_index": 6, "correct_answer": "无上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份礼物对我来说是很无上的快乐。", "explanation": "这里把〈无上〉当成可以分程度的形容词来用，说成“程度更深”的样子；〈无上〉本身已是最高，应直接说〈无上的快乐〉。"}, {"text": "我的成绩比他更无上。", "explanation": "这里把〈无上〉当成可以比较高低的形容词来用；〈无上〉已是最高，没有“比别人更高”的比较。"}, {"text": "这件事对他来说是非常无上的荣誉。", "explanation": "这里把〈无上〉当成可以分程度的形容词来用，说成“程度极高”；〈无上〉本身已是最高，不分程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "能为学校做事，是他无上地荣誉。", "corrected_sentence": "能为学校做事，是他无上的荣誉。", "error_description": "“无上”修饰名词“荣誉”时应用“的”，不能用“地”（“地”多用于修饰动词或形容词）。错误在于用了“地”，应改为“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在父亲眼里，我的成长是很无上的喜悦。", "corrected_sentence": "在父亲眼里，我的成长是无上的喜悦。", "error_description": "“无上”表示最高、没有更高，本身不分程度，不能用“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
