INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门做研究的人。", "primary_collocate": null, "pronunciation": "yán jiū yuán", "ipa": "jɛn˧˥ tɕjoʊ˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "他想长大后做研究员。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位研究员每天都在图书馆看书。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究员需要很有耐心。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从大学毕业后成了研究员。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究员们正在开会。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我认识一位研究员，他研究海洋。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个研究员说，实验还没有结束。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做研究员要会写论文。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "研究员找到了新的办法。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老研究员对年轻人很好。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副研究员", "label": "复合"}, {"form": "助理研究员", "label": "复合"}, {"form": "研究員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以做研究为专门工作的人；指一种职业或人的类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孩", "is_correct": false, "explanation": "语义：“小孩”不是职业，“长大后做小孩”说不通。"}, {"text": "研究员", "is_correct": true, "explanation": "“做研究员”指以研究为职业，符合“长大后做”的职业语境。"}, {"text": "废物", "is_correct": false, "explanation": "语域：“废物”是贬义骂人的词，不能用作职业理想。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：“妻子”指女性配偶，与主语“他”不符。"}], "explanations": {"小孩": "语义：“小孩”不是职业，“长大后做小孩”说不通。", "研究员": "“做研究员”指以研究为职业，符合“长大后做”的职业语境。", "废物": "语域：“废物”是贬义骂人的词，不能用作职业理想。", "妻子": "语义：“妻子”指女性配偶，与主语“他”不符。"}, "sentence_index": 0, "correct_answer": "研究员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她从大学毕业后读了研究员。", "explanation": "这里应该用〈研究生〉。“读”后接的是在校学习的对象，研究员是已经工作的专业人员，应说“读研究生”。"}, {"text": "她们学校来了一张研究员。", "explanation": "这里应该用〈位〉或〈名〉。研究员指人，量词要用“位”或“名”，不能用“张”。"}, {"text": "她从大学毕业后进了研究员。", "explanation": "这里应该用〈研究所〉。研究员指人，进入的地方要说“研究所”，不能说“进了研究员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狗", "is_correct": false, "explanation": "语义：狗不会说话，不能作“说”的主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不能“说”话。"}, {"text": "研究员", "is_correct": true, "explanation": "“那个研究员说”指一位研究人员发言，与“说”和报告内容都相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会说话，不能作“说”的主语。"}], "explanations": {"狗": "语义：狗不会说话，不能作“说”的主语。", "窗户": "语义：窗户是无生命的物体，不能“说”话。", "研究员": "“那个研究员说”指一位研究人员发言，与“说”和报告内容都相符。", "椅子": "语义：椅子不会说话，不能作“说”的主语。"}, "sentence_index": 6, "correct_answer": "研究员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位研究员每天在电视台播报新闻。", "explanation": "这里应该用〈主播〉。在电视台播报新闻的是主播，研究员从事研究工作，不承担播报工作。"}, {"text": "那位研究员每天在店里为客人量尺寸、做衣服。", "explanation": "这里应该用〈裁缝〉。量尺寸、做衣服的是裁缝，研究员从事研究工作，不做这类手艺活。"}, {"text": "那位研究员每天在门口为学生检票。", "explanation": "这里应该用〈检票员〉。在门口为学生检票的是检票员，研究员从事研究工作，不做这类工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他叔叔是一只研究员。", "corrected_sentence": "他叔叔是一名研究员。", "error_description": "“研究员”指人，量词应用“名”或“位”，不能用“只”；这是把动物量词套用到人身上的常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都是研究员们。", "corrected_sentence": "我们都是研究员。", "error_description": "“研究员”在“是”后面作谓语时不能加“们”，复数已由主语“我们”和“都”表示，应说“我们都是研究员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
