INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事研究工作的专业人员。", "primary_collocate": null, "pronunciation": "yán jiū yuán", "ipa": "jɛn˧˥ tɕjoʊ˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "她是一位研究员。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位研究员在实验室工作。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究员每天都要看很多资料。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥是一名研究员，他在研究所工作。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究员正在写一份报告。", "target_word": "研究员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位研究员发表了三篇文章。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司请了一位研究员来给大家讲课。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了十年研究员。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究员把结果告诉了大家。", "target_word": "研究员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家研究所有二十多名研究员。", "target_word": "研究员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副研究员", "label": "复合"}, {"form": "助理研究员", "label": "复合"}, {"form": "研究員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在研究所、大学或公司里从事研究工作的专业人员；强调职业身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
